// Generated by tools/build-data.js on 2026-10-25 from the JSON files in this folder. Do not edit.
window.ATLAS_SUMMARIES = {"beatles":{"title":"The Beatles","desc":"English rock band (1960–1970)","text":"The Beatles were an English rock band formed in Liverpool in 1960. The band comprised John Lennon, Paul McCartney, George Harrison and Ringo Starr. They are regarded as the most influential band in popular music and were integral to the development of 1960s counterculture and the recognition of popular music as an art form. Rooted in skiffle, beat and 1950s rock 'n' roll, their sound incorporated elements of classical music and traditional pop in innovative ways.","url":"https://en.wikipedia.org/wiki/The_Beatles"},"stones":{"title":"The Rolling Stones","desc":"English rock band","text":"The Rolling Stones are an English rock band formed in 1962. Active for over six decades, they are one of the most popular, influential, and enduring bands of the rock era. In the early 1960s, the band pioneered the gritty, rhythmically driven sound that came to define hard rock.","url":"https://en.wikipedia.org/wiki/The_Rolling_Stones"},"who":{"title":"The Who","desc":"English rock band","text":"The Who are an English rock band formed in London in 1964. Their classic lineup (1964–1978) consisted of lead vocalist Roger Daltrey, guitarist Pete Townshend, bassist John Entwistle, and drummer Keith Moon.","url":"https://en.wikipedia.org/wiki/The_Who"},"velvet":{"title":"The Velvet Underground","desc":"American rock band","text":"The Velvet Underground was an American rock band formed in New York City in 1964. They became known for their integration of rock and roll and the avant-garde, which earned them little commercial success during their initial nine-year run but made them one of the most influential bands of their era, particularly in underground, experimental, and alternative music scenes. Their provocative subject matter and experimentation were instrumental in the development of punk rock, new wave and other genres.","url":"https://en.wikipedia.org/wiki/The_Velvet_Underground"},"mc5":{"title":"MC5","desc":"American rock band","text":"MC5 was an American rock band formed in Lincoln Park, Michigan, in 1963. The classic lineup consisted of vocalist Rob Tyner, guitarists Wayne Kramer and Fred \"Sonic\" Smith, bassist Michael Davis, and drummer Dennis Thompson. MC5 were listed by Parade as one of the best rock bands of all time and by VH1 as one of the greatest hard rock artists of all time. The band's music is widely recognized as influential, and their 1969 song \"Kick Out the Jams\" has been covered by many artists.","url":"https://en.wikipedia.org/wiki/MC5"},"doors":{"title":"The Doors","desc":"American rock band","text":"The Doors were an American rock band formed in Los Angeles in 1965, comprising vocalist Jim Morrison, keyboardist Ray Manzarek, guitarist Robby Krieger, and drummer John Densmore. They are considered one of the most innovative, influential and eclectic rock bands in history, primarily due to their pioneering experimentation with a great variety of musical styles and techniques and Morrison's poetic lyrics and evocative voice.","url":"https://en.wikipedia.org/wiki/The_Doors"},"floyd":{"title":"Pink Floyd","desc":"English rock band","text":"Pink Floyd are an English rock band formed in London in 1965 by Syd Barrett, Nick Mason (drums), Roger Waters and Richard Wright. David Gilmour joined in 1967. Gaining an early underground following as one of the first British psychedelic groups, Pink Floyd were distinguished by their extended compositions, sonic experiments, philosophical lyrics, and elaborate live performances, becoming a leading progressive rock band.","url":"https://en.wikipedia.org/wiki/Pink_Floyd"},"cream":{"title":"Cream (band)","desc":"English rock supergroup","text":"Cream were a British rock supergroup formed in London in 1966. The group consisted of bassist Jack Bruce, guitarist Eric Clapton, and drummer Ginger Baker. Bruce was the primary songwriter and vocalist, although Clapton and Baker contributed to songs. Formed by members of previously successful bands, they are widely considered to be the first so-called supergroup in rock history.","url":"https://en.wikipedia.org/wiki/Cream_(band)"},"hendrix":{"title":"Jimi Hendrix","desc":"American guitarist (1942–1970)","text":"James Marshall \"Jimi\" Hendrix was an American guitarist and singer-songwriter. He is widely regarded as one of the greatest and most influential guitarists of all time. He was inducted into the Rock and Roll Hall of Fame in 1992 as a part of his band, the Jimi Hendrix Experience; the institution describes him as \"arguably the greatest instrumentalist in the history of rock music\".","url":"https://en.wikipedia.org/wiki/Jimi_Hendrix"},"stooges":{"title":"The Stooges","desc":"American punk rock band","text":"The Stooges were an American rock band formed in Ann Arbor, Michigan, in 1967 by singer Iggy Pop, guitarist Ron Asheton, drummer Scott Asheton, and bassist Dave Alexander. Initially playing a raw, primitive style of rock and roll, the band sold few records in their original incarnation and gained a reputation for their confrontational performances, which sometimes involved acts of stage diving and self-mutilation by Iggy Pop.","url":"https://en.wikipedia.org/wiki/The_Stooges"},"sabbath":{"title":"Black Sabbath","desc":"English heavy metal band","text":"Black Sabbath were an English heavy metal band formed in Birmingham in 1968 by guitarist Tony Iommi, drummer Bill Ward, bassist Geezer Butler and vocalist Ozzy Osbourne. After adopting the Black Sabbath name in 1969, they distinguished themselves through occult themes with horror-inspired lyrics and down-tuned guitars. Their first three albums, Black Sabbath, Paranoid, and Master of Reality (1971), were commercially successful, and are cited as pioneering albums in the development of heavy metal.","url":"https://en.wikipedia.org/wiki/Black_Sabbath"},"zeppelin":{"title":"Led Zeppelin","desc":"English rock band (1968–1980)","text":"Led Zeppelin were an English rock band formed in London in 1968. The band comprised vocalist Robert Plant, guitarist Jimmy Page, bass-guitarist and keyboardist John Paul Jones and drummer John Bonham. Their combination of a heavy electric-guitar sound with elements of blues and folk music popularised album-oriented rock and stadium rock and established them as the progenitor of hard rock and heavy metal.","url":"https://en.wikipedia.org/wiki/Led_Zeppelin"},"purple":{"title":"Deep Purple","desc":"British rock band","text":"Deep Purple are a British rock band formed in London in 1968. They are considered to be among the pioneers of heavy metal and modern hard rock, although their musical style has varied throughout their career. Originally formed as a psychedelic rock and progressive rock band, they shifted to a heavier sound with their 1970 album Deep Purple in Rock.","url":"https://en.wikipedia.org/wiki/Deep_Purple"},"bluecheer":{"title":"Blue Cheer","desc":"American rock band","text":"Blue Cheer was an American rock band that initially performed and recorded in the late 1960s and early 1970s and was sporadically active until 2009. Based in San Francisco, Blue Cheer played in a psychedelic blues rock or acid rock style. They are also credited as being some of the earliest pioneers of heavy metal, with their cover of \"Summertime Blues\" sometimes cited as the first in the genre.","url":"https://en.wikipedia.org/wiki/Blue_Cheer"},"queen":{"title":"Queen (band)","desc":"British rock band","text":"Queen are a British rock band formed in London in 1970 by Freddie Mercury, Brian May, and Roger Taylor, and later joined by John Deacon (bass). Their earliest works were influenced by progressive rock, hard rock and heavy metal, but the band gradually ventured into more conventional and radio-friendly works by incorporating further styles, such as arena rock and pop rock.","url":"https://en.wikipedia.org/wiki/Queen_(band)"},"aerosmith":{"title":"Aerosmith","desc":"American rock band","text":"Aerosmith is an American rock band formed in Boston in 1970. The group consists of lead vocalist Steven Tyler, bassist Tom Hamilton, drummer Joey Kramer, and guitarists Joe Perry and Brad Whitford. Their style, which is rooted in blues-based hard rock, has also incorporated elements of pop rock, heavy metal, glam metal, and rhythm and blues, and has inspired many subsequent rock artists.","url":"https://en.wikipedia.org/wiki/Aerosmith"},"vanhalen":{"title":"Van Halen","desc":"American rock band (1972–1999; 2003–2020)","text":"Van Halen was an American rock band formed in Pasadena, California, in 1972. Credited with restoring hard rock to the forefront of the music scene, Van Halen was known for their energetic live performances and the virtuosity of their guitarist, Eddie Van Halen.","url":"https://en.wikipedia.org/wiki/Van_Halen"},"kiss":{"title":"Kiss (band)","desc":"American rock band","text":"Kiss was an American rock band formed in New York City in 1973 by Paul Stanley, Gene Simmons, Ace Frehley and Peter Criss. Known for their face paint and stage outfits, the group rose to prominence in the mid-1970s with shock rock–style live performances that featured fire-breathing, blood-spitting, smoking guitars, shooting rockets, levitating drum kits and pyrotechnics.","url":"https://en.wikipedia.org/wiki/Kiss_(band)"},"acdc":{"title":"AC/DC","desc":"Australian rock band","text":"AC/DC are an Australian rock band formed in Sydney in 1973. Their music has been variously described as hard rock, blues rock and heavy metal, although the band calls it simply \"rock and roll\". They are cited as a formative influence on the new wave of British heavy metal bands, such as Def Leppard and Saxon, and were among \"the second generation of rising stars ready to step into the breach as the old guard waned\", according to critics.","url":"https://en.wikipedia.org/wiki/AC%2FDC"},"motorhead":{"title":"Motörhead","desc":"English rock band (1975–2015)","text":"Motörhead were an English rock band formed in London in 1975 by bassist and lead vocalist Lemmy Kilmister, guitarist Larry Wallis and drummer Lucas Fox. Kilmister was the primary songwriter and only constant member. The band are often considered a precursor to the new wave of British heavy metal, which re-energised heavy metal in the late 1970s and early 1980s.","url":"https://en.wikipedia.org/wiki/Mot%C3%B6rhead"},"ratt":{"title":"Ratt","desc":"American glam metal band","text":"Ratt was an American glam metal band that had significant commercial success in the 1980s, with their albums having been certified as gold, platinum and multi-platinum by the RIAA. The group is perhaps best known for hit singles such as \"Round and Round\" and \"Lay It Down\", tracks that ranked on Billboard's top 40 at No. 12 and No. 40, respectively, as well as other songs such as \"Wanted Man\", \"You're in Love\" and \"Dance\".","url":"https://en.wikipedia.org/wiki/Ratt"},"twisted":{"title":"Twisted Sister","desc":"American heavy metal and glam rock band","text":"Twisted Sister is an American heavy metal band formed in 1972 in Ho-Ho-Kus, New Jersey, and later based on Long Island, New York. Their best-known songs include \"We're Not Gonna Take It\" and \"I Wanna Rock\", both of which were associated with music videos noted for their sense of slapstick humour. Besides their music, the band is equally remembered for their hairstyles and for wearing androgynous clothing and makeup, leading to their categorization in the hair metal scene of the 1980s.","url":"https://en.wikipedia.org/wiki/Twisted_Sister"},"motley":{"title":"Mötley Crüe","desc":"American heavy metal band","text":"Mötley Crüe is an American heavy metal band formed in Hollywood, California, in 1981 by bassist Nikki Sixx and drummer Tommy Lee, with guitarist Mick Mars and lead vocalist Vince Neil joining right after. The band has sold over 100 million records worldwide. They have achieved seven platinum or multi-platinum certifications, nine Top 10 albums on the Billboard 200 chart, twenty-two Top 40 mainstream rock hits, and six Top 20 pop singles.","url":"https://en.wikipedia.org/wiki/M%C3%B6tley_Cr%C3%BCe"},"poison":{"title":"Poison (band)","desc":"American rock band","text":"Poison was an American rock band formed in Mechanicsburg, Pennsylvania in 1983. C. DeVille. The band achieved huge commercial success in the mid-1980s through the mid-1990s and sold over 65 million records and DVDs worldwide. In 2012, VH1 ranked them at No. 1 on their list of the \"Top 5 Hair Bands of the '80s\".","url":"https://en.wikipedia.org/wiki/Poison_(band)"},"bonjovi":{"title":"Bon Jovi","desc":"American rock band","text":"Bon Jovi is an American rock band formed in Sayreville, New Jersey in 1983. The band consists of singer Jon Bon Jovi, keyboardist David Bryan, drummer Tico Torres, guitarists John Shanks and Phil X, percussionist Everett Bradley, and bassist Hugh McDonald. Original bassist Alec John Such left the band in 1994, and longtime guitarist and co-songwriter Richie Sambora left in 2013.","url":"https://en.wikipedia.org/wiki/Bon_Jovi"},"ramones":{"title":"Ramones","desc":"American punk rock band (1974–1996)","text":"The Ramones were an American punk rock band formed in the New York City neighborhood Forest Hills, Queens, in 1974. Known for helping establish the punk movement in the United States and elsewhere, the Ramones are often recognized as one of the first bands of the genre. Although they never achieved significant commercial success during their existence, the band is highly influential in punk culture.","url":"https://en.wikipedia.org/wiki/Ramones"},"pistols":{"title":"Sex Pistols","desc":"English punk rock band","text":"The Sex Pistols are an English punk rock band formed in London in 1975. Although their initial career lasted just two and a half years, they became culturally influential in popular music. The band initiated the punk movement in the United Kingdom, with their clothes and hairstyles becoming a significant influence on the punk subculture and fashion.","url":"https://en.wikipedia.org/wiki/Sex_Pistols"},"clash":{"title":"The Clash","desc":"English punk rock band (1976–1986)","text":"The Clash were an English rock band formed in London in 1976. Billed as \"The Only Band That Matters\", they are considered one of the most influential acts in the original wave of British punk rock, with their music fusing elements of reggae, dub, funk, ska and rockabilly. The band also contributed to the post-punk and new wave movements that followed.","url":"https://en.wikipedia.org/wiki/The_Clash"},"blackflag":{"title":"Black Flag (band)","desc":"American hardcore punk band","text":"Black Flag is an American punk rock band formed in 1976 in Hermosa Beach, California. The band was founded as Panic by guitarist Greg Ginn, and singer Keith Morris. They are widely considered to be one of the first hardcore punk bands, as well as one of the pioneers of post-hardcore.","url":"https://en.wikipedia.org/wiki/Black_Flag_(band)"},"misfits":{"title":"Misfits (band)","desc":"American punk band","text":"The Misfits are an American punk rock band, often recognized as pioneers of the horror punk subgenre, blending punk and other musical influences with horror film themes and imagery. The group was formed in 1977 in Lodi, New Jersey, by vocalist, songwriter, and keyboardist Glenn Danzig. Shortly after, bassist Jerry Only joined, and the pair remained the core members through numerous personnel changes over the next six years.","url":"https://en.wikipedia.org/wiki/Misfits_(band)"},"discharge":{"title":"Discharge (band)","desc":"English punk band","text":"Discharge are an English hardcore punk band formed in 1977 in Stoke-on-Trent, Staffordshire. The band is known for influencing several sub-genres of extreme music and their songs have been covered by many notable artists in heavy metal and other genres. The musical sub-genre of D-beat is named after Discharge and the band's distinctive drumbeat.","url":"https://en.wikipedia.org/wiki/Discharge_(band)"},"badbrains":{"title":"Bad Brains","desc":"American punk band","text":", in 1976. They are widely regarded as pioneers of hardcore punk, though the band's members have objected to the use of this term to describe their music. They are also a reggae band, while later recordings featured elements of other genres like funk, heavy metal, hip-hop, and soul.","url":"https://en.wikipedia.org/wiki/Bad_Brains"},"deadkennedys":{"title":"Dead Kennedys","desc":"American punk band","text":"Dead Kennedys are an American punk rock band that formed in San Francisco, California, in 1978. The band was one of the defining bands of the American punk scene during the band's initial eight-year run.","url":"https://en.wikipedia.org/wiki/Dead_Kennedys"},"minorthreat":{"title":"Minor Threat","desc":"American hardcore punk band (1980–1983)","text":", by vocalist Ian MacKaye and drummer Jeff Nelson. MacKaye and Nelson had played in several other bands together, and recruited bassist Brian Baker and guitarist Lyle Preslar to form Minor Threat. They added a fifth member, Steve Hansgen, in 1982, playing bass, while Baker switched to second guitar.","url":"https://en.wikipedia.org/wiki/Minor_Threat"},"suicidal":{"title":"Suicidal Tendencies","desc":"American crossover thrash band","text":"Suicidal Tendencies is an American hardcore punk/crossover thrash band, formed in 1980 in Venice, Los Angeles, California, by vocalist Mike Muir. The band has undergone various lineup changes, with Muir as the only constant and sole remaining original member. Their current lineup includes Muir, guitarists Dean Pleasants and Ben Weinman, bassist Tye Trujillo, and drummer Xavier \"X\" Ware.","url":"https://en.wikipedia.org/wiki/Suicidal_Tendencies"},"dri":{"title":"Dirty Rotten Imbeciles","desc":"American crossover thrash band","text":"Dirty Rotten Imbeciles are an American crossover thrash band that formed in Houston, Texas in 1982 and would later relocate to San Francisco, California. The band is currently composed of two of its founding members, lead vocalist Kurt Brecht and guitarist Spike Cassidy, as well as bassist Greg Orr and drummer Danny Walker.","url":"https://en.wikipedia.org/wiki/Dirty_Rotten_Imbeciles"},"scorpions":{"title":"Scorpions (band)","desc":"German rock band","text":"The Scorpions are a German hard rock/heavy metal band formed in Hanover in 1965 by guitarist Rudolf Schenker. The longest-running and most successful line-up of the band included Schenker, Klaus Meine (vocals), Matthias Jabs, Francis Buchholz (bass), and Herman Rarebell (drums), and lasted from 1978 to 1992.","url":"https://en.wikipedia.org/wiki/Scorpions_(band)"},"priest":{"title":"Judas Priest","desc":"English heavy metal band","text":"Judas Priest are an English heavy metal band formed in Birmingham in 1969. They have sold over 50 million albums and are frequently ranked as one of the greatest metal bands of all time. They have been referred to as one of the pioneers of the new wave of British heavy metal (NWOBHM) movement, and cited as a formative influence on metal subgenres, including speed metal, thrash metal, and power metal, as well as the hard rock and glam metal scenes of the 1980s.","url":"https://en.wikipedia.org/wiki/Judas_Priest"},"iron":{"title":"Iron Maiden","desc":"English heavy metal band","text":"Iron Maiden are an English heavy metal band formed in Leyton, East London, in 1975 by bassist and primary songwriter Steve Harris. Although fluid in the early years of the band, the line-up for most of the band's history has consisted of Harris, lead vocalist Bruce Dickinson, drummer Nicko McBrain, and guitarists Dave Murray, Adrian Smith and Janick Gers.","url":"https://en.wikipedia.org/wiki/Iron_Maiden"},"rainbow":{"title":"Rainbow (rock band)","desc":"English rock band","text":"Rainbow were a British hard rock band formed in Hertford in 1975 by guitarist Ritchie Blackmore. Established in the aftermath of Blackmore's first departure from Deep Purple, Rainbow originally featured four members of the American rock band Elf, including their singer Ronnie James Dio, but after their self-titled debut album, Blackmore fired these members, except Dio, recruiting drummer Cozy Powell, bassist Jimmy Bain, and keyboardist Tony Carey.","url":"https://en.wikipedia.org/wiki/Rainbow_(rock_band)"},"saxon":{"title":"Saxon (band)","desc":"British heavy metal band","text":"Saxon are an English heavy metal band formed in Barnsley in 1975. As leaders of the new wave of British heavy metal (NWOBHM), they had eight UK Top 40 albums in the 1980s, including four UK Top 10 albums and two Top 5 albums. They had numerous hit singles on the UK Singles Chart and achieved success across Europe, South America, and Japan, as well as in the United States and Canada.","url":"https://en.wikipedia.org/wiki/Saxon_(band)"},"accept":{"title":"Accept (band)","desc":"German heavy metal band","text":"Accept is a German heavy metal band from Solingen, formed in 1976 with their first consistent lineup featuring lead singer Udo Dirkschneider, lead guitarist Wolf Hoffmann, bassist Peter Baltes, rhythm guitarist Jörg Fischer and drummer Stefan Kaufmann. Their current lineup consists of Hoffmann, vocalist Mark Tornillo, guitarist Philip Shouse, drummer Christopher Williams and bassist Martin Motnik.","url":"https://en.wikipedia.org/wiki/Accept_(band)"},"diamondhead":{"title":"Diamond Head (British band)","desc":"British heavy metal band","text":"Diamond Head are an English heavy metal band formed in Stourbridge, West Midlands, in 1976. They were part of the new wave of British heavy metal movement and are cited by bands such as Metallica and Megadeth as a significant early influence. The original members were schoolfriends Brian Tatler (guitarist) and Duncan Scott (drummer), who were joined by singer Sean Harris in the same year, and bass player Collin Kimberley in 1978.","url":"https://en.wikipedia.org/wiki/Diamond_Head_(British_band)"},"defleppard":{"title":"Def Leppard","desc":"English rock band","text":"Def Leppard are an English rock band formed in Sheffield in 1976. Since 1992, the band has consisted of Rick Savage, Joe Elliott, Rick Allen (drums), Phil Collen, and Vivian Campbell. They established themselves as part of the new wave of British heavy metal of the early 1980s.","url":"https://en.wikipedia.org/wiki/Def_Leppard"},"ozzy":{"title":"Ozzy Osbourne","desc":"English musician and media personality (1948–2025)","text":"John Michael \"Ozzy\" Osbourne was an English singer, songwriter, and media personality. Dubbed the \"Prince of Darkness\", he co-founded the heavy metal band Black Sabbath in 1968 and rose to prominence in the 1970s as their lead vocalist. Black Sabbath is widely credited as a pioneer of heavy metal music. He performed on the band's first eight studio albums, including Black Sabbath, Paranoid and Master of Reality (1971), before he was sacked in 1979 due to his problems with alcohol and other drugs.","url":"https://en.wikipedia.org/wiki/Ozzy_Osbourne"},"mercyful":{"title":"Mercyful Fate","desc":"Danish heavy metal band","text":"Mercyful Fate is a Danish heavy metal band from Copenhagen, formed in 1981 by vocalist King Diamond and guitarist Hank Shermann. Influenced by progressive rock and hard rock, and with lyrics dealing with LaVeyan Satanism and the occult, Mercyful Fate was part of the first wave of black metal in the early to mid-1980s, along with Venom and Bathory. The band is also cited as a formative influence to the then-nascent genres of thrash metal and death metal, as well as the Norwegian black metal scene.","url":"https://en.wikipedia.org/wiki/Mercyful_Fate"},"dio":{"title":"Dio (band)","desc":"American heavy metal band (1982–2010)","text":"Dio was an American heavy metal band formed in 1982 and led by vocalist Ronnie James Dio. Dio left Black Sabbath with intentions to form a new band with fellow former Black Sabbath member, drummer Vinny Appice. The band released ten studio albums and had numerous lineup changes over the years, with Dio himself being the only constant member. Guitarists included Vivian Campbell, Craig Goldy, Doug Aldrich, Warren DeMartini, Tracy G, Jake E.","url":"https://en.wikipedia.org/wiki/Dio_(band)"},"exodus":{"title":"Exodus (band)","desc":"American thrash metal band","text":"Exodus is an American thrash metal band formed in 1979 in Richmond, California. Their current lineup consists of guitarists Gary Holt and Lee Altus, bassist Jack Gibson, drummer Tom Hunting and lead vocalist Rob Dukes. Notable former members include vocalists Paul Baloff and Steve \"Zetro\" Souza, drummers John Tempesta and Paul Bostaph, and founding guitarist Kirk Hammett, who later joined fellow Bay Area thrash metal band Metallica.","url":"https://en.wikipedia.org/wiki/Exodus_(band)"},"overkill":{"title":"Overkill (band)","desc":"American thrash metal band","text":"Overkill is an American thrash metal band, formed in 1980 in New Jersey. D. Verni and lead vocalist Bobby \"Blitz\" Ellsworth as the only remaining original members. The band's current lineup includes Verni, Ellsworth, Dave Linsk on lead guitar, Derek \"The Skull\" Tailer on rhythm guitar, and Jeramie Kling on drums. Notable former members include guitarists Dan Spitz, Bobby Gustafson, Merritt Gant and Joe Comeau, and drummers Rat Skates and Jason Bittner.","url":"https://en.wikipedia.org/wiki/Overkill_(band)"},"metallica":{"title":"Metallica","desc":"American heavy metal band","text":"Metallica is an American heavy metal band. It was formed in Los Angeles in 1981 by vocalist/guitarist James Hetfield and drummer Lars Ulrich, and has been based in San Francisco for most of its career. The band's fast tempos, instrumentals and aggressive musicianship made them one of the founding \"big four\" bands of thrash metal, alongside Megadeth, Anthrax, and Slayer.","url":"https://en.wikipedia.org/wiki/Metallica"},"slayer":{"title":"Slayer","desc":"American thrash metal band","text":"Slayer is an American thrash metal band from Huntington Park, California, formed in 1981 by guitarists Kerry King and Jeff Hanneman, drummer Dave Lombardo and vocalist/bassist Tom Araya. Slayer's fast and aggressive musical style made them one of the \"big four\" bands of thrash metal, alongside Metallica, Megadeth, and Anthrax.","url":"https://en.wikipedia.org/wiki/Slayer"},"anthrax":{"title":"Anthrax (American band)","desc":"American heavy metal band","text":"Anthrax is an American heavy metal band from New York City, formed in 1981 by rhythm guitarist Scott Ian and bassist Dan Lilker. The group is considered one of the leaders of the thrash metal scene from the 1980s and is part of the \"Big Four\" of the genre, along with Metallica, Megadeth and Slayer. They were also one of the first thrash metal bands to emerge from the East Coast.","url":"https://en.wikipedia.org/wiki/Anthrax_(American_band)"},"sodom":{"title":"Sodom (band)","desc":"German thrash metal band","text":"Sodom is a German thrash metal band from Gelsenkirchen, formed in 1982. They have gone through various line-up changes. Bassist/vocalist Thomas 'Tom Angelripper' Such is the only constant member. The band is currently composed of Such, guitarists Frank \"Blackfire\" Gosdzik and Yorck Segatz, and drummer Toni Merkel. Sodom has been referred to as one of the \"Big Four\" of Teutonic thrash metal, along with Kreator, Destruction and Tankard.","url":"https://en.wikipedia.org/wiki/Sodom_(band)"},"kreator":{"title":"Kreator","desc":"German thrash metal band","text":"Kreator is a German thrash metal band from Essen, formed in 1982. Their current line-up consists of lead vocalist and rhythm guitarist Miland \"Mille\" Petrozza, drummer Jürgen \"Ventor\" Reil, lead guitarist Sami Yli-Sirniö, and bassist Frédéric Leclercq. The band's line-up has changed multiple times throughout its 44-year career, most noticeably their bassists and lead guitarists.","url":"https://en.wikipedia.org/wiki/Kreator"},"destruction":{"title":"Destruction (band)","desc":"German thrash metal band","text":"Destruction is a German thrash metal band formed in 1982. They have been credited as one of the \"Big Four\" of the German thrash metal scene, alongside Kreator, Sodom and Tankard.","url":"https://en.wikipedia.org/wiki/Destruction_(band)"},"megadeth":{"title":"Megadeth","desc":"American heavy metal band","text":"Megadeth is an American heavy metal band formed in Los Angeles in 1983 by vocalist and guitarist Dave Mustaine. Known for their technically complex guitar work and musicianship, Megadeth is one of the \"big four\" of American thrash metal—along with Slayer, Anthrax, and Metallica—and is credited with helping to develop and popularize the genre.","url":"https://en.wikipedia.org/wiki/Megadeth"},"testament":{"title":"Testament (band)","desc":"American thrash metal band","text":"Testament is an American thrash metal band from Berkeley, California. Formed in 1983 under the name Legacy, the band's current lineup includes rhythm guitarist Eric Peterson, lead vocalist Chuck Billy, lead guitarist Alex Skolnick, bassist Steve Di Giorgio and drummer Chris Dovas. Testament has experienced many lineup changes over the years, with Peterson being the only remaining original member.","url":"https://en.wikipedia.org/wiki/Testament_(band)"},"sepultura":{"title":"Sepultura","desc":"Brazilian heavy metal band","text":"Sepultura is a Brazilian heavy metal band from Belo Horizonte, formed in 1984 by brothers Max and Igor Cavalera. They were a major force in the groove metal, thrash metal and death metal genres during the late 1980s and early 1990s, and were also an integral part of the sound of deathrash. Their style has changed over the years, with the band merging its sound with influences and textures of alternative metal, world music, nu metal, progressive rock, hardcore punk, and industrial metal.","url":"https://en.wikipedia.org/wiki/Sepultura"},"pantera":{"title":"Pantera","desc":"American heavy metal band","text":"Pantera is an American heavy metal band formed in Arlington, Texas, in 1981 by the Abbott brothers, and currently composed of vocalist Phil Anselmo, bassist Rex Brown, and touring musicians Zakk Wylde and Charlie Benante. The group's best-known lineup consisted of the Abbott brothers along with Brown and Anselmo, who joined in 1982 and 1986, respectively. The band is credited for developing and popularizing the subgenre of groove metal in the 1990s.","url":"https://en.wikipedia.org/wiki/Pantera"},"napalm":{"title":"Napalm Death","desc":"English grindcore band","text":"Napalm Death are an English grindcore band formed in Meriden, West Midlands, in 1981. The band currently consists of Barney Greenway on vocals, Shane Embury on bass guitar, John Cooke on guitar and Danny Herrera on drums. None of the founding band members remain in the band. From 1989 to 2004, Napalm Death were a five-piece band after they added Jesse Pintado and Mitch Harris as replacements for guitarist Bill Steer.","url":"https://en.wikipedia.org/wiki/Napalm_Death"},"possessed":{"title":"Possessed (band)","desc":"American death metal band","text":"Possessed is an American death metal band formed in 1982 in the San Francisco Bay Area. Noted for their fast playing style and Jeff Becerra's growled vocals, they are often called the first death metal band, and paved the way for the 1980s Bay Area thrash metal scene, along with Metallica, Exodus, Testament and Death Angel. The band is notable for featuring then-teenage guitarist Larry LaLonde, who went on to join Primus.","url":"https://en.wikipedia.org/wiki/Possessed_(band)"},"death":{"title":"Death (metal band)","desc":"American death metal band","text":"Death was an American death metal band formed in Altamonte Springs, Florida, in 1983 by guitarist Chuck Schuldiner, drummer/vocalist Kam Lee, and guitarist Rick Rozz. Formed out of what would become the Florida death metal scene, Death is considered a pioneering death metal band. The band's 1987 debut album, Scream Bloody Gore, is regarded as one of the first death metal records, alongside the first records from Possessed and Necrophagia.","url":"https://en.wikipedia.org/wiki/Death_(metal_band)"},"morbidangel":{"title":"Morbid Angel","desc":"American death metal band","text":"Morbid Angel is an American death metal band based in Tampa, Florida, formed in 1983 by guitarist, primary composer and sole remaining original member Trey Azagthoth, vocalist and bassist Dallas Ward, and drummer Mike Browning. It was one of the first bands to incorporate guttural vocals, up-tempo blast beats, multiple tempo changes and a dark atmosphere.","url":"https://en.wikipedia.org/wiki/Morbid_Angel"},"repulsion":{"title":"Repulsion (band)","desc":"American grindcore band","text":"Repulsion is an American grindcore band from Flint, Michigan, founded in 1984 by Scott Carlson and Matt Olivo.","url":"https://en.wikipedia.org/wiki/Repulsion_(band)"},"obituary":{"title":"Obituary (band)","desc":"American death metal band","text":"Obituary is an American death metal band, formed in Tampa, Florida in 1984. Initially called Executioner, they were fundamental in the development of the death metal genre, and are one of the genre's most successful bands of all-time. Obituary has released eleven studio albums and, with the exception of a five-year hiatus from 1998 to 2003, they continue to perform live.","url":"https://en.wikipedia.org/wiki/Obituary_(band)"},"carcass":{"title":"Carcass (band)","desc":"British death metal band","text":"Carcass are an English death metal band from Liverpool, formed in 1985. The band have gone through several line-up changes. Guitarist Bill Steer and bassist-vocalist Jeff Walker are the only constant members. They broke up in 1996, but reformed in 2007 without original drummer Ken Owen, for health reasons. To date, the band have released seven studio albums, two compilation albums, four EPs, two demo albums, one video album, and six music videos.","url":"https://en.wikipedia.org/wiki/Carcass_(band)"},"boltthrower":{"title":"Bolt Thrower","desc":"English death metal band","text":"Bolt Thrower were a British death metal band from Coventry, England. They formed in 1986 and released their first album with Vinyl Solution in 1988. The band moved to Earache Records and became one of the label's best-selling bands. Their last label was Metal Blade Records. The band had a succession of members and toured Europe, the United States, and Australia. Over the course of their 30-year career, Bolt Thrower released eight studio albums, three EPs, one live album, three compilation albums and two demos.","url":"https://en.wikipedia.org/wiki/Bolt_Thrower"},"entombed":{"title":"Entombed (band)","desc":"Swedish death metal band","text":"Entombed is a Swedish death metal band formed in 1987 as Nihilist. Entombed began their career as an early pioneer of Scandinavian death metal, which differed from its American counterpart by its distinct \"buzzsaw\" guitar tone. Their sound evolved by the early-to-mid-1990s and the band began to explore progressive, punk, hard rock, garage rock, and groove metal influences, which shaped the sound of death 'n' roll.","url":"https://en.wikipedia.org/wiki/Entombed_(band)"},"cannibal":{"title":"Cannibal Corpse","desc":"American death metal band","text":"Cannibal Corpse is an American death metal band formed in Buffalo, New York, in 1988, now based in Tampa, Florida.","url":"https://en.wikipedia.org/wiki/Cannibal_Corpse"},"dismember":{"title":"Dismember (band)","desc":"Swedish death metal band","text":"Dismember is a Swedish death metal band from Stockholm, formed in 1988. They split up in 2011 and reunited in 2019. Pioneers of Swedish death metal, Dismember is considered one of the country's \"big four\", with Entombed, Grave, and Unleashed.","url":"https://en.wikipedia.org/wiki/Dismember_(band)"},"atthegates":{"title":"At the Gates","desc":"Swedish melodic death metal band","text":"At the Gates is a Swedish melodic death metal band from Gothenburg, formed in 1990. The band was a progenitor of the mid-90s Gothenburg Sound with Dark Tranquillity and In Flames. Prior to their first disbandment in 1996, At the Gates released four albums, the last being Slaughter of the Soul (1995). The album has been seen as a landmark in the mid-1990s Swedish death metal scene.","url":"https://en.wikipedia.org/wiki/At_the_Gates"},"inflames":{"title":"In Flames","desc":"Swedish heavy metal band","text":"In Flames is a Swedish heavy metal band from Gothenburg, formed in 1990. They are considered pioneers of the Gothenburg metal scene, which also includes bands such as At the Gates and Dark Tranquillity. Their lineup has changed several times. Vocalist Anders Fridén and lead guitarist Björn Gelotte are the only consistent members since 1995. Since the departure of Jesper Strömblad in 2010, no original members remain with the band.","url":"https://en.wikipedia.org/wiki/In_Flames"},"darktranq":{"title":"Dark Tranquillity","desc":"Swedish melodic death metal band","text":"Dark Tranquillity are a Swedish melodic death metal band from Gothenburg, formed in 1989. They are considered pioneers of the Gothenburg metal scene, which includes bands such as At the Gates and In Flames. After a nearly three-decade long collaboration of four founding members, frequent lineup changes between 2015-2021 have left vocalist Mikael Stanne as the only original member, together with long-time keyboardist Martin Brändström.","url":"https://en.wikipedia.org/wiki/Dark_Tranquillity"},"nile":{"title":"Nile (band)","desc":"American technical death metal band","text":"Nile is an American technical death metal band from Greenville, South Carolina, formed in 1993. The band's current lineup consists of founding guitarist/vocalist Karl Sanders, drummer George Kollias, guitarist/vocalist Brian Kingsland, guitarist/vocalist Zach Jeter, and bassist/vocalist Adam Roethlisberger. The band is known for their lyrics and music inspired by Egyptology and H.","url":"https://en.wikipedia.org/wiki/Nile_(band)"},"behemoth":{"title":"Behemoth (band)","desc":"Polish blackened death metal band","text":"Behemoth is a Polish blackened death metal band from Gdańsk, formed in 1991. They are considered important in establishing the Polish extreme metal underground with Vader and Hate.","url":"https://en.wikipedia.org/wiki/Behemoth_(band)"},"venom":{"title":"Venom (band)","desc":"British heavy metal band","text":"Venom were an English heavy metal band formed in Newcastle upon Tyne in 1978. Coming to prominence towards the end of the new wave of British heavy metal (NWOBHM), Venom's first two albums, Welcome to Hell (1981) and Black Metal (1982), are considered major influences on black metal, thrash metal and extreme metal in general.","url":"https://en.wikipedia.org/wiki/Venom_(band)"},"bathory":{"title":"Bathory (band)","desc":"Swedish extreme metal band","text":"Bathory was a Swedish extreme metal band formed in Vällingby in March 1983. Frontman and songwriter Thomas \"Quorthon\" Forsberg was the sole constant member, and at times responsible for all instruments.","url":"https://en.wikipedia.org/wiki/Bathory_(band)"},"celtic":{"title":"Celtic Frost","desc":"Swiss metal band","text":"Celtic Frost was a Swiss extreme metal band from Zürich. Their early work influenced extreme metal, especially death, black and doom metal. They are noted for their avant-garde approach.","url":"https://en.wikipedia.org/wiki/Celtic_Frost"},"mayhem":{"title":"Mayhem (band)","desc":"Norwegian black metal band","text":"Mayhem is a Norwegian black metal band formed in Oslo in 1984. They were one of the pioneers of the Norwegian black metal scene, and their music has profoundly influenced the black metal genre. Mayhem's early career was marked by several controversies, including their notorious live performances, the 1991 suicide of vocalist Per Yngve Ohlin (\"Dead\"), and the 1993 murder of guitarist Øystein Aarseth (\"Euronymous\") by former bassist Varg Vikernes.","url":"https://en.wikipedia.org/wiki/Mayhem_(band)"},"darkthrone":{"title":"Darkthrone","desc":"Norwegian metal band","text":"Darkthrone is a Norwegian heavy metal band from Kolbotn, Akershus. Formed in 1986 as a death metal band named Black Death, in the early 1990s, Darkthrone switched to a black metal style influenced by Bathory and Celtic Frost, and were a leading band in the Norwegian black metal scene. Darkthrone has been a duo consisting of Fenriz and Nocturno Culto since guitarist Zephyrous left the group in 1993.","url":"https://en.wikipedia.org/wiki/Darkthrone"},"burzum":{"title":"Burzum","desc":"Norwegian black metal project","text":"Burzum is a Norwegian music project founded by Kristian \"Varg\" Vikernes in 1991. Although Burzum never played live performances, it became a key member of the early Norwegian black metal scene and is considered one of the most influential acts in the history of black metal and its offshoot National Socialist black metal (NSBM). The word \"burzum\" means \"darkness\" in the Black Speech, a fictional language crafted by The Lord of the Rings writer J.","url":"https://en.wikipedia.org/wiki/Burzum"},"emperor":{"title":"Emperor (Norwegian band)","desc":"Norwegian black metal band","text":"Emperor is a Norwegian black metal band formed in 1991 by guitarist and vocalist Ihsahn and guitarist Samoth. The group split up in 2001, but reunited from 2005 to 2007 for a few festival dates and brief US tours, and again from 2013 to 2014. Emperor reformed a third time in 2016.","url":"https://en.wikipedia.org/wiki/Emperor_(Norwegian_band)"},"immortal":{"title":"Immortal (band)","desc":"Norwegian black metal band","text":"Immortal is a Norwegian black metal band from Bergen. The group was founded in 1991 by frontman and guitarist Abbath Doom Occulta and guitarist Demonaz Doom Occulta. The pair worked with various drummers, and were joined by former drummer Horgh in 1996.","url":"https://en.wikipedia.org/wiki/Immortal_(band)"},"cradle":{"title":"Cradle of Filth","desc":"English extreme metal band","text":"Cradle of Filth are an English extreme metal band formed in Suffolk in 1991. The band's style evolved from black metal to a cleaner and more \"produced\" amalgam of gothic metal, symphonic metal and other genres. Their lyrics and imagery are influenced by Gothic literature, poetry, mythology and horror films. The band consist of founding member and vocalist Dani Filth, drummer Martin \"Marthus\" Škaroupka, bassist Daniel Firth, and guitarists Donny Burbage and Joff Bailey.","url":"https://en.wikipedia.org/wiki/Cradle_of_Filth"},"gorgoroth":{"title":"Gorgoroth","desc":"Norwegian black metal band","text":"Gorgoroth is a Norwegian black metal band based in Bergen. It was formed in 1992 by guitarist Infernus, the sole original member remaining. They have released nine studio albums. Gorgoroth are a Satanic band and have drawn controversy due to some of their concerts featuring impaled sheep heads and mock crucifixions. The band is named after the dead plateau of darkness in the land of Mordor from J.","url":"https://en.wikipedia.org/wiki/Gorgoroth"},"satyricon":{"title":"Satyricon (band)","desc":"Norwegian black metal band","text":"Satyricon is a Norwegian black metal band formed in Oslo in 1991. Satyr and Frost have been the band's core members since 1993, and its only official members since 1997. The band's first three albums typify Norwegian black metal. Since its fourth album in 1999, the band has included elements of traditional heavy metal. Satyricon was the first Norwegian black metal band to join a multi-national record label (EMI).","url":"https://en.wikipedia.org/wiki/Satyricon_(band)"},"dimmu":{"title":"Dimmu Borgir","desc":"Norwegian symphonic black metal band","text":"Dimmu Borgir is a Norwegian symphonic black metal band from Jessheim, formed in 1993. The name derives from Dimmuborgir, a volcanic formation in Iceland, the name of which means \"dark cities\" or \"dark castles/fortresses\" in Icelandic, Faroese and Old Norse. The band has been through numerous lineup changes over the years. Vocalist Shagrath and guitarist Silenoz are the only remaining original members.","url":"https://en.wikipedia.org/wiki/Dimmu_Borgir"},"watain":{"title":"Watain","desc":"Swedish black metal band","text":"Watain is a Swedish black metal band, formed in 1998. The band's name is taken from an early recording by the American black metal group Von. The band have become famous for their theistic Satanist views and for their live shows which involve pyrotechnics, candles, Satanic rituals, animal carcasses, and blood. At a now-notorious live performance in Brooklyn in 2014, they doused audience members in animal blood, allegedly causing some members of the audience to vomit.","url":"https://en.wikipedia.org/wiki/Watain"},"mgla":{"title":"Mgła","desc":"Polish black metal band","text":"Mgła is a Polish black metal band from Kraków, formed in 2000. The duo consists of vocalist, guitarist and bassist M. and drummer Darkside.","url":"https://en.wikipedia.org/wiki/Mg%C5%82a"},"pentagram":{"title":"Pentagram (band)","desc":"American heavy metal band","text":"Pentagram is an American doom metal band from Alexandria, Virginia. They are noted as one of the pioneers of heavy metal, particularly of the aforementioned subgenre doom metal. As such, they are considered one of the \"big four\" of doom metal alongside Candlemass, Saint Vitus, and Trouble. The band's sound has drawn comparisons to Black Sabbath. Pentagram frontman Bobby Liebling has expressed distaste for the \"doom metal\" terminology, instead preferring Pentagram to be referred to as a \"heavy hard rock\" band.","url":"https://en.wikipedia.org/wiki/Pentagram_(band)"},"saintvitus":{"title":"Saint Vitus (band)","desc":"American doom metal band","text":"Saint Vitus is an American doom metal band formed in Los Angeles in 1978. They are considered to be one of the first doom metal bands, and have been labeled as one of the \"big four\" of that genre, along with Candlemass, Pentagram and Trouble. Having released nine studio albums to date, Saint Vitus have never achieved a popular breakthrough, but have exerted great influence on the development of doom metal, sludge metal, and stoner rock.","url":"https://en.wikipedia.org/wiki/Saint_Vitus_(band)"},"trouble":{"title":"Trouble (band)","desc":"American doom metal band","text":"Trouble is an American doom metal band from Chicago, Illinois, formed in 1978. They are often considered one of the pioneers of doom metal, and have been referred to as one of the genre's \"big four\" alongside Candlemass, Pentagram and Saint Vitus. The band created a distinct style, taking influences of the British heavy metal bands Black Sabbath and Judas Priest, and psychedelic rock of the 1960s.","url":"https://en.wikipedia.org/wiki/Trouble_(band)"},"candlemass":{"title":"Candlemass (band)","desc":"Swedish doom metal band","text":"Candlemass is a Swedish epic doom metal band formed in Upplands Väsby, a suburb of Stockholm, in 1984 by bassist, songwriter, and bandleader Leif Edling, alongside drummer Matz Ekström. The band has had a defining influence on doom metal, with the epic doom genre itself taking its name from their 1986 debut album Epicus Doomicus Metallicus. Along with Pentagram, Saint Vitus, and Trouble, Candlemass has been recognised as one of the \"big four\" of doom metal.","url":"https://en.wikipedia.org/wiki/Candlemass_(band)"},"kyuss":{"title":"Kyuss","desc":"American stoner rock band","text":"Kyuss was an American stoner rock band formed in Palm Desert, California, in 1987. They are considered one of the pioneers of the genre. After disbanding in 1995, a number of band members have gone on to form or play in several notable bands including Queens of the Stone Age, Screaming Trees, Fu Manchu, Dwarves, Eagles of Death Metal, Mondo Generator, Hermano, Unida, Slo Burn and Them Crooked Vultures.","url":"https://en.wikipedia.org/wiki/Kyuss"},"eyehategod":{"title":"Eyehategod","desc":"American sludge metal band","text":"Eyehategod is an American sludge metal band from New Orleans, Louisiana, who formed in 1988. Their core lineup has remained consistent since the band's inception, with the exception of the bassist, until the death of drummer Joey LaCaze in 2013. As of 2026, the band has released six studio albums.","url":"https://en.wikipedia.org/wiki/Eyehategod"},"paradise":{"title":"Paradise Lost (band)","desc":"British gothic metal band","text":"Paradise Lost are a British gothic metal band. Formed in Halifax, West Yorkshire, in 1988, they are considered pioneers of death-doom and the main influence on gothic metal. As of 2005, Paradise Lost have sold over two million albums worldwide.","url":"https://en.wikipedia.org/wiki/Paradise_Lost_(band)"},"cathedral":{"title":"Cathedral (band)","desc":"English doom metal band","text":"Cathedral were a British doom metal band from Coventry, England. The group gained attention upon release of its debut album, Forest of Equilibrium (1991), which is considered a classic of the genre. However, the band's sound evolved quickly and began to adopt characteristics of 1970s metal, hard rock and progressive rock. After releasing ten full-length albums and touring extensively for over two decades, Cathedral broke up after the release of The Last Spire in 2013.","url":"https://en.wikipedia.org/wiki/Cathedral_(band)"},"monstermagnet":{"title":"Monster Magnet","desc":"American rock band","text":"Monster Magnet is an American rock band formed in Red Bank, New Jersey, in 1989 by Dave Wyndorf, John McBain (guitar), and Tim Cronin. The band has since undergone several lineup changes, with Wyndorf remaining the only constant member. Monster Magnet has released 11 studio albums to date and is best known for their 1990s hits \"Negasonic Teenage Warhead\" and \"Space Lord\". The band is also credited with developing and popularizing the stoner rock genre, along with Masters of Reality, Kyuss, Fu Manchu, and Sleep.","url":"https://en.wikipedia.org/wiki/Monster_Magnet"},"sleep":{"title":"Sleep (band)","desc":"American stoner/doom metal band","text":"Sleep is an American stoner/doom metal band from San Jose, California. Bassist and vocalist Al Cisneros has been the only constant member throughout the band's history. Critic Eduardo Rivadavia describes them as \"perhaps the ultimate stoner rock band\" and notes they exerted a strong influence on metal in the 1990s.","url":"https://en.wikipedia.org/wiki/Sleep_(band)"},"mdb":{"title":"My Dying Bride","desc":"English doom metal band","text":"My Dying Bride are an English doom metal band formed in Bradford. Since their inception in 1990, they have released 15 studio albums, five EPs, one demo, one box set, four compilation albums, one live album, and one live CD/DVD release.","url":"https://en.wikipedia.org/wiki/My_Dying_Bride"},"electricwizard":{"title":"Electric Wizard","desc":"British metal band","text":"Electric Wizard are an English doom/stoner metal band from Dorset. Formed in 1988 under the name Lord of Putrefaction, the band have recorded nine studio albums, two of which have been considered genre landmarks: Come My Fanatics… (1997) and Dopethrone (2000). Electric Wizard's brand of doom metal incorporates stoner and sludge traits, with lyrics focusing on the occult, witchcraft, H.","url":"https://en.wikipedia.org/wiki/Electric_Wizard"},"qotsa":{"title":"Queens of the Stone Age","desc":"American rock band","text":"Queens of the Stone Age is an American rock band formed in Palm Desert, California, in 1996. The band was founded by vocalist and guitarist Josh Homme shortly before he returned to his native Palm Desert, California. Homme has been the only constant member throughout multiple line-up changes; since 2013, the line-up has consisted of Homme, Troy Van Leeuwen, Michael Shuman, Dean Fertita, and Jon Theodore.","url":"https://en.wikipedia.org/wiki/Queens_of_the_Stone_Age"},"sunn":{"title":"Sunn O)))","desc":"American drone metal band","text":"Sunn O))) is an American drone metal band formed in 1998 in Seattle, Washington. The band is known for its distinctive visual style and slow, heavy sound, which blends diverse genres including doom metal, drone, black metal, and dark ambient, as well as for their extremely loud live performances.","url":"https://en.wikipedia.org/wiki/Sunn_O)))"},"manowar":{"title":"Manowar","desc":"American heavy metal band","text":"Manowar is an American heavy metal band from Auburn, New York. Formed in 1980, the group is known for lyrics based on fantasy fiction and mythology as well as numerous songs celebrating the genre and its core audience. The band is also known for a loud and emphatic sound. In an interview for MTV in February 2007, bassist Joey DeMaio lamented that \"these days, there's a real lack of big, epic metal that is drenched with crushing guitars and choirs and orchestras...","url":"https://en.wikipedia.org/wiki/Manowar"},"helloween":{"title":"Helloween","desc":"German power metal band","text":"Helloween is a German power metal band founded in 1984 in Hamburg by members of the bands Iron Fist, Gentry, Second Hell, and Powerfool. Helloween has at times been called one of the most influential European heavy metal bands of the 1980s.","url":"https://en.wikipedia.org/wiki/Helloween"},"blindguardian":{"title":"Blind Guardian","desc":"German power metal band","text":"Blind Guardian is a German power metal band formed in 1984 in Krefeld, West Germany. They are often credited as one of the seminal and most influential bands in the power metal and speed metal subgenres. Nine musicians have been part of the band's lineup throughout its history, which currently includes singer Hansi Kürsch, guitarists André Olbrich and Marcus Siepen, and, since 2005, drummer Frederik Ehmke.","url":"https://en.wikipedia.org/wiki/Blind_Guardian"},"stratovarius":{"title":"Stratovarius","desc":"Finnish power metal band","text":"Stratovarius is a Finnish power metal band formed in 1984. They have released sixteen studio albums, six DVDs, and six live albums. The band's line-up has changed many times, with no founding member left since the departure of drummer Tuomo Lassila in 1995, and no member from their early recording days left following guitarist Timo Tolkki's departure in 2008. Currently, the longest standing member is singer Timo Kotipelto, who joined in 1994.","url":"https://en.wikipedia.org/wiki/Stratovarius"},"gammaray":{"title":"Gamma Ray (band)","desc":"German power metal band","text":"Gamma Ray is a German power metal band from Hamburg, founded and fronted by Kai Hansen after his departure from power metal band Helloween, in 1989. He is the band's lead vocalist, guitarist and chief songwriter. Between 1990 and 2014, Gamma Ray recorded eleven studio albums.","url":"https://en.wikipedia.org/wiki/Gamma_Ray_(band)"},"rhapsody":{"title":"Rhapsody of Fire","desc":"Italian symphonic power metal band","text":"Rhapsody of Fire is an Italian symphonic power metal band formed in Trieste by guitarist Luca Turilli and keyboardist Alex Staropoli. The band is widely considered a pioneer of the symphonic power metal subgenre. Originally formed in 1993 as Thundercross, the band released albums under the moniker Rhapsody before changing their name to Rhapsody of Fire in 2006 due to trademark issues.","url":"https://en.wikipedia.org/wiki/Rhapsody_of_Fire"},"hammerfall":{"title":"HammerFall","desc":"Swedish power metal band","text":"HammerFall is a Swedish power metal band from Gothenburg. It was formed in 1993 by ex-Ceremonial Oath guitarist Oscar Dronjak. They have released thirteen studio albums.","url":"https://en.wikipedia.org/wiki/HammerFall"},"sonata":{"title":"Sonata Arctica","desc":"Finnish power metal band","text":"Sonata Arctica is a Finnish power metal band from the town of Kemi. Created as a hard rock band named Tricky Beans, they later changed to Tricky Means and finally to Sonata Arctica, when they shifted to power metal. The current lineup consists of drummer Tommy Portimo, lead singer Tony Kakko, keyboardist Henrik Klingenberg, guitarist Elias Viljanen and bassist Pasi Kauppinen. All the musicians of the band's history except Portimo also acted as backing vocalists.","url":"https://en.wikipedia.org/wiki/Sonata_Arctica"},"dragonforce":{"title":"DragonForce","desc":"British power metal band","text":"DragonForce are a British power metal band from London, formed in 1999. They are known for their long and fast guitar solos, fantasy-themed lyrics and retro video game-influenced sound. The band themselves refer to their music as \"extreme power metal\".","url":"https://en.wikipedia.org/wiki/DragonForce"},"sabaton":{"title":"Sabaton (band)","desc":"Swedish power metal band","text":"Sabaton is a Swedish power metal band from Falun, formed in 1999 by lead singer Joakim Brodén, bassist Pär Sundström, guitarists Oskar Montelius and Rikard Sundén, and drummer Richard Larsson. The band has gone through multiple lineup changes with Brodén and Sundström remaining the only consistent members. The vast majority of their songs are about historical events, mainly wars and significant battles.","url":"https://en.wikipedia.org/wiki/Sabaton_(band)"},"crimson":{"title":"King Crimson","desc":"English progressive rock band","text":"King Crimson were an English progressive rock band formed in London in 1968. Led by guitarist and primary composer Robert Fripp – the group's sole constant member throughout their history – the band are widely regarded as a foundational catalyst of the progressive rock movement. They drew inspiration from an expansive array of musical styles, incorporating elements of classical, jazz, folk, heavy metal, gamelan, post-punk, industrial, and experimental music.","url":"https://en.wikipedia.org/wiki/King_Crimson"},"rush":{"title":"Rush (band)","desc":"Canadian rock band","text":"Rush is a Canadian rock band, formed in Toronto in 1968. The band's original line-up included guitarist Alex Lifeson, drummer John Rutsey, and bassist and vocalist Jeff Jones, whom Geddy Lee replaced shortly after its formation. Rush went through a few line-up changes over the next six years, before settling on its classic power trio line-up with the addition of Neil Peart in July 1974, replacing Rutsey four months after the release of their self-titled debut album.","url":"https://en.wikipedia.org/wiki/Rush_(band)"},"yes":{"title":"Yes (band)","desc":"English progressive rock band","text":"Yes are an English progressive rock band formed in London in 1968. Having featured 20 full-time musicians across their history, their most notable members include lead singer Jon Anderson, bassist Chris Squire, guitarists Steve Howe and Trevor Rabin, drummers Bill Bruford and Alan White, and keyboardists Tony Kaye and Rick Wakeman, who represented Yes when they were inducted into the Rock and Roll Hall of Fame in 2017.","url":"https://en.wikipedia.org/wiki/Yes_(band)"},"genesis":{"title":"Genesis (band)","desc":"English rock band","text":"Genesis were an English rock band formed in 1967 at Charterhouse School in Godalming, Surrey. The band's longest-lasting and most commercially successful line-up consisted of keyboardist Tony Banks, bassist/guitarist Mike Rutherford and drummer/singer Phil Collins. In the 1970s, during which the band also included singer Peter Gabriel and guitarist Steve Hackett, Genesis were among the pioneers of progressive rock.","url":"https://en.wikipedia.org/wiki/Genesis_(band)"},"queensryche":{"title":"Queensrÿche","desc":"American progressive metal band","text":"Queensrÿche is an American progressive metal band. It formed in 1980 in Bellevue, Washington, and first went by Cross+Fire and then by the Mob before settling on its current name in 1982. The band has released 16 studio albums, one EP, and several DVDs, and continues to tour and record. The original lineup consisted of guitarists Michael Wilton and Chris DeGarmo, drummer Scott Rockenfield and bassist Eddie Jackson.","url":"https://en.wikipedia.org/wiki/Queensr%C3%BFche"},"fateswarning":{"title":"Fates Warning","desc":"American progressive metal band","text":"Fates Warning is an American progressive metal band, formed in Hartford, Connecticut, in 1982 by vocalist John Arch, guitarists Jim Matheos and Victor Arduini, bassist Joe DiBiase, and drummer Steve Zimmerman. There have been numerous lineup changes over the course of their 44-year career, and Matheos has been the only constant member. As of 2020, the band consists of Matheos, vocalist Ray Alder, bassist Joey Vera, drummer Bobby Jarzombek and guitarist Michael Abdow.","url":"https://en.wikipedia.org/wiki/Fates_Warning"},"dreamtheater":{"title":"Dream Theater","desc":"American progressive metal band","text":"Dream Theater is an American progressive metal band formed in 1985 in Boston, Massachusetts. The band comprises John Petrucci (guitar), John Myung (bass), Mike Portnoy (drums), James LaBrie (vocals), and Jordan Rudess (keyboards).","url":"https://en.wikipedia.org/wiki/Dream_Theater"},"porcupine":{"title":"Porcupine Tree","desc":"English progressive rock band","text":"Porcupine Tree are an English progressive rock band formed by musician Steven Wilson in 1987. During an initial career spanning more than twenty years, they earned acclaim from critics and fellow musicians, developed a cult following, and became an influence for new artists. The group carved out a career at a certain distance away from mainstream music, being described by publications such as Classic Rock and PopMatters as \"the most important band you'd never heard of\".","url":"https://en.wikipedia.org/wiki/Porcupine_Tree"},"meshuggah":{"title":"Meshuggah","desc":"Swedish extreme metal band","text":"Meshuggah is a Swedish extreme metal band formed in Umeå in 1987. Since 2004, the band's lineup consists of founding members Jens Kidman and Fredrik Thordendal, alongside rhythm guitarist Mårten Hagström, drummer Tomas Haake and bassist Dick Lövgren. Since its formation, the band has released nine studio albums, six EPs and eight music videos. Their latest studio album, Immutable, was released in April 2022 via Atomic Fire Records.","url":"https://en.wikipedia.org/wiki/Meshuggah"},"opeth":{"title":"Opeth","desc":"Swedish progressive metal band","text":"Opeth is a Swedish progressive metal band from Stockholm, formed in 1990. The band incorporates folk, blues, classical, and jazz elements into its usually lengthy compositions, as well as strong influences from death metal, especially in their early works. Most songs and compositions include acoustic guitar passages, Mellotrons, death growls, and strong dynamic shifts.","url":"https://en.wikipedia.org/wiki/Opeth"},"tool":{"title":"Tool (band)","desc":"American rock band","text":"Tool is an American rock band formed in Los Angeles in 1990. The group consists of vocalist Maynard James Keenan, guitarist Adam Jones, drummer Danny Carey and bassist Justin Chancellor, who replaced founding member Paul D'Amour in 1995. Tool has won four Grammy Awards, performed worldwide tours, and produced albums topping charts in several countries.","url":"https://en.wikipedia.org/wiki/Tool_(band)"},"mastodon":{"title":"Mastodon (band)","desc":"American heavy metal band","text":"Mastodon is an American heavy metal band from Atlanta, Georgia. Formed in 2000, the band's lineup of Troy Sanders (bass/vocals), Brent Hinds, Bill Kelliher, and Brann Dailor (drums/vocals) remained unchanged for 24 years. Hinds departed Mastodon in March 2025, and died five months later in a motorcycle accident in Atlanta, Georgia.","url":"https://en.wikipedia.org/wiki/Mastodon_(band)"},"btbam":{"title":"Between the Buried and Me","desc":"American progressive metal band","text":"Between the Buried and Me, often abbreviated as BTBAM, is an American progressive metal band from Raleigh, North Carolina. , Paul Waggoner, Dan Briggs, and Blake Richardson (drums).","url":"https://en.wikipedia.org/wiki/Between_the_Buried_and_Me"},"periphery":{"title":"Periphery (band)","desc":"American progressive metal band","text":", in 2005. Their musical style has been described as progressive metal, djent, and progressive metalcore. They are considered one of the pioneers of the djent movement within progressive metal. They have also received a Grammy nomination. The band consists of vocalist Spencer Sotelo, guitarists Misha Mansoor, Mark Holcomb, Jake Bowen, and drummer Matt Halpern.","url":"https://en.wikipedia.org/wiki/Periphery_(band)"},"typeo":{"title":"Type O Negative","desc":"American gothic metal band (1989–2010)","text":"Type O Negative was an American gothic metal band from Brooklyn, New York, formed in 1989. The band was formed by vocalist and bassist Peter Steele, guitarist Kenny Hickey, keyboardist Josh Silver, and drummer Sal Abruscato, who was later replaced by Johnny Kelly. Their lyrical emphasis on themes of addiction, death, depression, religion, romance, and sex resulted in the nickname \"the Drab Four\", which is in homage to the Beatles' \"Fab Four\" moniker.","url":"https://en.wikipedia.org/wiki/Type_O_Negative"},"nightwish":{"title":"Nightwish","desc":"Finnish symphonic metal band","text":"Nightwish are a Finnish symphonic metal band from Kitee. The band was formed in 1996 by keyboardist Tuomas Holopainen, guitarist Emppu Vuorinen, and former lead vocalist Tarja Turunen. The lineup grew with drummer Jukka Nevalainen and bassist Sami Vänskä. In 2001, Vänskä was replaced by Marko Hietala, who also took over the male vocalist role previously filled by Holopainen or guest singers.","url":"https://en.wikipedia.org/wiki/Nightwish"},"within":{"title":"Within Temptation","desc":"Dutch symphonic metal band","text":"Within Temptation is a Dutch symphonic metal band founded in April 1996 by vocalist Sharon den Adel and guitarist Robert Westerholt. They have also been classified under other genres, with critics praising the band's experimentation and musical versatility. 5 million albums worldwide.","url":"https://en.wikipedia.org/wiki/Within_Temptation"},"evanescence":{"title":"Evanescence","desc":"American rock band","text":"Evanescence is an American rock band founded in 1994 by singer and keyboardist Amy Lee and guitarist Ben Moody in Little Rock, Arkansas. After releasing independent EPs and a demo CD as a duo in the late 1990s, Evanescence released their debut studio album, Fallen, on Wind-up Records in 2003. Propelled by the success of hit singles including \"Bring Me to Life\" and \"My Immortal\", Fallen sold more than four million copies in the US by January 2004, garnering Evanescence two Grammy Awards out of six nominations.","url":"https://en.wikipedia.org/wiki/Evanescence"},"sonicyouth":{"title":"Sonic Youth","desc":"American rock band (1981–2011)","text":"Sonic Youth was an American rock band formed in New York City in 1981. Founding members Kim Gordon, Thurston Moore and Lee Ranaldo remained together for the entire history of the band, while drummer Steve Shelley, who joined in 1985, rounded out the core lineup. Jim O'Rourke was also a member from 1999 to 2005; Mark Ibold of Pavement joined in 2006 and remained in the band until their 2011 split.","url":"https://en.wikipedia.org/wiki/Sonic_Youth"},"melvins":{"title":"Melvins","desc":"American rock band","text":"Melvins are an American rock band formed in 1983 in Montesano, Washington. Known for combining heavy, slow riffs with experimental and eclectic songwriting, the band has been credited as pioneers of sludge metal, and a key influence in the development of alternative metal and grunge. Since 1984, vocalist/guitarist Buzz Osborne and drummer Dale Crover have been the band's only constant members.","url":"https://en.wikipedia.org/wiki/Melvins"},"soundgarden":{"title":"Soundgarden","desc":"American rock band","text":"Soundgarden was an American rock band formed in Seattle, Washington, in 1984 by singer and drummer Chris Cornell, lead guitarist Kim Thayil, and bassist Hiro Yamamoto. Scott Sundquist was brought in to play drums in 1985 so that Cornell could focus solely on vocals. Sundquist was soon replaced on drums by Matt Cameron in 1986. Yamamoto left in 1989 and was replaced initially by Jason Everman and shortly thereafter by Ben Shepherd.","url":"https://en.wikipedia.org/wiki/Soundgarden"},"pixies":{"title":"Pixies (band)","desc":"American alternative rock band","text":"The Pixies are an American alternative rock band formed in Boston, Massachusetts, in 1986. The original lineup consisted of Black Francis, Joey Santiago, Kim Deal and David Lovering (drums). The Pixies are associated with the 1990s alternative rock boom, and draw on elements including punk rock and surf rock. Their music is known for dynamic \"loud-quiet-loud\" shifts and song structures.","url":"https://en.wikipedia.org/wiki/Pixies_(band)"},"mudhoney":{"title":"Mudhoney","desc":"American rock band","text":"Mudhoney is an American rock band formed in Seattle, Washington, on January 1, 1988, following the demise of Green River. Its members are singer and rhythm guitarist Mark Arm, lead guitarist Steve Turner, bassist Guy Maddison and drummer Dan Peters. Original bassist Matt Lukin left the band in 1999, but rejoined the band in December 2000 for a tour that lasted through January 2001.","url":"https://en.wikipedia.org/wiki/Mudhoney"},"aic":{"title":"Alice in Chains","desc":"American rock band","text":"Alice in Chains is an American rock band formed in Seattle in 1987. Since 2006, the band's lineup has consisted of vocalist/guitarists Jerry Cantrell and William DuVall, bassist Mike Inez, and drummer Sean Kinney. Original vocalist Layne Staley died in 2002, and former bassist Mike Starr left in 1993. Often associated with grunge music, Alice in Chains' sound and style is rooted in heavy metal.","url":"https://en.wikipedia.org/wiki/Alice_in_Chains"},"nirvana":{"title":"Nirvana (band)","desc":"American rock band (1987–1994)","text":"Nirvana was an American rock band formed in Aberdeen, Washington, in 1987. Founded by lead singer and guitarist Kurt Cobain and bassist Krist Novoselic, the band went through a succession of drummers, most notably Chad Channing, before recruiting Dave Grohl in 1990. Nirvana's success popularized alternative rock, and they were often referenced as the flagship band of Generation X.","url":"https://en.wikipedia.org/wiki/Nirvana_(band)"},"smashing":{"title":"The Smashing Pumpkins","desc":"American alternative rock band","text":"The Smashing Pumpkins are an American alternative rock band formed in Chicago in 1988 by lead vocalist and guitarist Billy Corgan, guitarist James Iha, bassist D'arcy Wretzky, and drummer Jimmy Chamberlin. The band has undergone several line-up changes since their reunion in 2006, with Corgan being the primary songwriter and sole constant member since its inception. The current lineup consists of Corgan, Iha, and Chamberlin.","url":"https://en.wikipedia.org/wiki/The_Smashing_Pumpkins"},"pearljam":{"title":"Pearl Jam","desc":"American rock band","text":"Pearl Jam is an American rock band from Seattle, Washington, that formed in 1990. One of the key bands in the grunge movement of the early 1990s, Pearl Jam has outsold and outlasted many of its contemporaries and is considered one of the most influential bands from that decade.","url":"https://en.wikipedia.org/wiki/Pearl_Jam"},"foo":{"title":"Foo Fighters","desc":"American rock band","text":"The Foo Fighters are an American rock band formed in Seattle in 1994. Initially founded as a one-man project by former Nirvana drummer Dave Grohl, the band comprises vocalist/guitarist Grohl, bassist Nate Mendel, guitarists Pat Smear and Chris Shiflett, keyboardist Rami Jaffee and drummer Ilan Rubin. Guitarist Franz Stahl and drummers William Goldsmith, Taylor Hawkins, and Josh Freese are former members.","url":"https://en.wikipedia.org/wiki/Foo_Fighters"},"radiohead":{"title":"Radiohead","desc":"English rock band","text":"Radiohead are an English rock band formed in Abingdon, Oxfordshire, in 1985. The members are Thom Yorke ; brothers Jonny Greenwood and Colin Greenwood (bass); Ed O'Brien ; and Philip Selway (drums). They have worked with the producer Nigel Godrich and the cover artist Stanley Donwood since 1994. Radiohead's experimental approach is credited with advancing the sound of alternative rock.","url":"https://en.wikipedia.org/wiki/Radiohead"},"fnm":{"title":"Faith No More","desc":"American rock band","text":"Faith No More is an American rock band from San Francisco, California, formed in 1979. The band rose to prominence with the lineup of bassist Billy Gould, drummer Mike Bordin, keyboardist/rhythm guitarist Roddy Bottum, guitarist Jim Martin – who all played on the debut album – and vocalist Mike Patton, who joined in 1988.","url":"https://en.wikipedia.org/wiki/Faith_No_More"},"ministry":{"title":"Ministry (band)","desc":"American industrial metal band","text":"Ministry is an American industrial metal band founded in Chicago, Illinois, in 1981 by producer, singer, and instrumentalist Al Jourgensen. Originally a synth-pop outfit, Ministry evolved into one of the pioneers of industrial rock and industrial metal in the late 1980s. The band's lineup has changed frequently, leaving Jourgensen as the sole remaining original member. Musicians who have contributed to the band's studio and/or live activities include vocalists Nivek Ogre, Chris Connelly, Gibby Haynes, Burton C.","url":"https://en.wikipedia.org/wiki/Ministry_(band)"},"deftones":{"title":"Deftones","desc":"American alternative metal band","text":"Deftones is an American alternative metal band formed in Sacramento, California, in 1988. They were formed by frontman Chino Moreno, lead guitarist Stephen Carpenter and drummer Abe Cunningham, with bassist Chi Cheng and keyboardist and turntablist Frank Delgado joining the lineup in 1990 and 1999, respectively.","url":"https://en.wikipedia.org/wiki/Deftones"},"godflesh":{"title":"Godflesh","desc":"English industrial metal band","text":"Godflesh are an English industrial metal band from Birmingham, formed in 1988 by Justin Broadrick and B. C. Green. D. and helped lay the groundwork for Godflesh’s formation. Through their fusion of hip hop–derived drum programming, metal riffs, and industrial dissonance, later exploring electronic and dub elements, Godflesh developed a sound widely recognized as foundational to industrial metal and post-metal, and influential across experimental and extreme metal.","url":"https://en.wikipedia.org/wiki/Godflesh"},"nin":{"title":"Nine Inch Nails","desc":"American industrial rock band","text":"Nine Inch Nails, commonly abbreviated as NIN, is an American industrial rock band formed by singer, songwriter, multi-instrumentalist, and producer Trent Reznor in 1988 in Cleveland, Ohio. Reznor was the sole permanent member of the band until his frequent collaborator, English musician Atticus Ross, became an official member in 2016. The band's debut album, Pretty Hate Machine (1989), was released via TVT Records.","url":"https://en.wikipedia.org/wiki/Nine_Inch_Nails"},"manson":{"title":"Marilyn Manson (band)","desc":"American rock band","text":"Marilyn Manson is an American rock band formed by namesake lead singer Marilyn Manson and lead guitarist Daisy Berkowitz in Fort Lauderdale, Florida, in 1989. Originally named Marilyn Manson & the Spooky Kids, they gained a local cult following in South Florida in the early 1990s with their theatrical live performances. In 1993, they were the first act signed to Trent Reznor's Nothing Records label.","url":"https://en.wikipedia.org/wiki/Marilyn_Manson_(band)"},"fearfactory":{"title":"Fear Factory","desc":"American industrial metal band","text":"Fear Factory is an American industrial metal band formed in Los Angeles in 1989. It has released ten full-length albums and evolved through a succession of sounds, all in its main style of industrial metal. Over the years, the band has undergone frequent changes in its lineup. Lead vocalist Burton C. Bell was the only consistent member for 31 years until his departure in 2020.","url":"https://en.wikipedia.org/wiki/Fear_Factory"},"rage":{"title":"Rage Against the Machine","desc":"American rock band","text":"Rage Against the Machine was an American rock band formed in Los Angeles, California, in 1991. It consisted of vocalist Zack de la Rocha, bassist and backing vocalist Tim Commerford, guitarist Tom Morello, and drummer Brad Wilk. They melded heavy metal, rap, punk rock, and funk with anti-authoritarian, anti-capitalist, and revolutionary lyrics. As of 2010, they had sold over 16 million records worldwide.","url":"https://en.wikipedia.org/wiki/Rage_Against_the_Machine"},"korn":{"title":"Korn","desc":"American nu metal band","text":"D. Their current lineup features Shaffer (guitar), Brian \"Head\" Welch (guitar), Jonathan Davis (vocals), and Ray Luzier (drums), the last of whom replaced Silveria in 2007. The band is notable for pioneering and popularizing the nu metal genre.","url":"https://en.wikipedia.org/wiki/Korn"},"rammstein":{"title":"Rammstein","desc":"German metal band","text":"Rammstein is a German Neue Deutsche Härte band formed in Berlin in 1994. The band's lineup—consisting of lead vocalist Till Lindemann, lead guitarist Richard Kruspe, rhythm guitarist Paul Landers, bassist Oliver Riedel, drummer Christoph Schneider, and keyboardist Christian \"Flake\" Lorenz—has remained unchanged throughout their history, along with their approach to songwriting, which consists of Lindemann writing and singing the lyrics over instrumental pieces the rest of the band has completed beforehand.","url":"https://en.wikipedia.org/wiki/Rammstein"},"soad":{"title":"System of a Down","desc":"Armenian-American metal band","text":"System of a Down is an Armenian-American heavy metal band formed in Glendale, California, in 1994. Since 1997, the band has consisted of founding members Serj Tankian, Daron Malakian, and Shavo Odadjian (bass); along with John Dolmayan (drums), who replaced original drummer Andy Khachaturian.","url":"https://en.wikipedia.org/wiki/System_of_a_Down"},"slipknot":{"title":"Slipknot (band)","desc":"American heavy metal band","text":"Slipknot is an American heavy metal band formed in Des Moines, Iowa, in 1995 by percussionist Shawn Crahan, vocalist Anders Colsefni and bassist Paul Gray. After several lineup changes in its early years, the band settled on nine members from 1999 until Gray's death in 2010: Crahan, Gray, Joey Jordison, Craig Jones, Mick Thomson, Corey Taylor, Sid Wilson, Chris Fehn, and Jim Root.","url":"https://en.wikipedia.org/wiki/Slipknot_(band)"},"linkin":{"title":"Linkin Park","desc":"American rock band","text":"Linkin Park is an American rock band formed in Agoura Hills, California, in 1996. The band's current lineup consists of vocalist/rhythm guitarist/keyboardist Mike Shinoda, lead guitarist Brad Delson, DJ/turntablist Joe Hahn, bassist Dave Farrell, vocalist Emily Armstrong, and drummer Colin Brittain.","url":"https://en.wikipedia.org/wiki/Linkin_Park"},"converge":{"title":"Converge (band)","desc":"American metalcore band","text":"Converge is an American hardcore band formed by vocalist and artist Jacob Bannon and guitarist and producer Kurt Ballou in Salem, Massachusetts, in 1990. While recording their landmark fourth album Jane Doe in 2001, the group became a four-piece with the departure of guitarist Aaron Dalbec and the addition of bassist Nate Newton and drummer Ben Koller. This lineup has remained intact since.","url":"https://en.wikipedia.org/wiki/Converge_(band)"},"machinehead":{"title":"Machine Head (band)","desc":"American heavy metal band","text":"Machine Head is an American heavy metal band from Oakland, California. The band was formed in 1991 by vocalist/guitarist Robb Flynn, who remains the only original member of the band. Machine Head's aggressive musicianship made it one of the pioneering bands in the new wave of American heavy metal. Its current lineup comprises Flynn, bassist Jared MacEachern, and drummer Matt Alston.","url":"https://en.wikipedia.org/wiki/Machine_Head_(band)"},"log":{"title":"Lamb of God (band)","desc":"American heavy metal band","text":"Lamb of God is an American heavy metal band from Richmond, Virginia. Formed in 1994 as Burn the Priest, the group consists of bassist John Campbell, vocalist Randy Blythe, guitarists Mark Morton and Willie Adler, and drummer Art Cruz. The band is considered a significant member of the new wave of American heavy metal movement.","url":"https://en.wikipedia.org/wiki/Lamb_of_God_(band)"},"bfmv":{"title":"Bullet for My Valentine","desc":"Welsh heavy metal band","text":"Bullet for My Valentine, often abbreviated as BFMV, are a Welsh heavy metal band from Bridgend, formed in 1998. The band is currently composed of Matthew Tuck, Michael Paget, Jamie Mathias (bass) and Jason Bowld (drums). Former members include Michael Thomas, Jason James and Nick Crandle; the latter were on bass. They were formed under the name Jeff Killed John and started their music career by covering songs by Metallica and Nirvana.","url":"https://en.wikipedia.org/wiki/Bullet_for_My_Valentine"},"killswitch":{"title":"Killswitch Engage","desc":"American metalcore band","text":"Killswitch Engage is an American metalcore band from Westfield, Massachusetts, formed in 1999. The band's current lineup consists of vocalist Jesse Leach, guitarists Joel Stroetzel and Adam Dutkiewicz, bassist Mike D'Antonio, and drummer Justin Foley. Howard Jones was the band's lead vocalist from 2002 to 2012.","url":"https://en.wikipedia.org/wiki/Killswitch_Engage"},"trivium":{"title":"Trivium (band)","desc":"American metal band","text":"Trivium is an American heavy metal band from Orlando, Florida, formed in 1999. The band's creative core comprises three long-time members; vocalist and guitarist Matt Heafy, guitarist Corey Beaulieu, and bassist Paolo Gregoletto. The band has changed drummers numerous times, with Alex Rüdinger becoming the most recent addition in October 2025.","url":"https://en.wikipedia.org/wiki/Trivium_(band)"},"a7x":{"title":"Avenged Sevenfold","desc":"American heavy metal band","text":"Avenged Sevenfold is an American heavy metal band from Huntington Beach, California, formed in 1999. The band's current lineup consists of vocalist M. Shadows, guitarists Zacky Vengeance and Synyster Gates, bassist Johnny Christ, and drummer Brooks Wackerman.","url":"https://en.wikipedia.org/wiki/Avenged_Sevenfold"},"parkway":{"title":"Parkway Drive","desc":"Australian metalcore band","text":"Parkway Drive are an Australian metalcore band from Byron Bay, New South Wales, formed in 2003. Parkway Drive have released seven studio albums, one EP, two DVDs, a split album and one book, titled Ten Years of Parkway Drive. The band's latest three albums have reached number 1 of the Australian ARIA Charts – Ire (2015), Reverence (2018), and Darker Still (2022).","url":"https://en.wikipedia.org/wiki/Parkway_Drive"},"bmth":{"title":"Bring Me the Horizon","desc":"British rock band","text":"Bring Me the Horizon are a British rock band formed in 2004 in Sheffield, England. The group currently consists of lead vocalist Oli Sykes, drummer Matt Nicholls, guitarist Lee Malia and bassist Matt Kean. They are signed to RCA Records globally and Columbia Records exclusively in the United States.","url":"https://en.wikipedia.org/wiki/Bring_Me_the_Horizon"},"architects":{"title":"Architects (British band)","desc":"British metalcore band","text":"Architects are an English metalcore band from Brighton, East Sussex formed in 2004 by twin brothers Dan and Tom Searle. The band now consists of Dan Searle on drums, Sam Carter on vocals, Alex Dean on bass, and Adam Christianson on guitar. They have been signed to Epitaph Records since 2013.","url":"https://en.wikipedia.org/wiki/Architects_(British_band)"},"gojira":{"title":"Gojira (band)","desc":"French metal band","text":"Gojira is a French heavy metal band from Ondres. Founded as Godzilla in 1996, the band's lineup—brothers Joe and Mario Duplantier (drums), Christian Andreu (guitar), and Jean-Michel Labadie (bass)—has been the same since the band changed its name to Gojira in 2001. Gojira has been known for its progressive and technical death metal styles and lyrics that often feature themes of spirituality, philosophy, and environmentalism.","url":"https://en.wikipedia.org/wiki/Gojira_(band)"},"ghost":{"title":"Ghost (Swedish band)","desc":"Swedish rock band","text":"Ghost is a Swedish rock band formed in Linköping, in 2006. The band released their debut album, Opus Eponymous, in 2010, which earned them international recognition. This was followed by Infestissumam in 2013 and in 2015 by Meliora, which reached number one in Sweden and number eight in the US. This was followed by the albums Prequelle in 2018 and Impera in 2022. The band's sixth studio album, Skeletá, was released in 2025; it subsequently became their first number one on the US Billboard 200 chart.","url":"https://en.wikipedia.org/wiki/Ghost_(Swedish_band)"},"spiritbox":{"title":"Spiritbox","desc":"Canadian heavy metal band","text":"Spiritbox is a Canadian heavy metal band, originally from Victoria, British Columbia, publicly established by guitarist Mike Stringer and vocalist Courtney LaPlante in October 2017. The band's full lineup comprises married couple LaPlante and Stringer alongside drummer Zev Rose and bassist Josh Gilbert. The band's style is rooted in metalcore and progressive metal, incorporates electronic elements and draws from a variety of influences, while LaPlante's singing is inspired by R&B.","url":"https://en.wikipedia.org/wiki/Spiritbox"},"sleeptoken":{"title":"Sleep Token","desc":"English rock band","text":"Sleep Token are an anonymous English rock band formed in London in 2016. They have released four studio albums, two EPs, two standalone songs, and multiple covers.","url":"https://en.wikipedia.org/wiki/Sleep_Token"},"lou":{"title":"Lou Reed","desc":"American rock musician (1942–2013)","text":"Lewis Allan Reed was an American musician, songwriter, and poet. He was the guitarist, lead singer, and principal songwriter for the rock band the Velvet Underground and had a solo career that spanned five decades. Although not commercially successful during its existence, the Velvet Underground came to be regarded as one of the most influential bands in the history of underground and alternative rock music.","url":"https://en.wikipedia.org/wiki/Lou_Reed"},"iggy":{"title":"Iggy Pop","desc":"American rock musician (born 1947)","text":", known professionally as Iggy Pop, is an American singer, songwriter, musician, and actor who was the lead vocalist of the proto-punk band the Stooges. Regarded as the \"Godfather of Punk\", he is noted for his outrageous and unpredictable stage antics, poetic lyrics, and unique voice. He was named one of the 50 Great Voices by NPR, inducted into the Rock and Roll Hall of Fame as a member of the Stooges in 2010, and received a Grammy Lifetime Achievement Award in 2020 for his solo career.","url":"https://en.wikipedia.org/wiki/Iggy_Pop"},"alice":{"title":"Alice Cooper (band)","desc":"American rock band","text":"Alice Cooper, also known as the Alice Cooper Group or the Alice Cooper Band, is an American rock band formed in Phoenix, Arizona, in 1968. During their original run, the band consisted of lead singer Vincent Furnier, lead guitarist Glen Buxton, rhythm guitarist and keyboardist Michael Bruce, bassist Dennis Dunaway, and drummer Neal Smith. The band was notorious for their elaborate, theatrical shock rock stage shows.","url":"https://en.wikipedia.org/wiki/Alice_Cooper_(band)"},"danzig":{"title":"Danzig (band)","desc":"American heavy metal band","text":"Danzig is an American heavy metal band led by former Misfits and Samhain frontman Glenn Danzig. Formed in 1987 in Lodi, New Jersey out of the latter band, its \"classic\" lineup included the eponymous vocalist and keyboardist, guitarist John Christ, bassist Eerie Von, and drummer Chuck Biscuits. Earning a major hit with a live version of its 1988 song \"Mother\", the band's musical style fuses gothic atmospheres with blues-infused rock and metal.","url":"https://en.wikipedia.org/wiki/Danzig_(band)"},"kingdiamond":{"title":"King Diamond (band)","desc":"Danish heavy metal band","text":"King Diamond is a Danish heavy metal band formed in 1985 by vocalist King Diamond, guitarists Andy LaRocque and Michael Denner, bassist Timi Hansen, and drummer Mikkey Dee. King, Denner and Hansen had recently disbanded Mercyful Fate, and formed a new band under the King Diamond moniker, already known from the initial Mercyful Fate era.","url":"https://en.wikipedia.org/wiki/King_Diamond_(band)"},"dickinson":{"title":"Bruce Dickinson","desc":"English heavy metal singer (born 1958)","text":"Paul Bruce Dickinson is an English heavy metal singer best known as the frontman of Iron Maiden. He has performed in the band across two stints, from 1981 to 1993 and from 1999 to the present day. He is known for his wide-ranging operatic vocal style and energetic stage presence.","url":"https://en.wikipedia.org/wiki/Bruce_Dickinson"},"malmsteen":{"title":"Yngwie Malmsteen","desc":"Swedish-American guitarist (born 1963)","text":"Yngwie Johan Malmsteen is a Swedish-American guitarist. He first became known in the 1980s for his neoclassical playing style in heavy metal, and has released 22 studio albums in a career spanning over 40 years. Malmsteen is considered to be one of the best guitarists in rock and metal. In the early 1990s, he released the albums Eclipse (1990), Fire & Ice (1992), The Seventh Sign (1994) and Magnum Opus (1995).","url":"https://en.wikipedia.org/wiki/Yngwie_Malmsteen"},"vai":{"title":"Steve Vai","desc":"American guitarist (born 1960)","text":"Steven Siro Vai is an American guitarist, songwriter, and producer. A three-time Grammy Award winner and fifteen-time nominee, Vai started his music career in 1978 at the age of eighteen as a transcriptionist for Frank Zappa, and played in Zappa's band from 1980 to 1983. He embarked on a solo career in 1983 and has released 11 solo albums to date. He has recorded and toured with Alcatrazz, David Lee Roth, and Whitesnake, as well as recording with artists such as Ozzy Osbourne, Public Image Ltd, Mary J.","url":"https://en.wikipedia.org/wiki/Steve_Vai"},"satriani":{"title":"Joe Satriani","desc":"American guitarist (born 1956)","text":"Joseph Satriani is an American rock guitarist, composer, record producer, and songwriter. Early in his career, he worked as a guitar instructor, with many of his former students achieving fame, including Steve Vai, Larry LaLonde, Rick Hunolt, Kirk Hammett, Andy Timmons, Charlie Hunter, Kevin Cadogan, and Alex Skolnick. Satriani went on to have a successful solo music career, starting in the mid-1980s.","url":"https://en.wikipedia.org/wiki/Joe_Satriani"},"townsend":{"title":"Devin Townsend","desc":"Canadian musician (born 1972)","text":"Devin Garrett Townsend is a Canadian singer, guitarist, songwriter, and record producer. He founded extreme metal band Strapping Young Lad and was its primary songwriter, vocalist, and guitarist from 1994 to 2007. He also has an extensive solo career, and has released a total of 30 albums across all of his projects as of 2026.","url":"https://en.wikipedia.org/wiki/Devin_Townsend"},"cornell":{"title":"Chris Cornell","desc":"American musician (1964–2017)","text":"Christopher John Cornell was an American musician, best known as the lead vocalist, rhythm guitarist, and primary lyricist for the rock bands Soundgarden and Audioslave. He also had a solo career and contributed to numerous movie soundtracks. Cornell was the founder and frontman of Temple of the Dog, a one-off tribute band dedicated to his late friend, musician Andrew Wood of Malfunkshun and Mother Love Bone.","url":"https://en.wikipedia.org/wiki/Chris_Cornell"},"whitezombie":{"title":"White Zombie (band)","desc":"American heavy metal band (1985–1998)","text":"White Zombie was an American heavy metal band that formed in 1985. Based in New York City, they started as a noise rock band, releasing three EPs and one studio album in that style before changing to a heavy metal-oriented sound that broke them into the mainstream. The albums La Sexorcisto: Devil Music Volume One (1992) and Astro-Creep: 2000 (1995) established them as an influential act in groove metal and industrial metal, respectively.","url":"https://en.wikipedia.org/wiki/White_Zombie_(band)"},"robzombie":{"title":"Rob Zombie","desc":"American rock musician and filmmaker (born 1965)","text":"Robert Bartleh Cummings, known professionally as Rob Zombie, is an American singer, songwriter, record producer, filmmaker and actor. His music and lyrics are notable for their horror and sci-fi themes, and his live shows have been praised for their elaborate shock rock theatricality. He rose to fame as a founding member and the frontman of heavy metal band White Zombie, with whom he released four studio albums and one techno remix album.","url":"https://en.wikipedia.org/wiki/Rob_Zombie"},"robertjohnson":{"title":"Robert Johnson","desc":"American blues musician and songwriter (1911–1938)","text":"Robert Leroy Johnson was an American blues musician and songwriter. His singing, guitar playing and songwriting on his landmark 1936 and 1937 recordings have influenced later generations of musicians. Although his recording career spanned only seven months, he is recognized as a master of the blues, particularly the Delta blues style, and as one of the most influential musicians of the 20th century.","url":"https://en.wikipedia.org/wiki/Robert_Johnson"},"muddy":{"title":"Muddy Waters","desc":"American blues/foundational rock and roll musician (1913–1983)","text":"McKinley Morganfield, better known as Muddy Waters, was an American blues singer-songwriter and musician who was an important figure in the post-World War II blues scene, and is often cited as the \"father of modern Chicago blues\".","url":"https://en.wikipedia.org/wiki/Muddy_Waters"},"hooker":{"title":"John Lee Hooker","desc":"American blues musician (1912 or 1917–2001)","text":"John Lee Hooker was an American blues singer, songwriter, and guitarist. The son of a sharecropper, he rose to prominence performing an electric guitar-style adaptation of Delta blues that he developed in Detroit. Hooker often incorporated other elements, including talking blues and early North Mississippi hill country blues. He developed his own driving-rhythm boogie style, distinct from the 1930s–1940s piano-derived boogie-woogie.","url":"https://en.wikipedia.org/wiki/John_Lee_Hooker"},"bbking":{"title":"B. B. King","desc":"American blues guitarist, singer, and songwriter (1925–2015)","text":"Riley B. King, known professionally as B. B. King, was an American blues guitarist, singer, songwriter, and record producer. He introduced a sophisticated style of soloing based on fluid string bending, shimmering vibrato, and staccato picking that influenced many later electric guitar blues players. AllMusic recognized King as \"the single most important electric guitarist of the last half of the 20th century\".","url":"https://en.wikipedia.org/wiki/B._B._King"},"bodiddley":{"title":"Bo Diddley","desc":"American guitarist and singer (1928–2008)","text":"Ellas Otha Bates, known professionally as Bo Diddley, was an American guitarist, singer and songwriter who played a key role in the transition from the blues to rock and roll. He influenced many artists, including Buddy Holly, the Beatles, the Rolling Stones, the Animals, George Thorogood, Syd Barrett, Tom Petty, and the Clash.","url":"https://en.wikipedia.org/wiki/Bo_Diddley"},"chuckberry":{"title":"Chuck Berry","desc":"American musician (1926–2017)","text":"Charles Edward Anderson Berry was an American guitarist, singer, and songwriter who was one of the pioneers of rock and roll. Nicknamed the \"Father of Rock and Roll\", he refined and developed rhythm and blues into the major elements that made rock and roll distinctive with songs such as \"Maybellene\" (1955), \"Roll Over Beethoven\" (1956), \"Rock and Roll Music\" (1957), and \"Johnny B.","url":"https://en.wikipedia.org/wiki/Chuck_Berry"},"littlerichard":{"title":"Little Richard","desc":"American musician (1932–2020)","text":"Richard Wayne Penniman, better known by his stage name Little Richard, was an American singer, pianist and songwriter. He was an influential figure in popular music and culture for seven decades. Referred to as the \"Architect of Rock and Roll\", Richard's most celebrated work dates from the mid-1950s, when his charismatic showmanship and dynamic music, characterized by frenetic piano playing, pounding backbeat and powerful raspy vocals, laid the foundation for rock and roll.","url":"https://en.wikipedia.org/wiki/Little_Richard"},"elvis":{"title":"Elvis Presley","desc":"American singer and actor (1935–1977)","text":"Elvis Aaron Presley was an American singer and actor. Referred to as the \"King of Rock and Roll\", he is widely regarded as one of the most culturally significant figures of the 20th century. Presley's energetic and sexually provocative performance style, combined with a mixture of influences across color lines during a transformative era in race relations, brought both great success and initial controversy.","url":"https://en.wikipedia.org/wiki/Elvis_Presley"},"jerrylee":{"title":"Jerry Lee Lewis","desc":"American musician (1935–2022)","text":"Jerry Lee Lewis was an American country music and rock and roll pianist, singer, and songwriter. Nicknamed \"The Killer\", he was described as \"rock 'n' roll's first great wild man\". A pioneer of rock and roll and rockabilly music, Lewis made his first recordings in 1952 at Cosimo Matassa's J&M Studio in New Orleans, Louisiana, and early recordings in 1956 at Sun Records in Memphis, Tennessee.","url":"https://en.wikipedia.org/wiki/Jerry_Lee_Lewis"},"kinks":{"title":"The Kinks","desc":"English rock band (1962–1997)","text":"The Kinks were an English rock band formed in London in 1962. The band's classic line-up comprised brothers Ray Davies and Dave Davies, Pete Quaife (bass), and Mick Avory. Emerging during the height of British rhythm and blues and Merseybeat, their breakthrough third single, the Ray Davies-penned \"You Really Got Me\" (1964), became an international hit, topping the charts in the United Kingdom and reaching the Top 10 in the United States.","url":"https://en.wikipedia.org/wiki/The_Kinks"},"yardbirds":{"title":"The Yardbirds","desc":"English blues and psychedelic rock band","text":"The Yardbirds are an English blues rock band formed in London in 1963. The Yardbirds were formed in London in 1963 by vocalist and harmonica player Keith Relf and fellow musicians Paul Samwell-Smith, Chris Dreja, Jim McCarty and Anthony “Top” Topham. Relf remained the band's frontman throughout its original 1963–1968 existence and was central to its development from a blues-based club band into one of the most innovative British rock groups of the decade.","url":"https://en.wikipedia.org/wiki/The_Yardbirds"},"mayall":{"title":"John Mayall & the Bluesbreakers","desc":"English blues band","text":"John Mayall & the Bluesbreakers were an English blues rock band led by multi-instrumentalist, singer and songwriter John Mayall. The band has been influential as an incubator for British rock and blues musicians. Many of the best known bands to come out of Britain in the 1960s and 1970s had members that came through the Bluesbreakers at one time, forming the foundation of British blues music that is still played heavily on classic rock radio.","url":"https://en.wikipedia.org/wiki/John_Mayall_%26_the_Bluesbreakers"},"fleetwood":{"title":"Fleetwood Mac","desc":"British and American rock band","text":"Fleetwood Mac were a British and American rock band formed in London in 1967. They have sold more than 120 million records worldwide, making them one of the world's best-selling musical acts. Their 1977 album, Rumours, is one of the best-selling albums of all time and won the Grammy Award for Album of the Year in 1978.","url":"https://en.wikipedia.org/wiki/Fleetwood_Mac"},"bobdylan":{"title":"Bob Dylan","desc":"American singer-songwriter (born 1941)","text":"Bob Dylan is an American singer-songwriter. Described as one of the greatest songwriters of all time, Dylan has been a major figure in popular culture over his 69-year career. Dylan added increasingly sophisticated lyrical techniques to the folk music of the early 1960s, infusing it \"with the intellectualism of classic literature and poetry\". His lyrics incorporated political, social, and philosophical influences, defying pop music conventions and appealing to the burgeoning counterculture.","url":"https://en.wikipedia.org/wiki/Bob_Dylan"},"byrds":{"title":"The Byrds","desc":"American rock band","text":"The Byrds were an American rock band formed in Los Angeles, California, in 1964. The band underwent multiple lineup changes, with frontman Roger McGuinn as the sole consistent member. For a short time in the mid-1960s, the Byrds were among the most popular groups in the world, with critics considering them to be among the most influential rock acts of their era.","url":"https://en.wikipedia.org/wiki/The_Byrds"},"beachboys":{"title":"The Beach Boys","desc":"American rock band","text":"The Beach Boys are an American rock band formed in Hawthorne, California, in 1961. The group's founding members consisted of brothers Brian, Dennis, and Carl Wilson, their cousin Mike Love, and their friend Al Jardine. One of the most popular and influential acts of the rock era, they are known for their musical ingenuity, vocal harmonies, and lyrics initially reflecting southern California's youth culture of surfing, cars, and romance dubbed the \"California sound\".","url":"https://en.wikipedia.org/wiki/The_Beach_Boys"},"sonics":{"title":"The Sonics","desc":"American garage rock band","text":"The Sonics are an American garage rock band from Tacoma, Washington, formed in 1960. Their aggressive, hard-edged sound has been a major influence on punk and garage music worldwide, and they have been named inspirations to the White Stripes, LCD Soundsystem, Nirvana, The Hives, and other musical artists.","url":"https://en.wikipedia.org/wiki/The_Sonics"},"dickdale":{"title":"Dick Dale","desc":"American surf rock guitarist (1937–2019)","text":"Richard Anthony Monsour, known professionally as Dick Dale, was an American rock guitarist. He was a pioneer of surf music, drawing on Middle Eastern music scales and experimenting with reverb. Dale was known as \"The King of the Surf Guitar,\" which was also the title of his second studio album.","url":"https://en.wikipedia.org/wiki/Dick_Dale"},"elevators":{"title":"The 13th Floor Elevators","desc":"American rock band","text":"The 13th Floor Elevators was an American rock band from Austin, Texas, United States, formed by guitarist and vocalist Roky Erickson, electric jug player Tommy Hall, and guitarist Stacy Sutherland. The band was together from 1965 to 1969, and during that period released four albums and seven singles for the International Artists record label. Their debut single \"You're Gonna Miss Me\" was a national Billboard No.","url":"https://en.wikipedia.org/wiki/The_13th_Floor_Elevators"},"gratefuldead":{"title":"Grateful Dead","desc":"American rock band (1965–1995)","text":"The Grateful Dead was an American rock band formed in Palo Alto, California, in 1965. They were known for their eclectic style which was influenced by elements of rock, blues, jazz, folk, country, bluegrass, rock and roll, gospel, reggae and world music. In their early years the band also introduced Space music psychedelia to their performances. The band became well known for their ability to improvise during their live performances.","url":"https://en.wikipedia.org/wiki/Grateful_Dead"},"jefferson":{"title":"Jefferson Airplane","desc":"American rock band","text":"Jefferson Airplane was an American rock band formed in San Francisco in 1965. One of the pioneering bands of psychedelic rock, the group defined the San Francisco Sound and was the first from the Bay Area to achieve international commercial success. They appeared at the Monterey Pop Festival (1967), the first Isle of Wight Festival (1968) as headliners, Woodstock (1969), and Altamont Free Concert (1969).","url":"https://en.wikipedia.org/wiki/Jefferson_Airplane"},"janis":{"title":"Janis Joplin","desc":"American singer-songwriter (1943–1970)","text":"Janis Lyn Joplin was an American singer-songwriter and musician. One of the most iconic and successful rock performers of her era, she was noted for her powerful mezzo-soprano vocals and her stage presence.","url":"https://en.wikipedia.org/wiki/Janis_Joplin"},"santana":{"title":"Santana (band)","desc":"American rock band","text":"Santana is an American rock band formed in San Francisco, California, in 1966 by Mexican-American guitarist Carlos Santana. The band has had various recording and performing line-ups in its history, with Santana being the only consistent member. After signing with Columbia Records, the band's appearance at the Woodstock Festival in 1969 increased their profile and they went on to record the critically acclaimed and commercially successful albums Santana (1969), Abraxas (1970) and Santana III (1971).","url":"https://en.wikipedia.org/wiki/Santana_(band)"},"creedence":{"title":"Creedence Clearwater Revival","desc":"American rock band (1959–1972)","text":"Creedence Clearwater Revival (CCR), or simply Creedence, was an American rock band formed in El Cerrito, California, in 1968. The band consisted of lead vocalist, lead guitarist, and primary songwriter John Fogerty; his brother, rhythm guitarist Tom Fogerty; bassist Stu Cook; and drummer Doug Clifford. These members had played together since 1959, first as the Blue Velvets and later as the Golliwogs, before settling on Creedence Clearwater Revival in 1968.","url":"https://en.wikipedia.org/wiki/Creedence_Clearwater_Revival"},"allman":{"title":"The Allman Brothers Band","desc":"American rock band","text":"The Allman Brothers Band was an American rock band formed in Jacksonville, Florida, in 1969. Brothers Duane and Gregg Allman founded it with Dickey Betts, Berry Oakley (bass), Butch Trucks (drums), and Jai Johanny \"Jaimoe\" Johanson (drums). Subsequently based in Macon, Georgia, they incorporated elements of blues, jazz and country music and their live shows featured jam band-style improvisation and instrumentals.","url":"https://en.wikipedia.org/wiki/The_Allman_Brothers_Band"},"skynyrd":{"title":"Lynyrd Skynyrd","desc":"American Southern rock band","text":"Lynyrd Skynyrd is an American rock band formed in Jacksonville, Florida, in 1964. The group originally formed as My Backyard and comprised Ronnie Van Zant (vocals), Gary Rossington (guitar), Allen Collins (guitar), Larry Junstrom (bass), and Bob Burns (drums). The band spent four years touring small venues under various names and with several lineup changes before deciding on \"Lynyrd Skynyrd\" in 1968.","url":"https://en.wikipedia.org/wiki/Lynyrd_Skynyrd"},"zztop":{"title":"ZZ Top","desc":"American rock band","text":"ZZ Top is an American rock band formed in Houston, Texas, in 1969. For five decades, the band had consisted of vocalist-guitarist Billy Gibbons, drummer Frank Beard and bassist-vocalist Dusty Hill, until Hill's death in 2021 and Beard's death in 2026. ZZ Top developed a signature sound based on Gibbons' blues style and Hill and Beard's rhythm section. They are known for their live performances, sly and humorous lyrics, and the matching appearances of Gibbons and Hill, who wore sunglasses, hats, and long beards.","url":"https://en.wikipedia.org/wiki/ZZ_Top"},"steppenwolf":{"title":"Steppenwolf (band)","desc":"Canadian–American rock group","text":"Steppenwolf was an American rock band formed in Los Angeles in 1967. The group was founded by singer/rhythm guitarist John Kay, keyboardist Goldy McJohn and drummer Jerry Edmonton, all formerly of the Canadian band the Sparrows. Guitarist Michael Monarch and bassist Rushton Moreve were recruited via notices placed in Los Angeles–area record and musical instrument stores.","url":"https://en.wikipedia.org/wiki/Steppenwolf_(band)"},"ironbutterfly":{"title":"Iron Butterfly","desc":"American rock group","text":"Iron Butterfly is an American rock band formed in San Diego, California, in 1966. They are best known for the 1968 hit \"In-A-Gadda-Da-Vida\", providing a dramatic sound that led the way towards the development of hard rock and heavy metal music. Although their heyday was the late 1960s, the band has been reformed with various members with varying levels of success with no new recordings since 1975.","url":"https://en.wikipedia.org/wiki/Iron_Butterfly"},"uriahheep":{"title":"Uriah Heep (band)","desc":"English rock band","text":"Uriah Heep are an English rock band formed in London in 1969. Their current lineup consists of guitarist Mick Box, keyboardist Phil Lanzon, lead vocalist Bernie Shaw, drummer Russell Gilbrook, and bassist Dave Rimmer. They have experienced numerous lineup changes throughout their 57-year career, leaving Box as the only remaining original member.","url":"https://en.wikipedia.org/wiki/Uriah_Heep_(band)"},"hawkwind":{"title":"Hawkwind","desc":"English rock band","text":"Hawkwind are an English rock band known as one of the earliest space rock groups. Since their formation in November 1969, Hawkwind have gone through many incarnations and have incorporated many different styles into their music, including hard rock, progressive rock and psychedelic rock. They are regarded as an influential proto-punk band. Their lyrics often cover themes of urban life and science fiction.","url":"https://en.wikipedia.org/wiki/Hawkwind"},"budgie":{"title":"Budgie (band)","desc":"Welsh rock band","text":"Budgie were a Welsh heavy metal band from Cardiff. The band formed in 1967, and recorded a demo the following year. Budgie was characterized by a constant rotation of guitarists, with bassist and singer Burke Shelley and drummer Steve Williams being the only permanent members.","url":"https://en.wikipedia.org/wiki/Budgie_(band)"},"boc":{"title":"Blue Öyster Cult","desc":"American rock band","text":"Blue Öyster Cult is an American rock band formed in Stony Brook, Long Island in 1967. They have sold 25 million records worldwide, including 7 million in the United States. Their fusion of hard rock with psychedelia and penchant for occult, fantastical and tongue-in-cheek lyrics had a major influence on heavy metal music. They developed a cult following and enjoyed mainstream success with \"(Don't Fear) The Reaper\" (1976), \"Godzilla\" (1977) and \"Burnin' for You\" (1981), which remain classic rock radio staples.","url":"https://en.wikipedia.org/wiki/Blue_%C3%96yster_Cult"},"thinlizzy":{"title":"Thin Lizzy","desc":"Irish rock band","text":"Thin Lizzy were an Irish rock band formed in Dublin in 1969. The band initially consisted of bass guitarist, lead vocalist, and principal songwriter Phil Lynott, drummer Brian Downey, guitarist Eric Bell, and organist Eric Wrixon, although Wrixon left after a few months.","url":"https://en.wikipedia.org/wiki/Thin_Lizzy"},"whitesnake":{"title":"Whitesnake","desc":"British rock band","text":"Whitesnake were a British rock band formed in London in 1978. The group originated as the backing band for singer David Coverdale, who had recently left Deep Purple. Though the band quickly developed their own entity, Coverdale was the only constant member throughout their history.","url":"https://en.wikipedia.org/wiki/Whitesnake"},"bowie":{"title":"David Bowie","desc":"English musician and actor (1947–2016)","text":"David Robert Jones, known as David Bowie, was an English singer, songwriter and actor. Regarded as among the most influential musicians of the 20th century, he was known for his frequent reinvention and visual presentation, and is often referred to as the \"chameleon of rock\". His music, stagecraft and fashion have had a significant impact on popular culture.","url":"https://en.wikipedia.org/wiki/David_Bowie"},"trex":{"title":"T. Rex (band)","desc":"English rock band (1967–1977)","text":"T. Rex, originally Tyrannosaurus Rex, were an English rock band formed in London in 1967 by singer-songwriter and guitarist Marc Bolan, who was their leader, frontman and only consistent member. Originally an acoustic psychedelic folk band, Bolan began to change the band's style towards electric rock with their fourth album, 1970's A Beard of Stars, and shortened their name to T.","url":"https://en.wikipedia.org/wiki/T._Rex_(band)"},"roxy":{"title":"Roxy Music","desc":"English art rock band","text":"Roxy Music were an English rock band formed in 1970 by Bryan Ferry and Graham Simpson (bass). By the time the band recorded their first album in early 1972, Ferry and Simpson were joined by Andy Mackay (saxophone/oboe), Phil Manzanera (guitar), Paul Thompson (drums) and Brian Eno (synthesizer). Simpson departed in mid-1972 – from which time the bassist position in the band went on to be unstable – while Eno was replaced by Eddie Jobson (synthesizer/keyboards/violin) in mid-1973.","url":"https://en.wikipedia.org/wiki/Roxy_Music"},"slade":{"title":"Slade","desc":"English rock band","text":"Slade are an English rock band formed in Wolverhampton in 1963. They rose to prominence during the glam rock era in the early 1970s, achieving 17 consecutive top 20 hits, including six number ones, on the UK Singles Chart, and three number ones on the UK Albums Charts. The British Hit Singles & Albums names them the most successful British group of the 1970s based on sales of singles.","url":"https://en.wikipedia.org/wiki/Slade"},"sweet":{"title":"The Sweet","desc":"British glam rock band","text":"The Sweet are a British glam rock band who rose to prominence in the 1970s. Their best-known line-up consisted of lead vocalist Brian Connolly, bassist Steve Priest, guitarist Andy Scott and drummer Mick Tucker. As well as having success with singles in the UK and USA, Sweet have sold over 35 million albums worldwide.","url":"https://en.wikipedia.org/wiki/The_Sweet"},"nydolls":{"title":"New York Dolls","desc":"American rock band","text":"The New York Dolls were an American rock band formed in New York City in 1971, who released two albums, New York Dolls (1973) and Too Much Too Soon (1974), before disbanding in 1976. Its classic lineup consisted of vocalist David Johansen, guitarist Johnny Thunders, bassist Arthur Kane, guitarist and pianist Sylvain Sylvain, and drummer Jerry Nolan; the latter two had replaced Rick Rivets and Billy Murcia, respectively, in 1972.","url":"https://en.wikipedia.org/wiki/New_York_Dolls"},"wasp":{"title":"W.A.S.P. (band)","desc":"American heavy metal band","text":"P. is an American heavy metal band formed in Los Angeles, California in 1982. The band is considered to be an integral part of the early Sunset Strip scene of hard rock and glam metal, and they became recognized for their shock rock-themed image, lyrics and live performances. P. (1984) and The Last Command (1985), being certified as gold by the RIAA.","url":"https://en.wikipedia.org/wiki/W.A.S.P._(band)"},"fugazi":{"title":"Fugazi","desc":"American post-hardcore band","text":", in 1986. The band consists of guitarists and vocalists Ian MacKaye and Guy Picciotto, bassist Joe Lally, and drummer Brendan Canty. They were noted for their style-transcending music, DIY ethical stance, manner of business practice, and contempt for the music industry.","url":"https://en.wikipedia.org/wiki/Fugazi"},"offspring":{"title":"The Offspring","desc":"American punk rock band","text":"The Offspring is an American rock band formed in Garden Grove, California in 1984. The band currently consists of lead vocalist and guitarist Dexter Holland, lead guitarist Noodles, bassist Todd Morse, multi-instrumentalist Jonah Nimoy, and drummer Brandon Pertzborn. They played a key role in reviving mainstream interest in punk rock during the 1990s, having sold more than 45 million records and becoming one of the genre's best-selling bands.","url":"https://en.wikipedia.org/wiki/The_Offspring"},"greenday":{"title":"Green Day","desc":"American rock band","text":"Green Day is an American rock band formed in Rodeo, California, in 1987 by lead singer and guitarist Billie Joe Armstrong and bassist and backing vocalist Mike Dirnt, with drummer Tré Cool joining in 1990. In 1994, their third album Dookie, released through Reprise Records, became a breakout success and eventually shipped over 20 million copies in the United States. Green Day has been credited with reigniting mainstream interest in punk rock.","url":"https://en.wikipedia.org/wiki/Green_Day"},"mcr":{"title":"My Chemical Romance","desc":"American rock band","text":"My Chemical Romance is an American rock band from New Jersey. The band's current lineup consists of lead vocalist Gerard Way, lead guitarist Ray Toro, rhythm guitarist Frank Iero, and bassist Mikey Way. They are considered one of the most influential rock groups of the 2000s and a major act in the emo and pop-punk genres, despite the band rejecting the former label.","url":"https://en.wikipedia.org/wiki/My_Chemical_Romance"},"patti":{"title":"Patti Smith","desc":"American singer and songwriter (born 1946)","text":"Patricia Lee Smith is an American singer, songwriter, poet, and author. Her 1975 debut album, Horses, made her an influential member of the New York City–based punk rock movement earned her nicknames \"Queen of Punk, and \"Godmother of Punk\". Smith has fused rock and poetry in her work. In 1978, her most widely known song, \"Because the Night\", co-written with Bruce Springsteen, reached number 13 on the Billboard Hot 100 chart and number five on the UK Singles Chart.","url":"https://en.wikipedia.org/wiki/Patti_Smith"},"television":{"title":"Television (band)","desc":"American rock band","text":"Television was an American rock band from New York City that formed in 1973. Its most prominent lineup comprised vocalist and guitarist-keyboardist Tom Verlaine, guitarist Richard Lloyd, drummer Billy Ficca, and bassist Fred Smith. An early fixture of CBGB and the 1970s New York punk rock scene, the band is considered influential in the development of punk rock and alternative rock.","url":"https://en.wikipedia.org/wiki/Television_(band)"},"talkingheads":{"title":"Talking Heads","desc":"American rock band","text":"Talking Heads were an American rock band formed in New York City in 1975. It consisted of lead vocalist and guitarist David Byrne, drummer Chris Frantz, bassist Tina Weymouth, and guitarist and keyboardist Jerry Harrison. Described as one of the most acclaimed groups of the 1970s and 1980s, Talking Heads helped to pioneer new wave music by combining elements of punk, art rock, funk, and world music with \"an anxious yet clean-cut image\".","url":"https://en.wikipedia.org/wiki/Talking_Heads"},"blondie":{"title":"Blondie (band)","desc":"American rock band","text":"Blondie is an American rock band formed in New York City in 1974 by singer Debbie Harry and guitarist Chris Stein. The band was a pioneer of the new wave genre emerging from the CBGB scene of the mid-1970s. They achieved global commercial success with their third album, Parallel Lines (1978), and a string of multi-genre hit singles including \"Heart of Glass\", \"Call Me\", and \"Rapture\".","url":"https://en.wikipedia.org/wiki/Blondie_(band)"},"wire":{"title":"Wire (band)","desc":"English rock band","text":"Wire are an English rock band. They were formed in London in October 1976 by Colin Newman, Graham Lewis, Bruce Gilbert (guitar), George Gill and Robert Grey. They were originally associated with the punk rock scene, appearing on The Roxy London WC2 album, and were instrumental in the development of post-punk, while their debut album, Pink Flag, was influential for hardcore punk.","url":"https://en.wikipedia.org/wiki/Wire_(band)"},"gangoffour":{"title":"Gang of Four (band)","desc":"English rock band","text":"Gang of Four are an English post-punk band, formed in 1976 in Leeds. The original members were singer Jon King, guitarist Andy Gill, drummer Hugo Burnham, and bass guitarist Dave Allen. There have been many different line-ups including, among other notable musicians, Sara Lee, Gail Ann Dorsey, Mark Heaney and David Pajo. After a brief lull in the 1980s, different constellations of the band recorded two studio albums in the 1990s.","url":"https://en.wikipedia.org/wiki/Gang_of_Four_(band)"},"pil":{"title":"Public Image Ltd","desc":"English rock band","text":"Public Image Ltd are an English post-punk band formed by lead vocalist John Lydon, guitarist Keith Levene, bassist Jah Wobble, and drummer Jim Walker in June 1978. The group's line-up has changed frequently over the years; Lydon has been the sole constant member.","url":"https://en.wikipedia.org/wiki/Public_Image_Ltd"},"joydivision":{"title":"Joy Division","desc":"English rock band (1976–1980)","text":"Joy Division were an English rock band formed in Salford in 1976. The group consisted of vocalist, guitarist and lyricist Ian Curtis, guitarist and keyboardist Bernard Sumner, bassist Peter Hook, and drummer Stephen Morris.","url":"https://en.wikipedia.org/wiki/Joy_Division"},"neworder":{"title":"New Order (band)","desc":"English rock band","text":"New Order are an English rock band formed in Manchester in 1980 by vocalist, guitarist and keyboardist Bernard Sumner, bassist Peter Hook, and drummer Stephen Morris, with keyboardist Gillian Gilbert joining the band shortly after. Sumner, Hook and Morris were previously members of Joy Division, which had disbanded earlier in 1980 after the suicide of lead singer Ian Curtis.","url":"https://en.wikipedia.org/wiki/New_Order_(band)"},"siouxsie":{"title":"Siouxsie and the Banshees","desc":"British rock band","text":"Siouxsie and the Banshees ( \"Susie\") were a British rock band formed in London in 1976 by vocalist Siouxsie Sioux and bassist Steven Severin. The Times called them \"one of the most audacious and uncompromising musical adventurers of the post-punk era\".","url":"https://en.wikipedia.org/wiki/Siouxsie_and_the_Banshees"},"bauhaus":{"title":"Bauhaus (band)","desc":"English rock band","text":"Bauhaus were an English rock band formed in Northampton in 1978. Known for their dark image and gloomy sound, Bauhaus are one of the pioneers of gothic rock, although they mixed many genres, including dub, glam rock, psychedelia, and funk. The group consisted of Daniel Ash, Peter Murphy, Kevin Haskins (drums) and David J (bass).","url":"https://en.wikipedia.org/wiki/Bauhaus_(band)"},"cure":{"title":"The Cure","desc":"English rock band","text":"The Cure are an English rock band formed in Crawley in 1976 by Robert Smith and Lol Tolhurst (drums). As of 2026, the band's line-up comprises Smith, Simon Gallup (bass), Roger O'Donnell (keyboards), Jason Cooper (drums) and Reeves Gabrels (guitar). Smith has remained the only constant member throughout numerous line-up changes since the band's formation.","url":"https://en.wikipedia.org/wiki/The_Cure"},"sisters":{"title":"The Sisters of Mercy","desc":"English rock band","text":"The Sisters of Mercy are an English rock band formed in Leeds in 1980. After achieving early underground fame, the band experienced a commercial breakthrough in the mid-1980s, sustaining their success until the early 1990s, when they halted the release of new records in protest against their record company, WEA. Although the band operates primarily as a touring outfit today, they continue to perform new and unreleased music live.","url":"https://en.wikipedia.org/wiki/The_Sisters_of_Mercy"},"depeche":{"title":"Depeche Mode","desc":"English electronic band","text":"Depeche Mode are an English electronic band formed in Basildon, Essex, in 1980. Originally formed with the line-up of Dave Gahan, Martin Gore, Andy Fletcher and Vince Clarke, the band has consisted of Gahan and Gore since Fletcher's death in 2022.","url":"https://en.wikipedia.org/wiki/Depeche_Mode"},"huskerdu":{"title":"Hüsker Dü","desc":"American punk rock band (1979–1988)","text":"Hüsker Dü was an American punk rock band formed in Saint Paul, Minnesota, in 1979. The band's continuous members were guitarist/vocalist Bob Mould, bassist Greg Norton, and drummer/vocalist Grant Hart. They first gained notability as a hardcore punk band, and later crossed over into alternative rock. Mould and Hart were the band's principal songwriters, with Hart's higher-pitched vocals and Mould's baritone taking the lead in alternating songs.","url":"https://en.wikipedia.org/wiki/H%C3%BCsker_D%C3%BC"},"replacements":{"title":"The Replacements (band)","desc":"American rock band (1979–2015)","text":"The Replacements were an American rock band formed in Minneapolis, Minnesota, in 1979. The band was composed of the guitarist and vocalist Paul Westerberg, guitarist Bob Stinson, bass guitarist Tommy Stinson, and drummer Chris Mars for most of its existence. After two albums of relatively straightforward punk rock, they became among the main pioneers of alternative rock with their acclaimed albums Let It Be and Tim.","url":"https://en.wikipedia.org/wiki/The_Replacements_(band)"},"rem":{"title":"R.E.M.","desc":"American rock band","text":"M. was an American rock band formed in Athens, Georgia, in 1980 by drummer Bill Berry, guitarist Peter Buck, bassist Mike Mills, and lead vocalist Michael Stipe, who were students at the University of Georgia. M. was noted for Buck's arpeggiated \"jangle\" guitar playing; Stipe's distinctive vocal style, unique stage presence, and cryptic lyrics; Mills's countermelodic bass lines and backing vocals; and Berry's tight, economical drumming.","url":"https://en.wikipedia.org/wiki/R.E.M."},"smiths":{"title":"The Smiths","desc":"English rock band (1982–1987)","text":"The Smiths were an English rock band formed in Manchester in 1982, consisting of Morrissey (vocals), Johnny Marr (guitar), Andy Rourke (bass) and Mike Joyce (drums). Morrissey and Marr formed the band's principal songwriting partnership. The Smiths are regarded as one of the most important and influential British bands of the 1980s, and as pioneers of indie rock and independent music.","url":"https://en.wikipedia.org/wiki/The_Smiths"},"dinojr":{"title":"Dinosaur Jr.","desc":"American rock band","text":"Dinosaur Jr. is an American rock band formed in Amherst, Massachusetts, in 1984. The band was founded by J Mascis, Lou Barlow, and Murph (drums). After three albums on independent labels, the band earned a reputation as one of the formative influences on American alternative rock. Creative tension led to Mascis firing Barlow, who later formed Sebadoh and Folk Implosion. His replacement, Mike Johnson, came aboard for three major-label albums.","url":"https://en.wikipedia.org/wiki/Dinosaur_Jr."},"rhcp":{"title":"Red Hot Chili Peppers","desc":"American rock band","text":"The Red Hot Chili Peppers are an American rock band formed in Los Angeles in 1982, consisting of Flea (bass), Anthony Kiedis (vocals), Chad Smith (drums), and John Frusciante (guitar). Their music incorporates elements of alternative rock, funk, punk rock, hard rock, hip-hop, and psychedelic rock, and has influenced genres including funk metal, rap metal, rap rock, and nu metal.","url":"https://en.wikipedia.org/wiki/Red_Hot_Chili_Peppers"},"oasis":{"title":"Oasis (band)","desc":"English rock band","text":"Oasis are an English rock band formed in Manchester in 1991. The group initially consisted of Liam Gallagher, Paul \"Bonehead\" Arthurs (guitar), Paul \"Guigsy\" McGuigan and Tony McCarroll (drums). Liam asked his older brother Noel Gallagher to join as a fifth member a few months later to finalise their formation. Noel became the de facto leader of the group and took over the songwriting duties for the band's first four albums.","url":"https://en.wikipedia.org/wiki/Oasis_(band)"},"blur":{"title":"Blur (band)","desc":"English rock band","text":"Blur are an English rock band formed in London in 1988, consisting of singer Damon Albarn, guitarist Graham Coxon, bassist Alex James, and drummer Dave Rowntree. Their debut album, Leisure (1991), incorporated the sounds of Madchester and shoegaze. Following a stylistic change influenced by British guitar pop groups such as the Kinks, the Beatles, and XTC, Blur released the albums Modern Life Is Rubbish (1993), Parklife (1994), and The Great Escape (1995).","url":"https://en.wikipedia.org/wiki/Blur_(band)"},"jethrotull":{"title":"Jethro Tull (band)","desc":"British rock band","text":"Jethro Tull are a British rock band formed in Blackpool, Lancashire, in 1967. Emerging from the 1960s British blues scene, the band soon developed a distinctive progressive rock sound, blending hard rock, English folk music and classical music, while undergoing numerous stylistic shifts throughout its history. The band was founded and has been continuously led by Ian Anderson, its principal composer, lead vocalist, and multi-instrumentalist best known for his flute playing.","url":"https://en.wikipedia.org/wiki/Jethro_Tull_(band)"},"elp":{"title":"Emerson, Lake & Palmer","desc":"English progressive rock band","text":"Emerson, Lake & Palmer were an English progressive rock supergroup formed in London in 1970. The band consisted of Keith Emerson (keyboards) of the Nice, Greg Lake of King Crimson, and Carl Palmer of Atomic Rooster.","url":"https://en.wikipedia.org/wiki/Emerson%2C_Lake_%26_Palmer"},"zappa":{"title":"Frank Zappa","desc":"American musician (1940–1993)","text":"Frank Vincent Zappa was an American composer, songwriter, guitarist, conductor, actor, satirist, filmmaker, and activist. In a career spanning more than 30 years, Zappa composed rock, pop, jazz, jazz fusion, orchestral and musique concrète works; he additionally produced nearly all the 60-plus albums he released with his band the Mothers of Invention and as a solo artist. His discography is characterized by nonconformity, improvisation, sonic experimentation, musical virtuosity and satire of American culture.","url":"https://en.wikipedia.org/wiki/Frank_Zappa"},"can":{"title":"Can (band)","desc":"German experimental rock band","text":"Can were a German experimental rock band formed in Cologne in 1968 by Holger Czukay, Irmin Schmidt (keyboards), Michael Karoli (guitar), and Jaki Liebezeit (drums). They featured several vocalists, including American Malcolm Mooney (1968–70) and Japanese Damo Suzuki (1970–73). They have been hailed as pioneers of the German krautrock scene.","url":"https://en.wikipedia.org/wiki/Can_(band)"},"neu":{"title":"Neu!","desc":"German rock band","text":"Neu! were a West German experimental and electronic rock band formed in Düsseldorf in 1971 by Klaus Dinger and Michael Rother following their departure from Kraftwerk. The group's albums were produced by Conny Plank, who has been regarded as the group's \"hidden member\". They released three albums in their initial incarnation—Neu! (1972), Neu! 2 (1973), and Neu! '75 (1975)—before disbanding in 1975.","url":"https://en.wikipedia.org/wiki/Neu!"},"tangerine":{"title":"Tangerine Dream","desc":"German electronic music group","text":"Tangerine Dream is a German electronic music band founded in 1967 by Edgar Froese. The group has seen many personnel changes over the years, with Froese the only constant member until his death in January 2015. The best-known lineup of the group was its mid-1970s trio of Froese, Christopher Franke, and Peter Baumann. In 1979, Johannes Schmoelling replaced Baumann until his own departure in 1985.","url":"https://en.wikipedia.org/wiki/Tangerine_Dream"},"kraftwerk":{"title":"Kraftwerk","desc":"German electronic band","text":"Kraftwerk is a German electronic band formed in Düsseldorf in 1970 by Ralf Hütter and Florian Schneider. Widely considered innovators and pioneers of electronic music, Kraftwerk was among the first successful acts to popularise the genre. The group began as part of West Germany's experimental krautrock scene in the early 1970s before embracing electronic instrumentation, including synthesizers, drum machines, and vocoders.","url":"https://en.wikipedia.org/wiki/Kraftwerk"},"throbbing":{"title":"Throbbing Gristle","desc":"English band","text":"Throbbing Gristle were an English music and visual arts group formed in Kingston upon Hull by Genesis P-Orridge and Cosey Fanni Tutti, later joined by Peter \"Sleazy\" Christopherson and Chris Carter. They are widely regarded as pioneers of industrial music.","url":"https://en.wikipedia.org/wiki/Throbbing_Gristle"},"neubauten":{"title":"Einstürzende Neubauten","desc":"German experimental band","text":"Einstürzende Neubauten is a German experimental music group, formed in West Berlin in 1980. U. Unruh, plus Jochen Arbeit, and Rudolph Moser, who both joined the line-up in 1997. In 2026, Josefine Lukschy joined the band as the bass player.","url":"https://en.wikipedia.org/wiki/Einst%C3%BCrzende_Neubauten"},"hellhammer":{"title":"Hellhammer","desc":"Swiss extreme metal band","text":"Hellhammer was a Swiss extreme metal band from Nürensdorf, active from 1982 to 1984. The band's sound and style were heavily criticized and poorly reviewed during their active years, but have been praised in retrospect and regarded as a key influence on black metal. In June 1984, Hellhammer disbanded, and two members formed extreme metal band Celtic Frost.","url":"https://en.wikipedia.org/wiki/Hellhammer"},"dissection":{"title":"Dissection (band)","desc":"Swedish extreme metal band","text":"Dissection was a Swedish extreme metal band from Strömstad, formed in 1989 by guitarist, vocalist, and main songwriter Jon Nödtveidt and bassist Peter Palmdahl. Despite several lineup changes, Dissection released The Somberlain in 1993 and Storm of the Light's Bane in 1995 before splitting up in 1997 due to Nödtveidt's imprisonment for complicity in the murder of Josef Meddour.","url":"https://en.wikipedia.org/wiki/Dissection_(band)"},"deafheaven":{"title":"Deafheaven","desc":"American blackgaze band","text":"Deafheaven is an American blackgaze band formed in 2010 in San Francisco. The group began as a two-piece with singer George Clarke and guitarist Kerry McCoy, who recorded and self-released a demo album. Following its release, Deafheaven recruited three new members and began to tour. Before the end of 2010, the band signed to Deathwish Inc. and released their debut album, Roads to Judah, in April 2011.","url":"https://en.wikipedia.org/wiki/Deafheaven"},"autopsy":{"title":"Autopsy (band)","desc":"American death metal band","text":"Autopsy is an American death metal band formed in Contra Costa County, California, in 1987 by Chris Reifert and Eric Cutler, after Reifert departed from Death following the release of the demo Mutilation (1986) and their debut album, Scream Bloody Gore (1987). The group disbanded in 1995 and reunited in 2008. The band's hometown is in Concord, California.","url":"https://en.wikipedia.org/wiki/Autopsy_(band)"},"suffocation":{"title":"Suffocation (band)","desc":"American death metal band","text":"Suffocation is an American death metal band formed in 1989 in Centereach, New York, currently consisting of lead guitarist Terrance Hobbs, bassist Derek Boyer, rhythm guitarist Charlie Errigo, vocalist Ricky Myers, and live drummer John Longstreth. The band rose to prominence with their 1991 debut album, Effigy of the Forgotten, a blueprint for death metal in the 1990s. Since then, Suffocation has recorded eight albums.","url":"https://en.wikipedia.org/wiki/Suffocation_(band)"},"amonamarth":{"title":"Amon Amarth","desc":"Swedish melodic death metal band","text":"Amon Amarth are a Swedish melodic death metal band from Tumba, formed in 1992. The band takes their name from the Sindarin name of Mount Doom, a volcano in J. R. R. Tolkien's Middle-earth. Their lyrics mostly revolve around Viking mythology and history, and so they are sometimes labelled \"Viking metal\", though they are musically melodic death metal, a term the band prefers.","url":"https://en.wikipedia.org/wiki/Amon_Amarth"},"coc":{"title":"Corrosion of Conformity","desc":"American heavy metal band","text":"Corrosion of Conformity is an American heavy metal band from Raleigh, North Carolina, formed in 1982. The band has undergone multiple lineup changes throughout its existence, with lead guitarist Woody Weatherman as the sole constant member. Weatherman, founding bassist Mike Dean, founding drummer Reed Mullin and vocalist/rhythm guitarist Pepper Keenan are widely regarded as its \"classic\" lineup.","url":"https://en.wikipedia.org/wiki/Corrosion_of_Conformity"},"neurosis":{"title":"Neurosis (band)","desc":"American post-metal band","text":"Neurosis is an American post-metal band from Oakland, California. It was formed in 1985 by guitarist Scott Kelly, bassist Dave Edwardson, and drummer Jason Roeder, initially as a crust punk band. Chad Salter joined as a second guitarist and appeared on the band's 1987 debut Pain of Mind, and then Steve Von Till replaced him in 1989. The following year, the lineup further expanded to include a keyboardist and a visual artist.","url":"https://en.wikipedia.org/wiki/Neurosis_(band)"},"down":{"title":"Down (band)","desc":"American heavy metal band","text":"Down is an American heavy metal supergroup that formed in New Orleans, Louisiana, in 1991. The current lineup consists of vocalist Phil Anselmo, drummer Jimmy Bower, guitarists Pepper Keenan and Kirk Windstein, and bassist Pat Bruders.","url":"https://en.wikipedia.org/wiki/Down_(band)"},"highonfire":{"title":"High on Fire","desc":"American metal band","text":"High on Fire is an American heavy metal band from Oakland, California, that was formed in 1998. Matt Pike, the band's frontman and founder, also played guitar for Sleep. High on Fire won the 2019 Grammy Award for Best Metal Performance with their song \"Electric Messiah\". The band has released nine studio albums, with their newest, Cometh the Storm, released in 2024.","url":"https://en.wikipedia.org/wiki/High_on_Fire"},"isis":{"title":"Isis (band)","desc":"American post-metal band","text":"Isis was an American post-metal band from Boston, Massachusetts, that was active from 1997 to 2010. After some early personnel changes, the band's lineup of guitarist Aaron Turner, bassist Jeff Caxide, drummer Aaron Harris, guitarist Michael Gallagher, and keyboardist Bryant Clifford Meyer remained consistent for all five studio albums.","url":"https://en.wikipedia.org/wiki/Isis_(band)"},"baroness":{"title":"Baroness (band)","desc":"American heavy metal band","text":"Baroness is an American heavy metal band from Savannah, Georgia that has been active since 2003. Its early members grew up together in Lexington, Virginia. The band has undergone numerous lineup changes, with frontman John Baizley serving as the sole constant throughout. Baizley creates the artwork for all of the group's albums and has done artwork for other bands.","url":"https://en.wikipedia.org/wiki/Baroness_(band)"},"hatebreed":{"title":"Hatebreed","desc":"American metalcore band","text":"Hatebreed is an American hardcore band formed in 1994 in Bridgeport, Connecticut, and later based in New Haven, Connecticut. The band released its debut album Satisfaction Is the Death of Desire in 1997, which gave the band a cult following. The band signed to Universal Records and released Perseverance in 2002, which hit the Billboard 200. They have played a major role in the Connecticut hardcore scene.","url":"https://en.wikipedia.org/wiki/Hatebreed"},"jamesbrown":{"title":"James Brown","desc":"American musician (1933–2006)","text":"James Joseph Brown was an American singer, songwriter, dancer, musician, and record producer. The central progenitor of funk music and a major figure of 20th-century music, he is referred to by various nicknames, among them \"Mr. Dynamite\", \"the Hardest-Working Man in Show Business\", \"Minister of New Super Heavy Funk\", \"Godfather of Soul\", \"King of Soul\", and \"Soul Brother No. 1\".","url":"https://en.wikipedia.org/wiki/James_Brown"},"themeters":{"title":"The Meters","desc":"American funk band","text":"The Meters are an American funk band formed in 1965 in New Orleans by Zigaboo Modeliste (drums), George Porter Jr. (bass), Leo Nocentelli (guitar) and Art Neville (keyboards). The band performed and recorded their own music from the late 1960s until 1977 and played an influential role as backing musicians for other artists, including Lee Dorsey, Robert Palmer, Dr. John, and Allen Toussaint.","url":"https://en.wikipedia.org/wiki/The_Meters"},"funkadelic":{"title":"Funkadelic","desc":"American rock band","text":"Funkadelic was an American funk rock band formed in Plainfield, New Jersey, in 1968 and active until 1982. As one of the two flagship groups of George Clinton's P-Funk collective, they helped pioneer the funk music culture of the 1970s. Funkadelic initially formed as a backing band for Clinton's vocal group the Parliaments, but eventually pursued a heavier, psychedelic rock-oriented sound in their own recordings.","url":"https://en.wikipedia.org/wiki/Funkadelic"},"parliament":{"title":"Parliament (band)","desc":"American funk band most prominent during the 1970s","text":"Parliament was an American funk band formed in 1968 by George Clinton as a flagship act of his P-Funk collective. Evolving out of an earlier vocal group, Parliament became associated with a more commercial and less rock-oriented sound than its sister act Funkadelic. Their work incorporated Afrofuturist concepts, horn arrangements, synthesizer, and outlandish theatrics.","url":"https://en.wikipedia.org/wiki/Parliament_(band)"},"prince":{"title":"Prince (musician)","desc":"American musician and songwriter (1958–2016)","text":"Prince Rogers Nelson was an American singer, songwriter, musician, dancer, actor, and filmmaker. Often credited as one of the greatest musicians of his generation, he pioneered the Minneapolis sound and was influential in the evolution of various other genres. With estimated sales exceeding 100 million records, Prince is one of the best-selling music artists of all time.","url":"https://en.wikipedia.org/wiki/Prince_(musician)"},"miles":{"title":"Miles Davis","desc":"American jazz musician (1926–1991)","text":"Miles Dewey Davis III was an American trumpeter, bandleader, composer, and painter. He is among the most influential and acclaimed figures in the history of jazz and 20th-century music. In a career spanning nearly five decades, Davis was at the forefront of several major stylistic developments in jazz, including bebop, cool jazz, hard bop, third stream, modal jazz, avant-garde jazz and jazz fusion.","url":"https://en.wikipedia.org/wiki/Miles_Davis"},"mahavishnu":{"title":"Mahavishnu Orchestra","desc":"American jazz fusion band","text":"The Mahavishnu Orchestra was a jazz fusion band formed in New York City in 1971, led by English guitarist John McLaughlin. The group underwent several line-up changes throughout its history across its two periods of activity, from 1971 to 1976 and from 1984 to 1987.","url":"https://en.wikipedia.org/wiki/Mahavishnu_Orchestra"},"weather":{"title":"Weather Report","desc":"American jazz fusion band","text":"Weather Report was an American jazz fusion band active from 1970 to 1986. The band was founded in 1970 by Austrian keyboardist Joe Zawinul, American saxophonist Wayne Shorter, Czech bassist Miroslav Vitouš, American drummer Alphonse Mouzon and American percussionists Don Alias and Barbara Burton. The band was initially co-led by Zawinul and Shorter but as the 1970s progressed, Zawinul became the primary composer and creative director of the group.","url":"https://en.wikipedia.org/wiki/Weather_Report"},"rtf":{"title":"Return to Forever","desc":"American jazz fusion group led by Chick Corea","text":"Return to Forever was an American jazz fusion band that was founded by pianist Chick Corea in 1972. The band has had many members, with the only consistent bandmate of Corea's being bassist Stanley Clarke. Along with Weather Report, The Headhunters, and Mahavishnu Orchestra, Return to Forever is often cited as one of the core groups of the jazz-fusion movement of the 1970s.","url":"https://en.wikipedia.org/wiki/Return_to_Forever"},"loudness":{"title":"Loudness (band)","desc":"Japanese heavy metal band","text":"Loudness is a Japanese heavy metal band formed in 1981 by guitarist Akira Takasaki and drummer Munetaka Higuchi. They were the first Japanese metal band signed to a major label in the United States. Loudness has released twenty-eight studio albums and eleven live albums as of 2026, and had reached the Billboard 200 during their heyday as well as charting on Oricon dozens of times.","url":"https://en.wikipedia.org/wiki/Loudness_(band)"},"xjapan":{"title":"X Japan","desc":"Japanese rock band","text":"X Japan is a Japanese rock band from Chiba, formed in 1982 by drummer and pianist Yoshiki and lead vocalist Toshi. Starting as a predominantly power/speed metal band with heavy symphonic elements, they later gravitated towards a progressive sound with an emphasis on ballads. Besides being one of the first Japanese acts to achieve mainstream success while on an independent label, the group is widely credited as one of the pioneers of visual kei, a movement among Japanese musicians comparable to Western glam.","url":"https://en.wikipedia.org/wiki/X_Japan"},"boris":{"title":"Boris (band)","desc":"Japanese rock band","text":"Boris is a Japanese metal band that draws variously from styles such as sludge metal, drone, noise, psychedelia, and minimalism. Formed in 1992 in Tokyo, the band is composed of drummer Atsuo, guitarist/bassist Takeshi, and guitarist/keyboardist Wata. All three members provide lead vocals. Boris has released more than 20 studio albums on various labels around the world, as well as a variety of live albums, compilations, EPs, singles, and collaborative albums.","url":"https://en.wikipedia.org/wiki/Boris_(band)"},"sigh":{"title":"Sigh (band)","desc":"Japanese black metal band","text":"Sigh is a Japanese experimental metal band from Tokyo, formed in 1989. They shifted from traditional extreme metal to an experimental, avant-garde style with symphonic, world music, and progressive elements. They released their most recent studio album, Goh-Ka, in 2026.","url":"https://en.wikipedia.org/wiki/Sigh_(band)"},"direngrey":{"title":"Dir En Grey","desc":"Japanese heavy metal band","text":", a sub-division of Free-Will. With a consistent lineup of vocalist Kyo, guitarists Kaoru and Die, bassist Toshiya, and drummer Shinya, they have released twelve full-length albums. Numerous stylistic changes have made the genre of their music difficult to determine, though it is generally considered to be a form of metal. Originally a visual kei band, the members later opted for more subtle attire, but have continued to maintain a dramatic image on stage.","url":"https://en.wikipedia.org/wiki/Dir_En_Grey"},"babymetal":{"title":"Babymetal","desc":"Japanese kawaii metal band","text":"Babymetal , stylized in all caps, is a Japanese kawaii metal band formed in Tokyo in 2010. It consists of Suzuka Nakamoto as \"Su-metal\", Moa Kikuchi as \"Moametal\", and Momoko Okazaki as \"Momometal\". The band is produced by Kobametal from the talent agency Amuse Inc. Their vocals are backed by instrumentation performed by a group of session musicians known as the \"Kami Band\".","url":"https://en.wikipedia.org/wiki/Babymetal"},"mono":{"title":"Mono (Japanese band)","desc":"Japanese instrumental band","text":"Mono is a Japanese instrumental band, formed in 1999 in Tokyo. The band consists of Takaakira \"Taka\" Goto, Hideki \"Yoda\" Suematsu, Dahm Majuri Cipolla (drums), and Tamaki Kunishi.","url":"https://en.wikipedia.org/wiki/Mono_(Japanese_band)"},"boredoms":{"title":"Boredoms","desc":"Japanese rock band","text":"Boredoms is a rock band from Osaka, Japan formed in 1986. The band's sound is often referred to as noise rock, or sometimes Japanoise, though their more recent records have moved toward repetitive psychedelic rock, ambient soundscapes, and tribal drumming.","url":"https://en.wikipedia.org/wiki/Boredoms"},"saicos":{"title":"Los Saicos","desc":"Peruvian rock band","text":"Los Saicos is a rock band formed in 1964 in Lima, Peru. Their use of fast tempos, screamed vocals and aggressive riffing has led publications to retrospectively credit them as pioneers of punk rock music.","url":"https://en.wikipedia.org/wiki/Los_Saicos"},"mutantes":{"title":"Os Mutantes","desc":"Brazilian rock band","text":"Os Mutantes is a Brazilian rock band that were linked with the Tropicália movement of the late 1960s. Heavily influenced by Anglo-American psychedelic pop, they bridged Brazilian sensibilities together with studio trickery, feedback, distortion, and musique concrète. They released their now-acclaimed self-titled debut album in 1968.","url":"https://en.wikipedia.org/wiki/Os_Mutantes"},"cadillacs":{"title":"Los Fabulosos Cadillacs","desc":"Ska and rock band from Argentina","text":"Los Fabulosos Cadillacs is an Argentine musical group from Buenos Aires. Their music fuses ska with Latin rock and various other styles.","url":"https://en.wikipedia.org/wiki/Los_Fabulosos_Cadillacs"},"sodastereo":{"title":"Soda Stereo","desc":"Argentine rock band","text":"Soda Stereo was an Argentine rock band formed in Buenos Aires in 1982. The band's membership consisted of singer-guitarist Gustavo Cerati, bassist Zeta Bosio and drummer Charly Alberti. During their career, the band released seven studio albums before disbanding in 1997. Soda Stereo is the best-selling Argentine band of all time, having sold seven million records by 2007.","url":"https://en.wikipedia.org/wiki/Soda_Stereo"},"prisioneros":{"title":"Los Prisioneros","desc":"Chilean rock band","text":"Los Prisioneros was a Chilean rock band formed in San Miguel, Santiago, in 1982. Considered one of the most influential Latin-American bands of all time, they've been evaluated as pioneers of Rock en español by Latin American media and musicians, and one of the strongest socio-political impactful bands in Chile. The group developed a new wave sound that had its roots in British punk rock, in particular the Clash, and incorporated rockabilly, reggae and ska influences, and later synthpop.","url":"https://en.wikipedia.org/wiki/Los_Prisioneros"},"caifanes":{"title":"Caifanes","desc":"Mexican rock band","text":"Caifanes is a Mexican rock band formed in Mexico City in 1986. The group achieved commercial success during the late 1980s and early 1990s. The original lineup of members consisted of Saúl Hernández, Sabo Romo (bass), Alfonso André (drums) and Diego Herrera. Alejandro Marcovich later joined as lead guitarist.","url":"https://en.wikipedia.org/wiki/Caifanes"},"cafetacvba":{"title":"Café Tacuba","desc":"Mexican rock band","text":"Café Tacuba is a Mexican rock band formed in 1989 in Naucalpan de Juárez, State of Mexico. The group gained popularity in the early 1990s. They were founded in 1989, before they had the current lineup of Rubén Isaac Albarrán Ortega, Emmanuel del Real Díaz, José Alfredo \"Joselo\" Rangel Arroyo, and Enrique \"Quique\" Rangel Arroyo, their friend Roberto Silva played the keyboards for a short period of time.","url":"https://en.wikipedia.org/wiki/Caf%C3%A9_Tacuba"},"heroes":{"title":"Héroes del Silencio","desc":"Spanish rock band","text":"Héroes del Silencio was a Spanish rock band from Zaragoza, formed by guitarist Juan Valdivia and singer Enrique Bunbury. The lineup was completed by bassist Joaquín Cardiel and drummer Pedro Andreu. During the 1980s they experienced success around Spain and the Americas, and in various European countries including Germany, Belgium, Switzerland, France, Yugoslavia, and Portugal.","url":"https://en.wikipedia.org/wiki/H%C3%A9roes_del_Silencio"},"baronrojo":{"title":"Barón Rojo","desc":"Spanish heavy metal band","text":"Barón Rojo is a Spanish heavy metal band from Madrid that achieved international success in the 1980s. The band is led by siblings Carlos and Armando de Castro, previously from the band Coz, and is considered one of the most important representatives of Spanish hard rock. Barón Rojo in Spanish means \"red baron\", the name of the band being an homage to Manfred von Richthofen; the 1981 eponymous song \"Barón Rojo\" is about him.","url":"https://en.wikipedia.org/wiki/Bar%C3%B3n_Rojo"},"angra":{"title":"Angra (band)","desc":"Brazilian power metal band","text":"Angra is a Brazilian progressive and power metal band formed in 1991. They have released ten regular studio albums, six EPs, and seven live CD/DVDs to date. Led by Rafael Bittencourt, the band has gained a degree of popularity in Japan and Europe.","url":"https://en.wikipedia.org/wiki/Angra_(band)"},"krisiun":{"title":"Krisiun","desc":"Brazilian death metal band","text":"Krisiun is a Brazilian death metal band, founded in 1990 by brothers Alex Camargo, Moyses Kolesne (guitars), and Max Kolesne (drums). Since its formation, the group recorded three demos, Curse of the Evil One in 1990, Mortal Toxic in 1991, and The Plague in 1992, and self-released an extended play (EP) Unmerciful Order in 1993. After signing with Brazilian label Dynamo Records, Krisiun released the debut full-length Black Force Domain in 1995, followed by Apocalyptic Revelation, in 1998.","url":"https://en.wikipedia.org/wiki/Krisiun"},"sarcofago":{"title":"Sarcófago","desc":"Brazilian extreme metal band","text":"Sarcófago was a Brazilian extreme metal band formed in 1985. They were fronted by Sepultura's original singer, Wagner Lamounier, and Geraldo Minelli.","url":"https://en.wikipedia.org/wiki/Sarc%C3%B3fago"},"plastic":{"title":"The Plastic People of the Universe","desc":"Czech rock band","text":"The Plastic People of the Universe (PPU) is a Czech rock band from Prague. They are considered the foremost representatives of Prague's underground culture (1968–1989), which defied Czechoslovakia's Communist regime. Members of the band often suffered serious repercussions, including arrests and prosecution, because of their non-conformist ideals. The group continues to perform, despite the death in 2001 of its founder, main composer, and bassist, Milan Hlavsa.","url":"https://en.wikipedia.org/wiki/The_Plastic_People_of_the_Universe"},"root":{"title":"Root (band)","desc":"Czech black metal band","text":"Root is a Czech black metal band from Brno, formed in 1987 by vocalist and drummer Jiří \"Big Boss\" Valter and guitarist/bassist Petr \"Blackie\" Hošek. They have released 11 studio albums, one live record, and one compilation.","url":"https://en.wikipedia.org/wiki/Root_(band)"},"vader":{"title":"Vader (band)","desc":"Polish death metal band","text":"Vader is a Polish death metal band from Olsztyn. Formed in 1983, the group was founded by then-bassist Piotr \"Peter\" Wiwczarek and guitarist Zbigniew \"Vika\" Wróblewski. Vader went through several lineup changes over the years, with Wiwczarek as the only constant member. Since 2022, the band has comprised Wiwczarek on lead vocals and lead guitar, rhythm guitarist Marek \"Spider\" Pająk, bassist Tomasz \"Hal\" Halicki, and drummer Michał Andrzejczyk.","url":"https://en.wikipedia.org/wiki/Vader_(band)"},"decapitated":{"title":"Decapitated (band)","desc":"Polish death metal band","text":"Decapitated is a Polish death metal band formed in Krosno in 1996. The group is composed of guitarist, founder and composer Wacław \"Vogg\" Kiełtyka, vocalist Eemeli Bodde, bassist Paweł Pasek and drummer James Stewart. Decapitated are recognized as one of death metal's most respected bands and one of the finest exponents of technical death metal. The band earned an international fan base in the underground music community and became an innovating act in the modern death metal genre.","url":"https://en.wikipedia.org/wiki/Decapitated_(band)"},"riverside":{"title":"Riverside (band)","desc":"Polish progressive rock band","text":"Riverside is a Polish progressive rock band from Warsaw. It was founded in 2001 by guitarist Piotr Grudziński; drummer Piotr Kozieradzki; bassist and vocalist Mariusz Duda; and keyboardist Jacek Melnicki. Melnicki was replaced by Michał Łapaj in 2003. Grudziński died in 2016, and guitarist Maciej Meller joined the band in 2020. As of 2026, they have released eight studio albums, three EPs, four live records, and three compilations, as well as a number of singles.","url":"https://en.wikipedia.org/wiki/Riverside_(band)"},"slint":{"title":"Slint","desc":"American rock band","text":"Slint was an American rock band from Louisville, Kentucky, formed in 1986 after the dissolution of two local bands, Squirrel Bait and Maurice. It initially consisted of Brian McMahan, David Pajo (guitar), Britt Walford, and Ethan Buckler (bass). Though little known during their original run, they gained a cult following and acclaim as one of the pioneers of post-rock and math rock.","url":"https://en.wikipedia.org/wiki/Slint"},"godspeed":{"title":"Godspeed You! Black Emperor","desc":"Canadian post-rock band","text":"Godspeed You! Black Emperor is a Canadian post-rock collective founded in Montreal, Quebec in 1994. They release recordings through Constellation, a Montreal independent record label.","url":"https://en.wikipedia.org/wiki/Godspeed_You!_Black_Emperor"},"mogwai":{"title":"Mogwai","desc":"Scottish post-rock band","text":"Mogwai are a Scottish post-rock band, formed in 1995 in Glasgow. The band consists of Stuart Braithwaite, Barry Burns, Dominic Aitchison, and Martin Bulloch (drums). Mogwai typically compose lengthy guitar-based instrumental pieces that feature dynamic contrast, melodic bass guitar lines, and heavy use of distortion and effects.","url":"https://en.wikipedia.org/wiki/Mogwai"},"eits":{"title":"Explosions in the Sky","desc":"American post-rock band","text":"Explosions in the Sky is an American post-rock band, formed in Austin, Texas, in 1999. The band is a quartet, composed of drummer Chris Hrasky and guitarists/keyboardists Michael James, Munaf Rayani, and Mark Smith. The band originally played under the name Breaker Morant, then changed to the current name in 1999.","url":"https://en.wikipedia.org/wiki/Explosions_in_the_Sky"},"sigur":{"title":"Sigur Rós","desc":"Icelandic post-rock band","text":"Sigur Rós is an Icelandic post-rock band that formed in 1994 in Reykjavík. It comprises lead vocalist and guitarist Jón Þór \"Jónsi\" Birgisson, bassist Georg Hólm, and keyboardist Kjartan Sveinsson. Known for their ethereal sound, frontman Jónsi's falsetto vocals, and their use of bowed guitar, Sigur Rós incorporate classical and minimal aesthetic elements. Jónsi's vocals are sung in Icelandic and non-linguistic vocalisations the band terms Vonlenska.","url":"https://en.wikipedia.org/wiki/Sigur_R%C3%B3s"},"tortoise":{"title":"Tortoise (band)","desc":"American post-rock band","text":"Tortoise is an American post-rock band formed in Chicago, Illinois, in 1990. The band incorporates krautrock, dub, minimal music, electronica and jazz into their music, and their eclectic style has left a great influence on the post-rock genre. Tortoise have been consistently credited, as part of the Chicago school of post-rock, for its rise in the 1990s.","url":"https://en.wikipedia.org/wiki/Tortoise_(band)"},"cocteau":{"title":"Cocteau Twins","desc":"Scottish rock band (1979–1997)","text":"Cocteau Twins were a Scottish rock band active from 1979 to 1997. They were formed in Grangemouth on the Firth of Forth by Robin Guthrie and Will Heggie (bass), adding Elizabeth Fraser (vocals) in 1981. In 1983, Heggie was replaced by multi-instrumentalist Simon Raymonde. The group earned critical praise for their ethereal, effects-laden sound and the soprano vocals of Fraser, whose lyrics often eschew any recognisable language.","url":"https://en.wikipedia.org/wiki/Cocteau_Twins"},"mbv":{"title":"My Bloody Valentine (band)","desc":"Irish rock band","text":"My Bloody Valentine is an Irish rock band formed in Dublin, Ireland in 1983. Founded by singer and guitarist Kevin Shields and drummer Colm Ó Cíosóig, the band underwent multiple lineup changes before recruiting bassist Debbie Googe in 1985 and singer and guitarist Bilinda Butcher in 1987. Regarded as pioneers of the shoegaze subgenre, their work is characterised by distorted guitar textures, subdued androgynous vocals, and unorthodox production techniques.","url":"https://en.wikipedia.org/wiki/My_Bloody_Valentine_(band)"},"ride":{"title":"Ride (band)","desc":"English rock band","text":"Ride are an English rock band formed in Oxford in 1988. The band consists of vocalists and guitarists Andy Bell and Mark Gardener, drummer Laurence \"Loz\" Colbert and bassist Steve Queralt. They have been recognised as one of the key pioneers of shoegaze, an alternative rock subgenre that emerged to prominence in the United Kingdom during the early 1990s.","url":"https://en.wikipedia.org/wiki/Ride_(band)"},"slowdive":{"title":"Slowdive","desc":"British shoegaze band","text":"Slowdive is an English rock band that formed in Reading, Berkshire, in 1989. The band consists of Neil Halstead, Rachel Goswell, Christian Savill (guitars), Nick Chaplin, and Simon Scott, all of whom played on the band's early records. Halstead is the band's primary songwriter.","url":"https://en.wikipedia.org/wiki/Slowdive"},"tesseract":{"title":"Tesseract (band)","desc":"British progressive metal band","text":"Tesseract are a British progressive metal band from Milton Keynes. The band, formed in 2003, consists of Daniel Tompkins, Alec \"Acle\" Kahney, James Monteith, Amos Williams and Jay Postones. The band is currently signed to Kscope. They are credited as one of the bands to pioneer the djent movement in progressive metal. T, and the extended plays Concealing Fate, Perspective, Errai and Regrowth.","url":"https://en.wikipedia.org/wiki/Tesseract_(band)"},"aal":{"title":"Animals as Leaders","desc":"American instrumental progressive metal band","text":"C. Since 2012, the band has consisted of Tosin Abasi, Javier Reyes, and Matt Garstka (drums), having originated in 2007 as a solo project by Abasi. They are a prominent band within the djent scene. Prosthetic Records released the band's eponymous debut album in 2009. They have since released the albums Weightless (2011), The Joy of Motion (2014), The Madness of Many (2016), and Parrhesia (2022).","url":"https://en.wikipedia.org/wiki/Animals_as_Leaders"},"plini":{"title":"Plini","desc":"Australian guitarist (born 1992)","text":"Plini Roessler-Holgate, known mononymously as Plini, is an Australian guitarist and songwriter. He began his career by releasing music under the name Halcyon, before switching to the use of his first name. Steve Vai described him as \"the future of exceptional guitar playing\", and the website MusicRadar named Plini the best prog guitarist of 2017.","url":"https://en.wikipedia.org/wiki/Plini"},"alcest":{"title":"Alcest","desc":"French blackgaze/post-metal band","text":"Alcest is a French post-black metal band from Bagnols-sur-Cèze, founded and led by Neige. It began in 2000 as Neige's black metal solo project that became a trio. Members Aegnor and Argoth left the band following the 2001 release of their first demo, leaving Neige as the sole member. Neige incorporated shoegaze and post-metal into the project's sound from 2005 onwards. In 2009, drummer Winterhalter from Les Discrets joined Alcest, after eight years with Neige as its sole full-time member.","url":"https://en.wikipedia.org/wiki/Alcest"},"wolves":{"title":"Wolves in the Throne Room","desc":"American black metal band","text":"Wolves in the Throne Room is an American black metal band formed in 2002 in Olympia, Washington, by brothers Aaron and Nathan Weaver. They have released seven full-length albums, two live albums, and two EPs to date. They have stated one of the founding concepts of the band to be channeling the \"energies of the Pacific Northwest's landscape\" into musical form.","url":"https://en.wikipedia.org/wiki/Wolves_in_the_Throne_Room"},"liturgy":{"title":"Liturgy (band)","desc":"American black metal band","text":"Liturgy is an American black metal band from Brooklyn, New York City. The band have described their music as \"transcendental black metal,\" particularly in a manifesto founding member Haela Hunt-Hendrix wrote. While transforming their black metal style, they have experimented with progressive rock, hip hop and electronic music. Early on, Hunt-Hendrix cited Swans, Glenn Branca, Rhys Chatham, La Monte Young and Lightning Bolt as influences.","url":"https://en.wikipedia.org/wiki/Liturgy_(band)"},"codeorange":{"title":"Code Orange (band)","desc":"American metalcore band","text":"Code Orange is an American metalcore band that formed in Pittsburgh, Pennsylvania, in 2008, while the members of the band were still in high school.","url":"https://en.wikipedia.org/wiki/Code_Orange_(band)"},"lornashore":{"title":"Lorna Shore","desc":"American deathcore band","text":"Lorna Shore is an American deathcore band formed in New Jersey in 2009. The group consists of lead guitarist Adam De Micco, drummer Austin Archey, rhythm guitarist Andrew O'Connor, vocalist Will Ramos, and bassist Michael Yager. The band is known for their 2021 single, \"To the Hellfire\". They have released five studio albums, Psalms (2015), Flesh Coffin (2017), Immortal (2020), Pain Remains (2022), and I Feel the Everblack Festering Within Me (2025).","url":"https://en.wikipedia.org/wiki/Lorna_Shore"},"loathe":{"title":"Loathe (band)","desc":"English metalcore band","text":"Loathe are an English heavy metal band from Liverpool. The band's music makes use of elements of metalcore and nu metal, while also incorporating more experimental aspects from genres like shoegaze, progressive metal and industrial music. Formed in 2011 under the name Our Imbalance, the group consists of lead vocalist Kadeem France, guitarist and second vocalist Erik Bickerstaffe, drummer Sean Radcliffe and bassist Feisal El-Khazragi.","url":"https://en.wikipedia.org/wiki/Loathe_(band)"},"zeal":{"title":"Zeal & Ardor","desc":"Swiss avant-garde metal band","text":"Zeal & Ardor is a Swiss avant-garde metal band started and led by Manuel Gagneux, a Swiss-American musician who had previously created a chamber pop project called Birdmask. Formed in 2013, the band mixes sounds of African-American spirituals with black metal.","url":"https://en.wikipedia.org/wiki/Zeal_%26_Ardor"},"turnstile":{"title":"Turnstile (band)","desc":"American rock band","text":"Turnstile is an American rock band from Baltimore, Maryland, formed in 2010. The band consists of lead vocalist Brendan Yates, guitarists Pat McCrory and Meg Mills, bassist Franz Lyons, and drummer Daniel Fang.","url":"https://en.wikipedia.org/wiki/Turnstile_(band)"},"primus":{"title":"Primus (band)","desc":"American rock band","text":"Primus is an American rock band formed in El Sobrante, California, in 1984. As of 2026, the band consists of bassist/vocalist Les Claypool, guitarist Larry \"Ler\" LaLonde, and drummer John \"Hoffer\" Hoffman. Primus originally formed in 1984 with Claypool and guitarist Todd Huth, later joined by drummer Jay Lane, though the latter two had departed by the beginning of the band's recording career in 1989, replaced by LaLonde and Tim \"Herb\" Alexander respectively.","url":"https://en.wikipedia.org/wiki/Primus_(band)"},"livingcolour":{"title":"Living Colour","desc":"American rock band","text":"Living Colour is an American rock band from New York City, formed in 1984. The band consists of guitarist Vernon Reid, lead vocalist Corey Glover, drummer Will Calhoun and bassist Doug Wimbish, who replaced Muzz Skillings in 1992. Their music is influenced by progressive rock, heavy metal, funk, jazz, hip-hop, punk, alternative rock, delta blues, doo-wop, swing music, ska, yacht rock and barbershop quartet.","url":"https://en.wikipedia.org/wiki/Living_Colour"},"dethklok":{"title":"Dethklok","desc":"Animated American metal band","text":"Dethklok is a melodic death metal virtual band featured in the Adult Swim animated television series Metalocalypse, known for its satirical or parodic lyrical themes.","url":"https://en.wikipedia.org/wiki/Dethklok"},"cheaptrick":{"title":"Cheap Trick","desc":"American rock band","text":"Cheap Trick is an American rock band formed in Rockford, Illinois, in 1973. The band's work bridged elements of 1960s guitar pop, 1970s hard rock, and the emerging punk rock sound, and helped set the template for subsequent power pop artists.","url":"https://en.wikipedia.org/wiki/Cheap_Trick"},"boston":{"title":"Boston (band)","desc":"American rock band","text":"Boston is an American rock band formed in 1975 in Boston, Massachusetts, by chief songwriter and composer Tom Scholz. The band's core members included multi-instrumentalist Scholz and lead vocalist Brad Delp, who remained the only constant members from 1975 to 1990, and from 1994 until Delp's suicide in 2007. Other musicians and members of the band varied largely across the group's lineup history.","url":"https://en.wikipedia.org/wiki/Boston_(band)"},"heart":{"title":"Heart (band)","desc":"American rock band","text":"Heart is an American rock band formed in 1974 in the Pacific Northwest. The band coalesced from previous projects by founding members including the Army (1967–1969), Hocus Pocus (1969–1970), and White Heart (1970–1973). By 1975, the band’s lineup coalesced with Ann Wilson and Nancy Wilson, Michael Derosier (drums), Howard Leese, Roger Fisher (guitar) and Steve Fossen. These core members were included in the band's 2013 induction into the Rock and Roll Hall of Fame.","url":"https://en.wikipedia.org/wiki/Heart_(band)"},"thecult":{"title":"The Cult","desc":"English rock band","text":"The Cult are an English rock band formed in Bradford in 1983. Before settling on its current name in January 1984, the band had performed under the name Death Cult, which was an evolution of the name of lead vocalist Ian Astbury's previous band Southern Death Cult.","url":"https://en.wikipedia.org/wiki/The_Cult"},"ufo":{"title":"UFO (band)","desc":"English rock band","text":"UFO were an English rock band formed in London in 1968. They became a transitional group between early hard rock and heavy metal and the new wave of British heavy metal (NWOBHM). The band's final line-up consisted of vocalist Phil Mogg, lead guitarist Vinnie Moore, rhythm guitarist and keyboardist Neil Carter, bass guitarist Rob De Luca, and drummer Andy Parker. They had gone through several line-up changes, leaving Mogg as the only constant member, and had disbanded three times.","url":"https://en.wikipedia.org/wiki/UFO_(band)"},"badco":{"title":"Bad Company","desc":"British rock band","text":"Bad Company were an English rock supergroup formed in London in 1973 by singer Paul Rodgers and drummer Simon Kirke, both formerly members of Free, former Mott the Hoople guitarist Mick Ralphs and former King Crimson bassist Boz Burrell. Only Kirke remained a member throughout the band's entire run, and he and Ralphs were the only members to appear on every studio album. Peter Grant, who managed the rock band Led Zeppelin, also managed Bad Company until 1982.","url":"https://en.wikipedia.org/wiki/Bad_Company"},"wishboneash":{"title":"Wishbone Ash","desc":"British rock band","text":"Wishbone Ash are a British rock band who achieved success in the early to mid-1970s.","url":"https://en.wikipedia.org/wiki/Wishbone_Ash"},"statusquo":{"title":"Status Quo (band)","desc":"British rock band","text":"Status Quo are an English rock band formed in London in 1962. Beginning with \"Pictures of Matchstick Men\" in 1968, they have had over 60 chart hits in the UK – more than any other band – with further hits including \"Caroline\", \"Down Down\", \"Rain\", \"Rockin' All Over the World\", \"Whatever You Want\" and \"What You're Proposing\". 22 of these reached the Top 10 in the UK singles chart, and 57 reached the Top 40.","url":"https://en.wikipedia.org/wiki/Status_Quo_(band)"},"skidrow":{"title":"Skid Row (American band)","desc":"American rock band","text":"Skid Row is an American hard rock/heavy metal band formed in 1986 in Toms River, New Jersey. Their current lineup comprises bassist Rachel Bolan, guitarists Dave Sabo and Scotti Hill, and drummer Rob Hammersmith. The group achieved commercial success with their multi-platinum albums Skid Row (1989) and Slave to the Grind (1991), the latter of which reached number one on the Billboard 200.","url":"https://en.wikipedia.org/wiki/Skid_Row_(American_band)"},"dokken":{"title":"Dokken","desc":"American heavy metal band","text":"Dokken is an American heavy metal band formed in Los Angeles in 1978. It split up in 1989 and reformed four years later. The band has had several singles that charted on the Billboard Hot 100, such as \"Alone Again\", \"In My Dreams\", and \"Burning Like a Flame\", and has sold more than ten million albums worldwide. The live album Beast from the East was nominated for the inaugural Grammy Award for Best Metal Performance in 1989.","url":"https://en.wikipedia.org/wiki/Dokken"},"quietriot":{"title":"Quiet Riot","desc":"American heavy metal band","text":"Quiet Riot is an American heavy metal band formed in Los Angeles in 1973 by guitarist Randy Rhoads, bassist Kelly Garni, and vocalist Kevin DuBrow.","url":"https://en.wikipedia.org/wiki/Quiet_Riot"},"europe":{"title":"Europe (band)","desc":"Swedish rock band","text":"Europe is a Swedish rock band formed in Upplands Väsby in 1979, by lead vocalist Joey Tempest, guitarist John Norum, bassist Peter Olsson, and drummer Tony Reno. Named after the continent itself, they obtained a major breakthrough in Sweden in 1982 by winning the televised competition Rock-SM ; it was the first time this competition was held.","url":"https://en.wikipedia.org/wiki/Europe_(band)"},"tesla":{"title":"Tesla (band)","desc":"American hard rock band","text":"Tesla is an American hard rock band from Sacramento, California. In late 1981, bassist Brian Wheat and guitarist Frank Hannon formed a band named City Kidd, which evolved into Tesla. By 1984, vocalist Jeff Keith, guitarist Tommy Skeoch and drummer Troy Luccketta had joined the band, forming their classic lineup that appeared on all the records and live shows during their initial run.","url":"https://en.wikipedia.org/wiki/Tesla_(band)"},"greatwhite":{"title":"Great White","desc":"American rock band","text":"Great White is an American hard rock band formed in Los Angeles in 1977. The band is named after both the shark with the same name, and guitarist Mark Kendall's former stage nickname. In August 2008, the band estimated they had sold around eight million records worldwide.","url":"https://en.wikipedia.org/wiki/Great_White"},"extreme":{"title":"Extreme (band)","desc":"American rock band","text":"Extreme is an American rock band formed in Boston, Massachusetts, in 1985, that reached the height of their popularity in the late 1980s and early 1990s. They have released six studio albums, two EPs and two compilation albums since their formation. The band was one of the most successful rock acts of the early 1990s, selling over 10 million albums worldwide.","url":"https://en.wikipedia.org/wiki/Extreme_(band)"},"motthehoople":{"title":"Mott the Hoople","desc":"British rock band","text":"Mott the Hoople were an English rock band formed in Hereford, Herefordshire in 1966. Originally named the Doc Thomas Group, the band changed their name after signing with Island Records in 1969. The band released albums at the beginning of the 1970s but failed to find any success. On the verge of breaking up, the band were encouraged by David Bowie to stay together. Bowie wrote their glam-style signature song \"All the Young Dudes\" for them, which became their first hit in 1972.","url":"https://en.wikipedia.org/wiki/Mott_the_Hoople"},"girlschool":{"title":"Girlschool","desc":"British, all-female, heavy metal band","text":"Girlschool are a British rock band that formed in the new wave of British heavy metal scene in 1978. Frequently associated with contemporaries Motörhead, they are the longest-running all-female rock band, still active after more than 40 years. Formed from a school band called Painted Lady, Girlschool enjoyed strong media exposure and commercial success in the UK in the early 1980s with three albums of \"punk-tinged metal\" and a few singles, but lost their momentum in the following years.","url":"https://en.wikipedia.org/wiki/Girlschool"},"tygers":{"title":"Tygers of Pan Tang","desc":"British heavy metal band","text":"Tygers of Pan Tang are an English heavy metal band that were a part of the new wave of British heavy metal movement. They formed in 1978 in Whitley Bay, England, and were active until 1987. The band reformed in 1999 and continue to record and perform. The name is derived from Pan Tang, a fictional archipelago in Michael Moorcock's Elric of Melniboné fantasy series whose wizards keep tigers as pets.","url":"https://en.wikipedia.org/wiki/Tygers_of_Pan_Tang"},"angelwitch":{"title":"Angel Witch","desc":"English heavy metal band","text":"Angel Witch are a British heavy metal band which formed in London in 1976, recognised as one of the pioneering groups of the new wave of British heavy metal (NWOBHM).","url":"https://en.wikipedia.org/wiki/Angel_Witch"},"raven":{"title":"Raven (British band)","desc":"English heavy metal band","text":"Raven are an English heavy metal band, formed in 1974 by the Gallagher brothers, bassist and vocalist John and guitarist Mark. They have released fifteen studio albums to date, and had a hit with the single \"On and On\".","url":"https://en.wikipedia.org/wiki/Raven_(British_band)"},"samson":{"title":"Samson (band)","desc":"British heavy metal band","text":"Samson were a British heavy metal band formed in 1977 by guitarist and vocalist Paul Samson. They are best known for their first three albums with future Iron Maiden singer Bruce Dickinson, then known as \"Bruce Bruce\", and drummer Thunderstick, who wore a leather mask and performed on stage in a metal cage. Drummer Clive Burr was also a member of the band, both before and after his tenure with Iron Maiden.","url":"https://en.wikipedia.org/wiki/Samson_(band)"},"satan":{"title":"Satan (band)","desc":"British heavy metal band","text":"Satan are an English heavy metal band originating from Newcastle upon Tyne in 1979, known as part of the new wave of British heavy metal movement. The band is considered influential for playing a form of proto-thrash/speed metal that was fairly advanced by the standards of the early 1980s.","url":"https://en.wikipedia.org/wiki/Satan_(band)"},"tank":{"title":"Tank (band)","desc":"British heavy metal band","text":"Tank are an English heavy metal band formed in 1980 by Algy Ward, a former member of The Damned. The original band is known as part of the new wave of British heavy metal movement. Tank was often compared to Motörhead as both bands were trios fronted by singing bassists, and played a loose, almost punk-styled metal music with often colourful lyrics.","url":"https://en.wikipedia.org/wiki/Tank_(band)"},"anvil":{"title":"Anvil (band)","desc":"Canadian heavy metal band","text":"Anvil is a Canadian heavy metal band formed in Toronto in 1978. The band currently consists of founding members guitarist/vocalist Steve \"Lips\" Kudlow and drummer Robb Reiner, along with bassist Chris Robertson who joined in 2014. As of 2024, the band has released twenty studio albums; they have been cited as having influenced many notable heavy metal groups including Megadeth, Slayer, Anthrax, and Metallica.","url":"https://en.wikipedia.org/wiki/Anvil_(band)"},"exciter":{"title":"Exciter (band)","desc":"Canadian speed metal band","text":"Exciter was a Canadian speed metal band formed in Ottawa, Ontario, in 1978. Named after a Judas Priest song, they are considered one of the first speed metal bands, and cited as an influence on thrash metal. Through personnel changes and three disbandments, Exciter has enjoyed limited commercial success.","url":"https://en.wikipedia.org/wiki/Exciter_(band)"},"cirithungol":{"title":"Cirith Ungol (band)","desc":"American heavy metal band","text":"Cirith Ungol is an American heavy metal band formed in late 1971 in Ventura, California. An early doom and power metal group, Cirith Ungol is known for lyrics based on fantasy. The band is named after the mountain pass Cirith Ungol in J. R. R. Tolkien's The Lord of the Rings.","url":"https://en.wikipedia.org/wiki/Cirith_Ungol_(band)"},"manillaroad":{"title":"Manilla Road","desc":"American heavy metal band","text":"Manilla Road was an American heavy metal band from Wichita, Kansas, founded by Mark \"The Shark\" Shelton and Scott \"Scooter\" Park (bass). Beginning in 1977, the early years of Manilla Road were spent playing mostly hard rock, psychedelic rock and progressive rock but eventually became noticeably heavier with time, the band's later heavy metal sound becoming more and more apparent with the release of Crystal Logic in 1983.","url":"https://en.wikipedia.org/wiki/Manilla_Road"},"omen":{"title":"Omen (band)","desc":"American heavy metal band","text":"Omen is an American heavy metal band formed in Los Angeles in 1983 by lead guitarist Kenny Powell.","url":"https://en.wikipedia.org/wiki/Omen_(band)"},"armoredsaint":{"title":"Armored Saint","desc":"American heavy metal band","text":"Armored Saint is an American heavy metal band formed in Los Angeles, California in 1982. Since 1990, the band has consisted of John Bush on lead vocals, Joey Vera on bass, Jeff Duncan on guitar and the Sandoval brothers on drums and guitar, respectively. Of the current lineup, Bush and Vera are the two constant members. To date, the band has released nine studio albums, one EP, two live albums and one compilation album.","url":"https://en.wikipedia.org/wiki/Armored_Saint"},"virginsteele":{"title":"Virgin Steele","desc":"American heavy metal band","text":"Virgin Steele is an American heavy metal band from New York, originally formed in 1981.","url":"https://en.wikipedia.org/wiki/Virgin_Steele"},"gravedigger":{"title":"Grave Digger (band)","desc":"German heavy metal band","text":"Grave Digger is a German heavy metal band that was first formed in 1980 by Chris Boltendahl and Peter Masson. Emerging from the 1980s German heavy/power/speed metal scene, they are considered part of the scene's \"big four\" alongside Helloween, Rage and Running Wild.","url":"https://en.wikipedia.org/wiki/Grave_Digger_(band)"},"runningwild":{"title":"Running Wild (band)","desc":"German heavy metal band","text":"Running Wild is a German heavy metal band formed in Hamburg in 1976. They were part of the German heavy metal scene to emerge in the early to mid-1980s and are considered part of the scene's \"big four\" alongside Grave Digger, Helloween and Rage. Over the course of their career, they have released 17 studio albums, three live albums, five compilation albums, and six singles/EPs.","url":"https://en.wikipedia.org/wiki/Running_Wild_(band)"},"primalfear":{"title":"Primal Fear (band)","desc":"German power metal band","text":"Primal Fear is a German power metal band formed in 1997 by Ralf Scheepers and Mat Sinner. Sinner and Scheepers formed the band after Scheepers was not hired as Rob Halford's replacement in Judas Priest.","url":"https://en.wikipedia.org/wiki/Primal_Fear_(band)"},"edguy":{"title":"Edguy","desc":"German power metal band","text":"Edguy is a German power metal band formed in Fulda in 1992.","url":"https://en.wikipedia.org/wiki/Edguy"},"powerwolf":{"title":"Powerwolf","desc":"German power metal band","text":"Powerwolf is a German power metal band founded in 2004 in Saarbrücken by members of Red Aim. The band consists of vocalist Karsten Brill as \"Attila Dorn\", lead guitarist Benjamin Buss as \"Matthew Greywolf\", bassist/rhythm guitarist David Vogt as \"Charles Greywolf\", keyboardist Christian Jost as \"Falk Maria Schlegel\" and drummer Roel van Helden.","url":"https://en.wikipedia.org/wiki/Powerwolf"},"gloryhammer":{"title":"Gloryhammer","desc":"British power metal band","text":"Gloryhammer are a British power metal band founded by keyboardist Christopher Bowes, lead vocalist of the band Alestorm. Each member of the band represents a character in the story concept. Band members appear on stage in armour and costumes to represent their respective characters.","url":"https://en.wikipedia.org/wiki/Gloryhammer"},"kamelot":{"title":"Kamelot","desc":"American power metal band","text":"Kamelot is an American power metal band from Tampa, Florida, formed by Thomas Youngblood in 1987. The Norwegian vocalist Roy Khan joined for the album Siége Perilous, and shared songwriting credit with Youngblood until his departure in April 2011. On June 22, 2012, Youngblood announced on their website that their new vocalist would be the Swedish singer Tommy Karevik, who was first featured on Kamelot's album Silverthorn as the main vocalist, co-songwriter, and lyricist.","url":"https://en.wikipedia.org/wiki/Kamelot"},"avantasia":{"title":"Avantasia","desc":"German heavy metal supergroup","text":"Avantasia is a German power metal supergroup with influences of opera and hard rock created by Tobias Sammet, vocalist of the band Edguy. It has been characterized as a rock opera, as it features the contributions of various vocalists and musicians and it consists of concept albums. The name is a blend of the words Avalon and fantasia ('fantasy') and describes \"a world beyond human imagination\".","url":"https://en.wikipedia.org/wiki/Avantasia"},"icedearth":{"title":"Iced Earth","desc":"American heavy metal band","text":"Iced Earth is an American heavy metal band currently composed of only bandleader Jon Schaffer, formed in Tampa, Florida, and based in Columbus, Indiana. They were formed in 1984 under the name the Rose, then Purgatory, by guitarist and main songwriter Schaffer and original drummer Greg Seymour. Iced Earth released their debut album in 1990 and have since released twelve studio albums, four EPs, three compilations, three box sets, three live albums and eleven music videos.","url":"https://en.wikipedia.org/wiki/Iced_Earth"},"savatage":{"title":"Savatage","desc":"American heavy metal band","text":"Savatage is an American heavy metal band founded by brothers Jon and Criss Oliva in 1979 in Tarpon Springs, Florida. The band was first called Avatar, but, shortly before the release of their debut album Sirens (1983), they changed their name to Savatage, as Avatar was already taken by at least one other band. Savatage is considered to be an integral part of the American heavy metal movement of the early-to-mid-1980s and has been cited as a key influence on numerous metal genres.","url":"https://en.wikipedia.org/wiki/Savatage"},"deathangel":{"title":"Death Angel","desc":"American thrash metal band","text":"Death Angel is a Filipino-American thrash metal band from San Francisco, California. They were originally active from 1982 to 1991, and again since 2001. They have released nine studio albums, two demo tapes, one box set, and three live albums. The band has gone through several lineup changes; lead guitarist Rob Cavestany has been the only constant member through the band's history.","url":"https://en.wikipedia.org/wiki/Death_Angel"},"violence":{"title":"Vio-lence","desc":"American thrash metal band","text":"Vio-lence is an American thrash metal band formed in 1985 in the San Francisco Bay Area. Throughout its career, they have released demo tapes, three EPs and three studio albums. Vio-lence is best-known for their association with the 1980s Bay Area thrash metal scene, and often credited as one of the leading lights of the second wave of the genre.","url":"https://en.wikipedia.org/wiki/Vio-lence"},"forbidden":{"title":"Forbidden (band)","desc":"American thrash metal band","text":"Forbidden is an American thrash metal band from the San Francisco Bay Area, California. They formed in 1985 as Forbidden Evil, but changed their name in 1987. Forbidden have broken up and reformed twice, with numerous line-up changes. After breaking up for the first time in 2001, Forbidden reunited in 2007, went into an indefinite hiatus in 2012, and reformed in 2023. The current line-up consists of Norman Skinner (vocals), Craig Locicero (guitar), Matt Camacho (bass), and Chris Kontos (drums).","url":"https://en.wikipedia.org/wiki/Forbidden_(band)"},"heathen":{"title":"Heathen (band)","desc":"American thrash metal band","text":"Heathen is an American thrash metal band from the San Francisco Bay Area, active from 1984 to 1993 and from 2001 onwards. Despite lacking commercial success, the band is credited – alongside Exodus, Testament, Forbidden, Death Angel and Vio-lence – as a leader of the Bay Area thrash metal scene of the mid-to-late 1980s. To date, Heathen has released four studio albums: Breaking the Silence (1987), Victims of Deception (1991), The Evolution of Chaos (2009) and Empire of the Blind (2020).","url":"https://en.wikipedia.org/wiki/Heathen_(band)"},"nuclearassault":{"title":"Nuclear Assault","desc":"American thrash metal band","text":"Nuclear Assault was an American thrash metal band formed in New York City in 1984. Part of the mid-to-late 1980s thrash metal movement, they were one of the main bands of the genre to emerge from the East Coast, along with Overkill, Whiplash, Toxik, Carnivore, and Anthrax, the last of which was co-founded by Nuclear Assault bassist Dan Lilker, who had been fired from Anthrax shortly after the release of their first album.","url":"https://en.wikipedia.org/wiki/Nuclear_Assault"},"sacredreich":{"title":"Sacred Reich","desc":"American thrash metal band","text":"Sacred Reich is an American thrash metal band formed in Phoenix, Arizona, in 1985. As of 2025, the band's lineup has consisted of vocalist-bassist Phil Rind, lead guitarist Wiley Arnett, rhythm guitarist Joey Radziwill, and drummer Eduardo Baldo. Former members include rhythm guitarist Jason Rainey, and drummers Greg Hall and Dave McClain. Their music features mid-tempo song structures and influences from punk rock and hardcore punk.","url":"https://en.wikipedia.org/wiki/Sacred_Reich"},"darkangel":{"title":"Dark Angel (band)","desc":"American thrash metal band","text":"Dark Angel is an American thrash metal band from Downey, California, formed in 1981. Following a breakup in 1992 and a reunion from 2002 to 2005, the band reunited a second time in 2013. Dark Angel's current lineup includes lead guitarist Eric Meyer, drummer Gene Hoglan, lead vocalist Ron Rinehart, bassist Mike Gonzalez, and rhythm guitarist Laura Christine.","url":"https://en.wikipedia.org/wiki/Dark_Angel_(band)"},"flotsam":{"title":"Flotsam and Jetsam (band)","desc":"American thrash metal band","text":"Flotsam and Jetsam is an American thrash metal band that was formed in Phoenix, Arizona, in 1981. Before settling on its name in 1984, the band was known as Paradox, Dredlox and The Dogz. K\" Knutson, guitarists Michael Gilbert and Steve Conley, bassist Bill Bodily, and drummer Ken Mary. Flotsam and Jetsam went through several lineup changes over the years, leaving Knutson as the only constant member.","url":"https://en.wikipedia.org/wiki/Flotsam_and_Jetsam_(band)"},"onslaught":{"title":"Onslaught (band)","desc":"British thrash metal band","text":"Onslaught are a British thrash metal band from Bristol, England, active from 1982 to 1991 and again since 2005. The band drew influences from US and British hardcore punk bands such as Discharge and the Exploited, as well as the new wave of British heavy metal (NWOBHM), and eventually adopted a straightforward thrash metal sound. Jason Anderson of AllMusic described their sound as \"punishing\".","url":"https://en.wikipedia.org/wiki/Onslaught_(band)"},"sabbat":{"title":"Sabbat (Japanese band)","desc":"Japanese metal band","text":"Sabbat is a Japanese black/thrash metal band formed in the early 1980s. On some releases, they showcase a traditional metal sound.","url":"https://en.wikipedia.org/wiki/Sabbat_(Japanese_band)"},"annihilator":{"title":"Annihilator (band)","desc":"Canadian thrash metal band","text":"Annihilator is a Canadian thrash metal band, formed in Ottawa, Ontario in 1984 by Jeff Waters. Waters is the band's sole constant member and has acted as its guitarist, bandleader, writer, producer, engineer, and occasional bassist and vocalist. Annihilator has released seventeen studio albums and has undergone many line-up changes, with Waters regularly assembling touring or session musicians to perform with him.","url":"https://en.wikipedia.org/wiki/Annihilator_(band)"},"voivod":{"title":"Voivod (band)","desc":"Canadian heavy metal band","text":"Voivod is a Canadian heavy metal band formed in Jonquière, Quebec in 1982. The original line-up consisted of vocalist Denis \"Snake\" Bélanger, guitarist Denis \"Piggy\" D'Amour, drummer Michel \"Away\" Langevin and bassist Jean-Yves \"Blacky\" Thériault. The band has had numerous members changes throughout its 44-year career, with Langevin as the only consistent member. As of 2014, the line-up includes Langevin, Bélanger, Daniel \"Chewy\" Mongrain (guitar) and Dominic \"Rocky\" Laroche (bass).","url":"https://en.wikipedia.org/wiki/Voivod_(band)"},"coroner":{"title":"Coroner (band)","desc":"Swiss thrash metal band","text":"Coroner is a Swiss thrash metal band from Zürich, active from 1983 to 1996 and again from 2010 onward. P. (1987), Punishment for Decadence (1988), No More Color (1989), Mental Vortex (1991), Grin (1993) and Dissonance Theory (2025).","url":"https://en.wikipedia.org/wiki/Coroner_(band)"},"artillery":{"title":"Artillery (band)","desc":"Danish thrash metal band","text":"Artillery is a Danish thrash metal band. They participated in the early development of the genre, and were pioneers in the Danish thrash metal scene with their highly energetic, riff-centric and often fast-paced music. After releasing three full-length albums and touring extensively throughout the 1980s and early 1990s, Artillery disbanded in 1991, but reunited seven years later, only to disband once again in 2000.","url":"https://en.wikipedia.org/wiki/Artillery_(band)"},"tankard":{"title":"Tankard (band)","desc":"German thrash metal band","text":"Tankard is a German thrash metal band from Frankfurt, founded in 1982. Alongside Kreator, Destruction and Sodom, Tankard is often considered one of the \"Big Four\" of Teutonic thrash metal. Stylistically, Tankard has consistently played thrash metal that thematically centres primarily on alcohol reverence, unlike the remaining \"Big Teutonic Four\", who are all known for covering such topics related to death, politics, violence and anti-fascism.","url":"https://en.wikipedia.org/wiki/Tankard_(band)"},"exhorder":{"title":"Exhorder","desc":"American thrash/groove metal band","text":"Exhorder is an American heavy metal band from New Orleans, Louisiana. The band currently consists of vocalist and rhythm guitarist Kyle Thomas, bassist Jason VieBrooks, lead guitarist Pat O'Brien and touring drummer Corey Pierce.","url":"https://en.wikipedia.org/wiki/Exhorder"},"prong":{"title":"Prong (band)","desc":"American heavy metal band","text":"Prong is an American heavy metal band formed in New York City in 1986. The band is fronted by guitarist/vocalist Tommy Victor, Prong's sole constant member. The band was originally composed of Victor, bassist Mike Kirkland, and drummer Ted Parsons. Their first two studio releases, the mini-album Primitive Origins (1987) and full-length album Force Fed (1988), were released independently and leaned into the crossover thrash genre.","url":"https://en.wikipedia.org/wiki/Prong_(band)"},"municipalwaste":{"title":"Municipal Waste (band)","desc":"American metal band","text":"Municipal Waste is an American crossover thrash band formed in Richmond, Virginia, in 2000. The band has released seven studio albums, three EPs, and four splits. Lineup changes have left vocalist Tony Foresta and rhythm guitarist Ryan Waste as the only constant members. In addition to Foresta and Waste, their current lineup includes bassist Philip \"Land Phil\" Hall, drummer Dave Witte, and Nick \"Nikropolis\" Poulos on lead guitar.","url":"https://en.wikipedia.org/wiki/Municipal_Waste_(band)"},"powertrip":{"title":"Power Trip (band)","desc":"American thrash metal band","text":"Power Trip is an American crossover thrash band formed in Dallas, Texas, in 2008. By 2020, Power Trip's lineup consisted of Riley Gale, Blake Ibanez, Nick Stewart, Chris Whetzel (bass) and Chris Ulsh (drums); the latter replaced drummer Marcus Johnson, who left in 2009. Drummer Mark Rubin played and recorded with the group at its formation in 2008 before departing within several months.","url":"https://en.wikipedia.org/wiki/Power_Trip_(band)"},"havok":{"title":"Havok (band)","desc":"American thrash metal band","text":"Havok is an American thrash metal band formed Denver, Colorado, in 2004. As of 2024, their lineup consists of frontman David Sanchez, drummer Pete Webber, and bassist Nick Schendzielos. They have gone through several personnel changes. Each album has featured a different lineup. Sanchez is the only remaining original member.","url":"https://en.wikipedia.org/wiki/Havok_(band)"},"vektor":{"title":"Vektor (band)","desc":"American thrash metal band","text":"Vektor is an American technical thrash metal band from Tempe, Arizona, and based in Philadelphia since 2012. Their music deals with scientific, philosophical, futuristic, and astronomical topics.","url":"https://en.wikipedia.org/wiki/Vektor_(band)"},"deicide":{"title":"Deicide (band)","desc":"American death metal band","text":"Deicide is an American death metal band from Tampa, Florida. They formed in 1987 with drummer Steve Asheim and guitarist brothers Eric and Brian Hoffman as Carnage, then hired bassist and vocalist Glen Benton and became Amon. They renamed to Deicide in 1989. The band rose to mainstream success in 1992 with their second album, Legion, and is credited as the second-best-selling death metal band of the Soundscan Era, after Cannibal Corpse.","url":"https://en.wikipedia.org/wiki/Deicide_(band)"},"malevolentcreation":{"title":"Malevolent Creation","desc":"American death metal band","text":"Malevolent Creation is an American death metal band formed in Buffalo, New York in 1987 and later based in Fort Lauderdale, Florida. The band's original members were guitarists Phil Fasciana and Jim Nickles and vocalist Bret Hoffmann, who were joined by bassist Jason Blachowicz and drummer Dennis Kubas the following year. Fasciana is the only founding member who stayed with the band consistently.","url":"https://en.wikipedia.org/wiki/Malevolent_Creation"},"incantation":{"title":"Incantation (American band)","desc":"American death metal band","text":"Incantation is an American death metal band formed by John McEntee and Paul Ledney in 1989. Despite the band's members residing in Johnstown, Pennsylvania, Incantation are considered leaders in the New York City death metal scene with Suffocation, Mortician and Immolation.","url":"https://en.wikipedia.org/wiki/Incantation_(American_band)"},"immolation":{"title":"Immolation (band)","desc":"American death metal band","text":"Immolation is an American death metal band from Yonkers, New York, formed in 1986 as Rigor Mortis. They are considered leaders of the New York death metal scene along with Incantation, Mortician and Suffocation. Currently, Immolation consists of founding members Robert Vigna, Ross Dolan, Steve Shalaty (drums), and Alex Bouks. They have released 12 studio albums, the latest being Descent on April 10, 2026.","url":"https://en.wikipedia.org/wiki/Immolation_(band)"},"hateeternal":{"title":"Hate Eternal","desc":"American death metal band","text":"Hate Eternal is a Florida death metal band from St. Petersburg, Florida. J. Hrubovcak and drummer John Longstreth. To date, Hate Eternal has released seven studio albums: Conquering the Throne (1999), King of All Kings (2002), I, Monarch (2005), Fury & Flames (2008), Phoenix Amongst the Ashes (2011), Infernus (2015), and Upon Desolate Sands (2018). All albums were produced by Rutan.","url":"https://en.wikipedia.org/wiki/Hate_Eternal"},"atheist":{"title":"Atheist (band)","desc":"American death metal band","text":"Atheist is an American death metal band from Sarasota, Florida, formed in 1987.","url":"https://en.wikipedia.org/wiki/Atheist_(band)"},"cynic":{"title":"Cynic (band)","desc":"American progressive metal band","text":"Cynic is an American progressive metal band formed in Miami, Florida in 1987. Paul Masvidal was originally the band's guitarist, but later took over as lead vocalist and chief songwriter. Cynic incorporates progressive rock, alternative, and metal.","url":"https://en.wikipedia.org/wiki/Cynic_(band)"},"gorguts":{"title":"Gorguts","desc":"Canadian death metal band","text":"Gorguts is a Canadian death metal band formed near Sherbrooke, Quebec, in 1989. Since its inception, the band has undergone numerous membership changes. The sole constant member has been co-founding member and guitarist-vocalist Luc Lemay, who remains the band's driving force. To date, they have released five full-length albums and one EP. Their most recent release, Pleiades' Dust, was released on May 13, 2016.","url":"https://en.wikipedia.org/wiki/Gorguts"},"pestilence":{"title":"Pestilence (band)","desc":"Dutch death metal band","text":"Pestilence is a Dutch death metal band founded in Enschede in 1986. Despite various lineup changes, guitarist-vocalist Patrick Mameli remains the sole constant member. After disbanding in 1994 to pursue other musical directions, Pestilence reunited in 2008, but was put on \"permanent hold\" in July 2014. The band reunited again in October 2016. Pestilence has released ten studio albums, and are one of technical death metal's \"big four\", with Death, Atheist, and Cynic.","url":"https://en.wikipedia.org/wiki/Pestilence_(band)"},"dyingfetus":{"title":"Dying Fetus","desc":"American death metal band","text":"Dying Fetus is an American death metal band from Greater Upper Marlboro, Maryland, formed in 1991. Lineup changes throughout the years have left John Gallagher as the sole remaining original member and the band's driving force. According to Gallagher, the band name was chosen while the members were young and was intended to be offensive. To date, Dying Fetus has released nine studio albums.","url":"https://en.wikipedia.org/wiki/Dying_Fetus"},"cryptopsy":{"title":"Cryptopsy","desc":"Canadian death metal band","text":"Cryptopsy is a Canadian death metal band from Montreal. Founded in 1992, the band initially consisted of drummer Mike Atkin, guitarist Steve Thibault, and vocalist Dan \"Lord Worm\" Greening. An earlier incarnation of the band started in 1988 as Obsessive Compulsive Disorder, releasing numerous demos before disbanding and regrouping with a new lineup as Cryptopsy, debuting with a demo tape titled Ungentle Exhumation (1993).","url":"https://en.wikipedia.org/wiki/Cryptopsy"},"obscura":{"title":"Obscura (band)","desc":"German technical death metal band","text":"Obscura is a German technical death metal band from Landshut, founded by guitarist and vocalist Steffen Kummerer in 2002. The band has released seven studio albums, a compilation album, and seventeen music videos since its formation. Their latest album, A Sonication, was released in February 2025.","url":"https://en.wikipedia.org/wiki/Obscura_(band)"},"kataklysm":{"title":"Kataklysm","desc":"Canadian death metal band","text":"Kataklysm is a Canadian death metal band. As of 2024, they have released fifteen studio albums, two EPs, and two DVDs. Kataklysm received their first Juno Award for Best Album of the Year in the \"Heavy Metal\" category for their 2015 album Of Ghosts and Gods.","url":"https://en.wikipedia.org/wiki/Kataklysm"},"brutaltruth":{"title":"Brutal Truth","desc":"American grindcore band","text":"Brutal Truth was an American grindcore band from New York City, formed by bass guitarist Dan Lilker in 1990. The group disbanded in 1999, but reformed in 2006 and continued to release music until 2014.","url":"https://en.wikipedia.org/wiki/Brutal_Truth"},"nasum":{"title":"Nasum","desc":"Swedish grindcore band","text":"Nasum was a Swedish grindcore band from Örebro, formed in 1992. The band released four studio albums and became \"one of that country's premier metal acts\". They disbanded after frontman Mieszko Talarczyk, was killed in the December 2004 Indian Ocean tsunami.","url":"https://en.wikipedia.org/wiki/Nasum"},"terrorizer":{"title":"Terrorizer","desc":"American grindcore band","text":"Terrorizer is an American deathgrind band from Los Angeles, California. It was formed in 1985 as Unknown Death by vocalist Oscar Garcia and guitarist Jesse Pintado. They renamed themselves Terrorizer after recruiting drummer Pete Sandoval, who is the band's sole constant member, in 1986. The band's lineup consists of Sandoval, guitarist Richie Brown and vocalist Antony Hämäläinen.","url":"https://en.wikipedia.org/wiki/Terrorizer"},"hypocrisy":{"title":"Hypocrisy (band)","desc":"Swedish melodic death metal band","text":"Hypocrisy is a Swedish melodic death metal band formed in October 1991 in Ludvika by Peter Tägtgren. The band has released thirteen studio albums.","url":"https://en.wikipedia.org/wiki/Hypocrisy_(band)"},"unleashed":{"title":"Unleashed (band)","desc":"Swedish death metal band","text":"Unleashed is a Swedish death metal band formed in 1989 by Johnny Hedlund in Stockholm. Lyrical themes include Viking culture, recollection of a pre-Christian world, and Norse folklore. A number of their recent songs contain references to J. R. R. Tolkien. Unleashed is considered one of the \"big four\" of Swedish death metal.","url":"https://en.wikipedia.org/wiki/Unleashed_(band)"},"grave":{"title":"Grave (band)","desc":"Swedish death metal band","text":"Grave is a Swedish death metal band that was formed in 1988 by vocalist and guitarist Ola Lindgren who is their only constant member. , Soulless and Hating Life, cemented their reputation as one of Sweden's foremost death metal bands. Grave went on hiatus in 1997, but got back together two years later. Since then, they have released seven more albums, making a total of eleven studio albums.","url":"https://en.wikipedia.org/wiki/Grave_(band)"},"archenemy":{"title":"Arch Enemy","desc":"Swedish melodic death metal band","text":"Arch Enemy is a Swedish melodic death metal band, originally a supergroup from Halmstad, formed in 1995. Its members have been in bands such as Carcass, Armageddon, Carnage, Mercyful Fate, Spiritual Beggars, The Agonist, Nevermore, Eucharist, and Once Human. Carcass guitarist Michael Amott founded Arch Enemy with Johan Liiva. They were both originally from death metal band Carnage.","url":"https://en.wikipedia.org/wiki/Arch_Enemy"},"soilwork":{"title":"Soilwork","desc":"Swedish melodic death metal band","text":"Soilwork is a Swedish melodic death metal band from Helsingborg. They have released twelve studio albums. It was formed in late 1995 by Björn Strid and Peter Wichers as Inferior Breed. In late 1996, they changed their name to Soilwork, which means \"working from the ground up\".","url":"https://en.wikipedia.org/wiki/Soilwork"},"childrenofbodom":{"title":"Children of Bodom","desc":"Finnish melodic death metal band","text":"Children of Bodom are a Finnish melodic death metal band from Espoo, Uusimaa. Formed in 1993 as Inearthed, the final line-up of the group upon their split in 2019 consisted of frontman Alexi Laiho, drummer Jaska Raatikainen, bassist Henkka Seppälä, keyboardist Janne Wirman and guitarist Daniel Freyberg. The band released ten studio albums, three live albums, two EPs, two compilation albums, and one DVD.","url":"https://en.wikipedia.org/wiki/Children_of_Bodom"},"insomnium":{"title":"Insomnium","desc":"Finnish melodic death metal band","text":"Insomnium is a Finnish melodic death metal band formed in Joensuu in 1997. Their sound and lyrics portray darkness, sorrow, loss, pain, and nature. Their music includes progressive metal and doom metal.","url":"https://en.wikipedia.org/wiki/Insomnium"},"whitechapel":{"title":"Whitechapel (band)","desc":"American deathcore band","text":"Whitechapel is an American deathcore band from Knoxville, Tennessee. The band is named after the Whitechapel district in east London, England, where Jack the Ripper committed a series of murders. The group comprises vocalist Phil Bozeman, guitarists Ben Savage, Alex Wade, and Zach Householder, bassist Gabe Crisp and drummer Brandon Zackey. Their core lineup, with the exception of the drummer, has remained consistent since Householder replaced original guitarist Brandon Cagle in 2007.","url":"https://en.wikipedia.org/wiki/Whitechapel_(band)"},"suicidesilence":{"title":"Suicide Silence","desc":"American deathcore band","text":"Suicide Silence is an American deathcore band from Riverside, California. The band was established in 2002, and has released seven studio albums, three EPs, and nineteen music videos. They were awarded the Revolver Golden God award for \"Best New Talent\" in 2009. The group currently consists of guitarists Chris Garza and Mark Heylmun, bassist Dan Kenny, vocalist Hernan \"Eddie\" Hermida and drummer Ernie Iniguez.","url":"https://en.wikipedia.org/wiki/Suicide_Silence"},"jobforacowboy":{"title":"Job for a Cowboy","desc":"American death metal band","text":"Job for a Cowboy is an American death metal band from Glendale, Arizona. Formed in 2003, the band's debut album, Genesis, was released in 2007, peaked at No. 54 on the US Billboard 200 and sold 13,000 copies in its first week of release. The second album, 2009's Ruination, sold 10,600 copies in the United States in its first week to debut at No. 42 on the Billboard 200 chart. The band comprises vocalist Jonny Davy, guitarists Tony Sannicandro and Al Glassman and bassist Nick Schendzielos.","url":"https://en.wikipedia.org/wiki/Job_for_a_Cowboy"},"allshallperish":{"title":"All Shall Perish","desc":"American deathcore band","text":"All Shall Perish is an American deathcore band from Oakland, California, formed in 2002. The band was signed to Nuclear Blast and has released four full-length albums through the label. Their latest album, This Is Where It Ends, was released in 2011.","url":"https://en.wikipedia.org/wiki/All_Shall_Perish"},"thyartismurder":{"title":"Thy Art Is Murder","desc":"Australian deathcore band","text":"Thy Art Is Murder is an Australian deathcore band from Blacktown, Sydney, that formed in 2006. The band consists of vocalist Jerry Grimefeld, guitarists Sean Delander and Andy Marsh, bassist Kevin Butler and drummer Jesse Beahler. Thy Art Is Murder has released six studio albums since formation.","url":"https://en.wikipedia.org/wiki/Thy_Art_Is_Murder"},"asilaydying":{"title":"As I Lay Dying (band)","desc":"American metalcore band","text":"As I Lay Dying is an American metalcore band from San Diego, California. Formed in 2000 by vocalist Tim Lambesis, the band's first full lineup was completed in 2001. The band has released eight albums, one split album, and two compilation albums.","url":"https://en.wikipedia.org/wiki/As_I_Lay_Dying_(band)"},"atreyu":{"title":"Atreyu","desc":"American rock band","text":"Atreyu is an American rock band from Yorba Linda, California, formed in 1998. The band's current line-up consists of guitarists Dan Jacobs and Travis Miguel, lead vocalist Brandon Saller, bassist and unclean vocalist Marc \"Porter\" McKnight and drummer Kyle Rosa.","url":"https://en.wikipedia.org/wiki/Atreyu"},"augustburnsred":{"title":"August Burns Red","desc":"American metalcore band","text":"August Burns Red is an American metalcore band from Lancaster, Pennsylvania, formed in 2003. The band's lineup of guitarists John Benjamin \"JB\" Brubaker and Brent Rambler, drummer Matt Greiner, lead vocalist Jake Luhrs and bassist Dustin Davidson has remained consistent since 2006.","url":"https://en.wikipedia.org/wiki/August_Burns_Red"},"allthatremains":{"title":"All That Remains (band)","desc":"American heavy metal band","text":"All That Remains is an American heavy metal band from Springfield, Massachusetts, formed in 1998. They have released ten studio albums, a live CD and DVD, and have sold over a million records worldwide. Established by vocalist Philip Labonte, the rest of the band consists of lead guitarist Ken Susi, rhythm guitarist Mike Martin, bassist Matt Deis and drummer Anthony Barone.","url":"https://en.wikipedia.org/wiki/All_That_Remains_(band)"},"unearth":{"title":"Unearth","desc":"American metalcore band","text":"Unearth is an American metalcore band formed in Boston, Massachusetts, in 1998. The group consists of lead guitarist Buz McGrath, vocalist Trevor Phipps, bassist Chris O'Toole, drummer Mike Justian and rhythm guitarist Peter Layman. They are currently signed to Metal Blade Records and have released eight studio albums. Their most recent studio album, The Wretched; the Ruinous, was released on May 5, 2023.","url":"https://en.wikipedia.org/wiki/Unearth"},"shadowsfall":{"title":"Shadows Fall","desc":"American metal band","text":"Shadows Fall is an American heavy metal band from Springfield, Massachusetts, formed in 1996. Although Shadows Fall has experienced several line-up changes, for most of its recording career, Shadows Fall has been composed of guitarists Jonathan Donais and Matt Bachand, bassist Paul Romanko, lead vocalist Brian Fair and drummer Jason Bittner.","url":"https://en.wikipedia.org/wiki/Shadows_Fall"},"darkesthour":{"title":"Darkest Hour (band)","desc":"American metal band","text":", formed in 1995. Though failing to break through early in their tenure, the band has received acclaim for their albums Undoing Ruin, Deliver Us, and The Eternal Return. Deliver Us debuted at number 110 on the Billboard album charts, with sales of 6,600, and their more recent effort, The Eternal Return, reached a higher position in the Billboard album charts at number 104.","url":"https://en.wikipedia.org/wiki/Darkest_Hour_(band)"},"burytomorrow":{"title":"Bury Tomorrow","desc":"British metalcore band","text":"Bury Tomorrow are a British metalcore band formed in 2006 in Southampton, Hampshire, England. The band is composed of six members; lead vocalist Daniel Winter-Bates, bassist Davyd Winter-Bates, drummer Adam Jackson, lead guitarist Kristan Dawson, who replaced founding guitarist Mehdi Vismara in 2013, rhythm guitarist Ed Hartwell, and keyboardist and vocalist Tom Prendergast, who both replaced Jason Cameron in 2021.","url":"https://en.wikipedia.org/wiki/Bury_Tomorrow"},"sylosis":{"title":"Sylosis","desc":"British heavy metal band","text":"Sylosis are a British heavy metal band formed in Reading, Berkshire, in 2000. Signed to Nuclear Blast Records, the band has released seven studio albums, a live album, two EPs and twelve music videos. Their latest album, The New Flesh, was released on February 20, 2026.","url":"https://en.wikipedia.org/wiki/Sylosis"},"motionlessinwhite":{"title":"Motionless in White","desc":"American metalcore band","text":"Motionless in White is an American metalcore band from Scranton, Pennsylvania. Formed in 2004, the band consists of lead vocalist Chris \"Motionless\" Cerulli, guitarists Ryan Sitkowski and Ricky \"Horror\" Olson, drummer Vinny Mauro and bassist Justin Morrow. Cerulli is the only member of the original line-up that remains in the band. The group has stated that their band name derived from the Eighteen Visions song \"Motionless and White\".","url":"https://en.wikipedia.org/wiki/Motionless_in_White"},"blackveilbrides":{"title":"Black Veil Brides","desc":"American rock band","text":"Black Veil Brides is an American rock band based in Hollywood, California. The group formed in 2006 in Cincinnati, Ohio, and is currently composed of lead vocalist Andy Biersack, multi instrumentalist Jinxx, lead guitarist Jake Pitts, drummer Christian \"CC\" Coma and bassist Lonny Eagleton. Black Veil Brides are known for their use of black makeup, body paint, tight black studded clothing, and long hair, which were all inspired by the stage personas of Kiss and Mötley Crüe, as well as other 1980s glam metal acts.","url":"https://en.wikipedia.org/wiki/Black_Veil_Brides"},"askingalexandria":{"title":"Asking Alexandria","desc":"English rock band","text":"Asking Alexandria are an English rock band formed in York, North Yorkshire, consisting of guitarist Cameron Liddell, drummer James Cassells, vocalist Danny Worsnop, and bassist Sam Bettley.","url":"https://en.wikipedia.org/wiki/Asking_Alexandria"},"iceninekills":{"title":"Ice Nine Kills","desc":"American heavy metal band","text":"Ice Nine Kills is an American heavy metal band from Boston, Massachusetts. The band's music is primarily described as horror-themed metalcore, but incorporates many other musical styles. It was originally a ska punk band called Ice Nine, formed in 2000 by high school friends Spencer Charnas and Jeremy Schwartz, before adopting a metalcore style in 2010. Charnas is currently the only remaining founding member.","url":"https://en.wikipedia.org/wiki/Ice_Nine_Kills"},"badomens":{"title":"Bad Omens","desc":"American metal band","text":"Bad Omens is an American heavy metal band from Richmond, Virginia. Their style is primarily metalcore and alternative metal, while their more recent music also includes dark pop, R&B and electronic elements. Formed in 2015 by vocalist and producer Noah Sebastian, guitarist Nicholas Ruffilo, and bassist Vincent Riquier, the band was later joined by guitarist and producer Joakim \"Jolly\" Karlsson and drummer Nick Folio.","url":"https://en.wikipedia.org/wiki/Bad_Omens"},"polaris":{"title":"Polaris (Australian band)","desc":"Australian metalcore band","text":"Polaris are an Australian metalcore band from Sydney. The band consists of vocalist Jamie Hails, guitarist Rick Schneider, bassist/vocalist Jake Steinhauser and drummer Daniel Furnari.","url":"https://en.wikipedia.org/wiki/Polaris_(Australian_band)"},"knockedloose":{"title":"Knocked Loose","desc":"American hardcore punk band","text":"Knocked Loose is an American hardcore punk band from Oldham County, Kentucky, formed in 2013 and currently signed to Pure Noise Records. The band released their debut studio album, Laugh Tracks, in September 2016 through Pure Noise Records, which was followed by A Different Shade of Blue in 2019. Their 2021 EP A Tear in the Fabric of Life incorporated elements of death metal and was released to widespread critical acclaim.","url":"https://en.wikipedia.org/wiki/Knocked_Loose"},"chimaira":{"title":"Chimaira","desc":"American heavy metal band","text":"Chimaira is an American heavy metal band from Cleveland, Ohio. Formed in August 1998, the band's name is derived from the word Chimera, a monstrous creature in Greek mythology. Throughout its history, the band had numerous line-up changes, leaving vocalist Mark Hunter as the only constant member. The band dissolved in 2014, but announced a reunion in 2017 and a return in 2023 with most of the group's longtime members rejoined.","url":"https://en.wikipedia.org/wiki/Chimaira"},"devildriver":{"title":"DevilDriver","desc":"American heavy metal band","text":"DevilDriver is an American heavy metal band from Santa Barbara, California, formed in 2002, consisting of vocalist Dez Fafara, bassist Jon Miller, lead guitarist Alex Lee, drummer Davier Pérez Ortega and rhythm guitarist Gabe Mangold. The band was originally named Deathride, but due to copyright issues and the name being used by several bands, they changed it to DevilDriver.","url":"https://en.wikipedia.org/wiki/DevilDriver"},"enslaved":{"title":"Enslaved (band)","desc":"Norwegian extreme metal band","text":"Enslaved is a Norwegian extreme metal band formed by Ivar Bjørnson and Grutle Kjellson in Haugesund in 1991. They are currently based in Bergen. The band's lineup has changed many times. Bjørnson and Kjellson are the sole constant members. The current lineup also includes lead guitarist Arve Isdal, keyboardist/singer Håkon Vinje, and drummer Iver Sandøy.","url":"https://en.wikipedia.org/wiki/Enslaved_(band)"},"marduk":{"title":"Marduk (band)","desc":"Swedish black metal band","text":"Marduk is a Swedish black metal band formed in Norrköping in 1990. The band released their debut full-length album, Dark Endless, in 1992 on No Fashion Records. They are named after Ancient Babylonian deity Marduk.","url":"https://en.wikipedia.org/wiki/Marduk_(band)"},"darkfuneral":{"title":"Dark Funeral","desc":"Swedish black metal band","text":"Dark Funeral is a Swedish black metal band from Stockholm, founded by guitarists Blackmoon and Lord Ahriman in 1993, during the second wave of black metal.","url":"https://en.wikipedia.org/wiki/Dark_Funeral"},"taake":{"title":"Taake","desc":"Norwegian black metal band","text":"Taake is a Norwegian black metal band from Bergen, formed in 1993 and originally named Thule. The band's one continuous member is Hoest, who writes all and records most of the music. Taake has released eight full-length albums and several EPs. The band describes itself as \"True Norwegian black metal\", and Hoest said he wants to \"awaken national pride and cultural nostalgia\" in Norwegian listeners as well as to remind people \"that Hell is right here on Earth and that humans can be demons\".","url":"https://en.wikipedia.org/wiki/Taake"},"rottingchrist":{"title":"Rotting Christ","desc":"Greek black metal band","text":"Rotting Christ is a Greek extreme metal band. Founded in Athens in 1987, they are described as \"one of the most influential, long-running metal bands to hail\" from their region.","url":"https://en.wikipedia.org/wiki/Rotting_Christ"},"samael":{"title":"Samael (band)","desc":"Swiss metal band","text":"Samael is a Swiss metal band formed in Sion in 1987. Their current lineup includes founding members and brothers Vorphalack (Vorph) and Xytraguptor (Xy), guitarist Drop, and bassist Ales. , Kaos, Mas and Makro.","url":"https://en.wikipedia.org/wiki/Samael_(band)"},"impalednazarene":{"title":"Impaled Nazarene","desc":"Finnish extreme metal band","text":"Impaled Nazarene is a Finnish extreme metal band that started as black metal but has incorporated grindcore, thrash metal and death metal, and grown towards hardcore punk.","url":"https://en.wikipedia.org/wiki/Impaled_Nazarene"},"beherit":{"title":"Beherit","desc":"Finnish black metal band","text":"Beherit is a Finnish black metal band from Rovaniemi. The band was formed in 1989 by Nuclear Holocausto Vengeance, Demonic Fornication and Sodomatic Slaughter, to perform \"the most primitive, savage, hell-obsessed black metal imaginable\". According to a source, \"Beherit\" is a Syriac word for a devil. Through their uncommercial music, visuals, and live performances, the band attracted a cult following.","url":"https://en.wikipedia.org/wiki/Beherit"},"blutausnord":{"title":"Blut Aus Nord","desc":"French black metal band","text":"Blut Aus Nord is a French black metal band from Mondeville, Calvados, that has incorporated avant-garde and industrial elements in its music.","url":"https://en.wikipedia.org/wiki/Blut_Aus_Nord"},"deathspell":{"title":"Deathspell Omega","desc":"French black metal band","text":"Deathspell Omega are a French black metal band formed in 1998. The group is an anonymous collective that has never confirmed the identity of its members.","url":"https://en.wikipedia.org/wiki/Deathspell_Omega"},"drudkh":{"title":"Drudkh","desc":"Ukrainian black metal band","text":"Drudkh is a Ukrainian black metal band. It consists of Roman Saenko, Thurios, Krechet, and Vlad. All four were members of Blood of Kingu until it was disbanded. Their lyrics and themes embrace Slavic mythology and Ukrainian nationalism. Many of the lyrics derive from the works of nineteenth and twentieth-century Ukrainian poets, especially Taras Shevchenko.","url":"https://en.wikipedia.org/wiki/Drudkh"},"agalloch":{"title":"Agalloch","desc":"American extreme metal band","text":"Agalloch is an American extreme metal band from Portland, Oregon. It was formed in 1995 by frontman John Haughm, with longterm members Don Anderson (guitar) and Jason William Walton (bass) joining after. The band's sound is rooted in atmospheric black metal, with characteristics of post-metal, folk metal and doom metal.","url":"https://en.wikipedia.org/wiki/Agalloch"},"ihsahn":{"title":"Ihsahn","desc":"Norwegian multi-instrumentalist, vocalist and composer","text":"Vegard Sverre Tveitan, better known by his stage name Ihsahn, is a Norwegian musician, singer, songwriter, record producer, and composer known for his work with black metal band Emperor. Tveitan is a founding member of Thou Shalt Suffer, where he played guitar and keyboard and sang, and Peccatum, a collaboration with wife and musician Heidi Solberg Tveitan, known as Starofash. Since 2006, Tveitan has focused on solo albums and occasional guest appearances.","url":"https://en.wikipedia.org/wiki/Ihsahn"},"witchfinder":{"title":"Witchfinder General (band)","desc":"British heavy metal band","text":"Witchfinder General was an English heavy/doom metal band from Stourbridge. They were named after the 1968 British horror film Witchfinder General, itself based upon the infamous witchhunter known as Matthew Hopkins.","url":"https://en.wikipedia.org/wiki/Witchfinder_General_(band)"},"solitude":{"title":"Solitude Aeturnus","desc":"American epic doom metal band","text":"Solitude Aeturnus is an American epic doom metal band from Arlington, Texas. Founded by guitarist John Perez in 1987, the band has released six studio albums. Their original name Solitude was chosen to pay homage to Black Sabbath and Candlemass, both of whom had songs bearing the name \"Solitude\".","url":"https://en.wikipedia.org/wiki/Solitude_Aeturnus"},"pallbearer":{"title":"Pallbearer (band)","desc":"American doom metal band","text":"Pallbearer is an American doom metal band from Little Rock, Arkansas, formed in 2008. While initially rooted in a fairly traditional sound at their beginning, their music is noted for expanding into progressive rock and alternative rock territories as their career has continued.","url":"https://en.wikipedia.org/wiki/Pallbearer_(band)"},"windhand":{"title":"Windhand","desc":"American doom metal band","text":"Windhand is an American stoner metal band formed in Richmond, Virginia, in 2008. Currently signed to Relapse Records, Windhand released their most recent album, Eternal Return, in October 2018.","url":"https://en.wikipedia.org/wiki/Windhand"},"theobsessed":{"title":"The Obsessed","desc":"American doom metal band","text":"The Obsessed is an American doom metal band from Potomac, Maryland, led by Scott \"Wino\" Weinrich. Formed in 1979, they recorded a few demos and played a handful of live shows until they first split up in 1986 when Weinrich joined as lead vocalist for Saint Vitus. About two years before his departure from Saint Vitus, Weinrich reformed The Obsessed in 1989, and three studio albums − The Obsessed (1990), Lunar Womb (1991) and The Church Within (1994) − were released before disbanding for the second time in 1995.","url":"https://en.wikipedia.org/wiki/The_Obsessed"},"reverendbizarre":{"title":"Reverend Bizarre","desc":"Finnish doom metal band","text":"Reverend Bizarre was a doom metal band from Finland. Formed in 1995, they played slow and heavy traditional doom with dramatic vocals, following in the footsteps of bands such as Witchfinder General, Saint Vitus, Candlemass, Pentagram and Black Sabbath. The band was one of the biggest names in 2000s traditional doom metal.","url":"https://en.wikipedia.org/wiki/Reverend_Bizarre"},"esoteric":{"title":"Esoteric (band)","desc":"British doom metal band","text":"Esoteric is an English funeral doom metal band from Birmingham, founded in 1992. Releasing seven studio albums, and a demo, the band is widely regarded as among the first groups to develop the funeral doom style. The band has named a variety of groups as influences, such as metal bands Morbid Angel and My Dying Bride, more \"trippy\" artists such as Pink Floyd, Spacemen 3, and King Crimson, and the industrial and dark ambient genres.","url":"https://en.wikipedia.org/wiki/Esoteric_(band)"},"anathema":{"title":"Anathema (band)","desc":"British rock band (1990–2020)","text":"Anathema were an English rock band from Liverpool, formed in 1990 by Vincent and Daniel Cavanagh, bassist Jamie Cavanagh, drummer/keyboardist John Douglas, and vocalist Darren \"Daz\" White.","url":"https://en.wikipedia.org/wiki/Anathema_(band)"},"katatonia":{"title":"Katatonia","desc":"Swedish heavy metal band","text":"Katatonia is a Swedish heavy metal band formed in Stockholm in 1991 by Jonas Renkse and Anders Nyström. The band started as a studio-only outlet for their love of death metal. Increasing popularity led to more band members for live performances, though outside of the band's founders, the lineup was a constantly changing musicians throughout the 1990s, including Mikael Åkerfeldt of Opeth for a period.","url":"https://en.wikipedia.org/wiki/Katatonia"},"skepticism":{"title":"Skepticism (band)","desc":"Finnish funeral doom band","text":"Skepticism is a Finnish funeral doom metal band. Formed in 1991, they are regarded as one of the pioneers of the genre.","url":"https://en.wikipedia.org/wiki/Skepticism_(band)"},"crowbar":{"title":"Crowbar (American band)","desc":"American sludge metal band","text":"Crowbar is an American sludge metal band formed in New Orleans, Louisiana in 1990. The band is fronted by vocalist/guitarist Kirk Windstein, Crowbar's sole constant member.","url":"https://en.wikipedia.org/wiki/Crowbar_(American_band)"},"acidbath":{"title":"Acid Bath","desc":"American sludge metal band","text":"Acid Bath is an American sludge metal band from Houma, Louisiana, that was active from 1991 to 1997. Regarded as one of the first and most influential sludge metal bands, they combined a doom metal foundation with elements of hardcore punk, death metal, gothic rock, blues, grunge, and Southern rock to create their sound.","url":"https://en.wikipedia.org/wiki/Acid_Bath"},"torche":{"title":"Torche (band)","desc":"American stoner metal band","text":"Torche is an American stoner metal/sludge metal band from Miami, Florida. The group formed in 2004 and has released five studio albums, four EPs, two split albums, and three singles. They released their fifth and final studio album, Admission, in 2019.","url":"https://en.wikipedia.org/wiki/Torche_(band)"},"clutch":{"title":"Clutch (band)","desc":"American rock band","text":"Clutch is an American rock band from Germantown, Maryland. Since its formation in 1991, the band lineup has included Tim Sult, Dan Maines (bass), Jean-Paul Gaster (drums), and Neil Fallon. To date, Clutch has released thirteen studio albums, and several rarities and live albums. Since 2008, the band has been signed to their own record label, Weathermaker Music. Clutch is one of the pioneers of stoner rock.","url":"https://en.wikipedia.org/wiki/Clutch_(band)"},"orangegoblin":{"title":"Orange Goblin","desc":"English heavy metal band","text":"Orange Goblin were an English stoner metal band from London. Formed in 1995, the band's most recent lineup consisted of singer Ben Ward, guitarist Joe Hoare, drummer Chris Turner, and bassist Harry Armstrong. Their final album Science, Not Fiction was released in July 2024.","url":"https://en.wikipedia.org/wiki/Orange_Goblin"},"fumanchu":{"title":"Fu Manchu (band)","desc":"American stoner rock band","text":"Fu Manchu is an American stoner rock band from Orange County, California. The band grew out of the hardcore punk band Virulence, which was founded in 1985, and adopted the name Fu Manchu in 1990. The band underwent multiple lineup changes throughout the 80s and 90s, but has remained consistent since 2001. The band currently consists of founding-guitarist-turned-lead-vocalist Scott Hill, bassist Brad Davis, lead guitarist Bob Balch and drummer Scott Reeder.","url":"https://en.wikipedia.org/wiki/Fu_Manchu_(band)"},"elder":{"title":"Elder (band)","desc":"American rock band","text":"Elder is an American rock band from Massachusetts, consisting of frontman and lead guitarist Nick DiSalvo, bassist Jack Donovan, guitarist/keyboardist Michael Risberg and drummer Georg Edert. They have released seven full-length albums since 2006, as well as multiple demos and EPs. Elder is now based in Berlin, Germany.","url":"https://en.wikipedia.org/wiki/Elder_(band)"},"uncleacid":{"title":"Uncle Acid & the Deadbeats","desc":"English rock band","text":"Uncle Acid & the Deadbeats are an English psychedelic rock and doom metal band formed in Cambridge by Kevin Starrs in 2009. The band has released six studio albums and one live album. Their most recent studio album Nell' Ora Blu, was released in May 2024 – as well as a number of singles. The band appears regularly at festivals around Europe.","url":"https://en.wikipedia.org/wiki/Uncle_Acid_%26_the_Deadbeats"},"earth":{"title":"Earth (American band)","desc":"American musical group","text":"Earth is an American rock band originally based in Olympia, Washington, and led by the guitarist Dylan Carlson. Initially active between 1989 and 1997, their early work is characterized by heavily distorted guitar, drones, and lengthy, minimalist song structures; their 1993 debut album Earth 2 is recognized as a pioneering work of the drone metal genre. The band resurfaced in the early 2000s, with their subsequent output reducing the distortion and incorporating elements of country, jazz rock, and folk.","url":"https://en.wikipedia.org/wiki/Earth_(American_band)"},"moonspell":{"title":"Moonspell","desc":"Portuguese gothic metal band","text":"Moonspell is a Portuguese gothic metal band formed in 1989. The group released their first EP, Under the Moonspell, in 1994, and followed up with their debut album, Wolfheart, a year later. They became the most recognizable Portuguese metal band and a key figure in gothic metal.","url":"https://en.wikipedia.org/wiki/Moonspell"},"tiamat":{"title":"Tiamat (band)","desc":"Swedish gothic metal band","text":"Tiamat is a Swedish metal band founded near Stockholm in 1990 and led by Johan Edlund. To date they have released ten studio albums. The band went through a number of stylistic changes in their earlier releases before settling on gothic metal. Under Edlund's leadership, the band would modify their style with influences ranging from Black Sabbath, Mercyful Fate, Candlemass, Pink Floyd and King Crimson combined with Sumerian lyrical themes.","url":"https://en.wikipedia.org/wiki/Tiamat_(band)"},"theatreoftragedy":{"title":"Theatre of Tragedy","desc":"Norwegian band","text":"Theatre of Tragedy was a Norwegian band from Stavanger, active between 1993 and 2010. They are best known for their earlier albums, which influenced the gothic metal genre.","url":"https://en.wikipedia.org/wiki/Theatre_of_Tragedy"},"lacuna":{"title":"Lacuna Coil","desc":"Italian heavy metal band","text":"Lacuna Coil is an Italian heavy metal band from Milan. They previously used the band names Sleep of Right and Ethereal. They have recorded ten studio albums, two extended plays, two live albums, two compilation albums, one video album, and sixteen singles and music videos.","url":"https://en.wikipedia.org/wiki/Lacuna_Coil"},"tristania":{"title":"Tristania (band)","desc":"Norwegian gothic metal band","text":"Tristania was a Norwegian gothic metal band formed in 1996 by Morten Veland, Einar Moen and Kenneth Olsson. Tristania's music is usually classified as gothic metal. Their songs largely dealt with dark and sentimental topics, including depression, sadness, suicide, love, absence, and anger.","url":"https://en.wikipedia.org/wiki/Tristania_(band)"},"gathering":{"title":"The Gathering (band)","desc":"Dutch rock band","text":"The Gathering are a Dutch rock band formed in Oss, North Brabant in 1989. The band's lineup currently consists of founding brothers René Rutten (guitars) and Hans Rutten (drums), Hugo Prinsen Geerligs (bass) and Frank Boeijen (keyboards), with former lead vocalist Anneke van Giersbergen currently a touring member.","url":"https://en.wikipedia.org/wiki/The_Gathering_(band)"},"amorphis":{"title":"Amorphis","desc":"Finnish progressive metal band","text":"Amorphis is a Finnish progressive metal band founded by Jan Rechberger, Tomi Koivusaari, and Esa Holopainen in 1990. Initially, the band was a death metal act, but on later albums they evolved into playing other genres, including progressive metal, folk metal, and melodic death metal. They frequently use the Kalevala, the epic poem of Finland, as a source for their lyrics.","url":"https://en.wikipedia.org/wiki/Amorphis"},"epica":{"title":"Epica (band)","desc":"Dutch symphonic metal band","text":"Epica is a Dutch symphonic metal band founded by guitarist and vocalist Mark Jansen after his departure from After Forever. Originally formed as a symphonic metal band with gothic influences, Epica later incorporated strong death metal elements into their sound. Starting with their third album, progressive metal influences also became evident. Additionally, the band often incorporates thrash metal and groove metal riffs, black metal elements, power metal sections, and influences from Arabic music.","url":"https://en.wikipedia.org/wiki/Epica_(band)"},"afterforever":{"title":"After Forever","desc":"Dutch metal band","text":"After Forever was a Dutch symphonic metal band with strong progressive metal influences. Originally formed as a death metal band in 1995 by Mark Jansen and Sander Gommans under the name Apocalypse, they later shifted their sound towards symphonic metal with the introduction of Floor Jansen to the band.","url":"https://en.wikipedia.org/wiki/After_Forever"},"delain":{"title":"Delain","desc":"Dutch symphonic metal band","text":"Delain is a Dutch symphonic metal band formed in 2002 by keyboardist Martijn Westerholt. After his departure from Within Temptation in 2001, Westerholt formed Delain the following year, intending for the band to be solely a project, but stopped after the release of one demo. In 2005, Westerholt restarted Delain alongside singer Charlotte Wessels, and released the debut studio album, Lucidity, in September 2006.","url":"https://en.wikipedia.org/wiki/Delain"},"therion":{"title":"Therion (band)","desc":"Swedish symphonic metal band","text":"Therion is a Swedish symphonic metal band founded by Christofer Johnsson in 1987. Its name, meaning \"Beast\" in Greek, was inspired by the Celtic Frost album To Mega Therion. Originally a death metal band, Therion adjusted its musical style by adding orchestral elements, including choirs, classical musicians, and even a full orchestra at their concert performances. As a result, they are considered pioneers of the symphonic metal genre.","url":"https://en.wikipedia.org/wiki/Therion_(band)"},"marillion":{"title":"Marillion","desc":"British progressive rock band","text":"Marillion are a British neo-prog band, formed in Aylesbury, Buckinghamshire, in 1979. They emerged from the post-punk music scene in Britain and existed as a bridge between the styles of punk rock and classic progressive rock, becoming the most commercially successful neo-prog band of the 1980s.","url":"https://en.wikipedia.org/wiki/Marillion"},"camel":{"title":"Camel (band)","desc":"English progressive rock band","text":"Camel are an English progressive rock band formed in Guildford, Surrey, in 1971. Originating from the blues-rock trio Brew, guitarist Andrew Latimer, drummer Andy Ward, and bassist Doug Ferguson initially worked as the backing band for singer-songwriter Phillip Goodhand-Tait before recruiting keyboardist Peter Bardens and establishing the group's progressive sound.","url":"https://en.wikipedia.org/wiki/Camel_(band)"},"gentlegiant":{"title":"Gentle Giant","desc":"British progressive rock band (1970–1980)","text":"Gentle Giant were a British progressive rock band active between 1970 and 1980. They were known for the complexity and sophistication of their music and for the varied musical skills of the members. All of the band members were multi-instrumentalists. Although not commercially successful, the band achieved a cult following.","url":"https://en.wikipedia.org/wiki/Gentle_Giant"},"vandergraaf":{"title":"Van der Graaf Generator","desc":"English rock band formed in 1967","text":"Van der Graaf Generator are an English progressive rock band, formed in 1967 in Manchester by singer-songwriters Peter Hammill and Chris Judge Smith. They were the first act signed by Charisma Records. They did not experience much commercial success in the UK, but became popular in Italy during the 1970s. In 2005 the band reformed, and are still musically active with a line-up of Hammill, organist Hugh Banton and drummer Guy Evans.","url":"https://en.wikipedia.org/wiki/Van_der_Graaf_Generator"},"caravan":{"title":"Caravan (band)","desc":"English band from the Canterbury area","text":"Caravan are an English rock band from the Canterbury area, founded by former Wilde Flowers members David Sinclair, Richard Sinclair, Pye Hastings, and Richard Coughlan in 1968. The band have never achieved the great commercial success that was widely predicted for them at the beginning of their career, but are nevertheless considered a key part of the Canterbury scene of progressive rock acts, blending psychedelic rock, jazz, and classical influences to create a distinctive sound.","url":"https://en.wikipedia.org/wiki/Caravan_(band)"},"magma":{"title":"Magma (band)","desc":"French progressive rock band","text":"Magma is a French progressive rock band founded in Paris in 1969 by self-taught drummer Christian Vander, who claimed as his inspiration a \"vision of humanity's spiritual and ecological future\" that profoundly disturbed him. The style of progressive rock that Vander developed with Magma is termed \"Zeuhl\" and has been applied to other bands in France operating in the same period, and to some recent Japanese bands.","url":"https://en.wikipedia.org/wiki/Magma_(band)"},"focus":{"title":"Focus (band)","desc":"Dutch rock band","text":"Focus is a Dutch progressive rock band formed in Amsterdam in 1969 by keyboardist, vocalist, and flautist Thijs van Leer, drummer Hans Cleuver, bassist Martijn Dresden, and guitarist Jan Akkerman. The band has undergone numerous formations in its history; since December 2016, it has comprised Van Leer, drummer Pierre van der Linden, guitarist Menno Gootjes, and bassist Udo Pannekeet.","url":"https://en.wikipedia.org/wiki/Focus_(band)"},"nevermore":{"title":"Nevermore","desc":"American heavy metal band","text":"Nevermore is an American heavy metal band formed in Seattle, Washington, in 1992. The band emerged following the dissolution of Sanctuary, whose final line-up included vocalist Warrel Dane, bassist Jim Sheppard and guitarist Jeff Loomis. The three musicians formed Nevermore with drummer Mark Arrington, who was replaced by Van Williams in 1994. Nevermore's music incorporates elements of progressive metal, thrash metal and power metal.","url":"https://en.wikipedia.org/wiki/Nevermore"},"symphonyx":{"title":"Symphony X","desc":"American metal band","text":"Symphony X is an American progressive metal band from Middletown, New Jersey. Founded in 1994, the band consists of guitarist Michael Romeo, keyboardist Michael Pinnella, drummer Jason Rullo, lead vocalist Russell Allen and bassist Michael LePond.","url":"https://en.wikipedia.org/wiki/Symphony_X"},"painofsalvation":{"title":"Pain of Salvation","desc":"Swedish progressive metal band","text":"Pain of Salvation is a Swedish progressive metal band led by Daniel Gildenlöw, who is the band's main songwriter, lyricist, guitarist, and vocalist. Pain of Salvation's sound is characterised by riff-oriented guitar work, a broad vocal range, oscillation between heavy and calm passages, complex vocal harmonies and the structures of their albums, syncopation, and polyrhythms. Thus far, every album released by the band has been a concept album.","url":"https://en.wikipedia.org/wiki/Pain_of_Salvation"},"evergrey":{"title":"Evergrey","desc":"Swedish progressive metal band","text":"Evergrey is a Swedish progressive metal band from Gothenburg, formed in 1993 by guitarist and vocalist Tom S. Englund and guitarist Dan Bronell. The band is known for combining progressive metal and power metal with dark lyrical themes and imagery.","url":"https://en.wikipedia.org/wiki/Evergrey"},"karnivool":{"title":"Karnivool","desc":"Australian rock band","text":"Karnivool is an Australian rock band formed in Perth in 1998. Since 2004, the group has consisted of Ian Kenny on vocals, Drew Goddard and Mark Hosking on guitar, Jon Stockman on bass, and Steve Judd on drums. The band has released four studio albums to date: Themata (2005), Sound Awake (2009), Asymmetry (2013) and In Verses (2026).","url":"https://en.wikipedia.org/wiki/Karnivool"},"leprous":{"title":"Leprous","desc":"Norwegian progressive metal band","text":"Leprous is a Norwegian progressive metal band formed in 2001 by singer and keyboardist Einar Solberg and guitarist Tor Oddmund Suhrke. After releasing several demos with relatively unstable lineups, the band released their first studio album, Tall Poppy Syndrome, in 2009. They subsequently gained prominence as the live backing band of Ihsahn, who, in turn, contributed on several Leprous records as guest singer or producer.","url":"https://en.wikipedia.org/wiki/Leprous"},"haken":{"title":"Haken (band)","desc":"English progressive metal band","text":"Haken are an English progressive metal band formed in 2007 by multi-instrumentalist Richard Henshall, guitarist Matthew Marshall, and vocalist Ross Jennings. While Henshall, Marshall, and Jennings first had the idea of forming Haken in 2004, they opted to pursue their instruments and songwriting first. Upon recruiting other members three years later, they eventually released the demo Enter the 5th Dimension in 2008, signing with Sensory Records and releasing their first album, Aquarius, in 2010.","url":"https://en.wikipedia.org/wiki/Haken_(band)"},"textures":{"title":"Textures (band)","desc":"Dutch progressive metalcore band","text":"Textures are a Dutch progressive metalcore band, formed in 2001. Textures' lineup revolved around founding members Jochem Jacobs, Stef Broks, Bart Hennephof, and bassist Remko Tielemans who joined in 2007. Since 2010, vocalist Daniël de Jongh and keyboardist Uri Dijk have been with the band.","url":"https://en.wikipedia.org/wiki/Textures_(band)"},"kmfdm":{"title":"KMFDM","desc":"German industrial rock band","text":"KMFDM is a multinational industrial rock band from Hamburg led by Sascha Konietzko, who founded the band in 1984 as a performance art project.","url":"https://en.wikipedia.org/wiki/KMFDM"},"front242":{"title":"Front 242","desc":"Belgian electronic music group","text":"Front 242 were a Belgian electronic music group that came into prominence during the 1980s. Pioneering the style they called electronic body music, they influenced the electronic and industrial music genres.","url":"https://en.wikipedia.org/wiki/Front_242"},"skinnypuppy":{"title":"Skinny Puppy","desc":"Canadian industrial band","text":"Skinny Puppy was a Canadian electro-industrial band formed in Vancouver in 1982. The musical group was considered one of the founding groups of the industrial rock and electro-industrial musical genres.","url":"https://en.wikipedia.org/wiki/Skinny_Puppy"},"nitzerebb":{"title":"Nitzer Ebb","desc":"British EBM band","text":"Nitzer Ebb are an English EBM group formed in 1982 by Essex school friends Vaughan \"Bon\" Harris, Douglas McCarthy, and David Gooday (drums). The band was originally named La Comédie De La Mort but soon discarded that and chose the name Nitzer Ebb by cutting up words and letters and arranging them randomly to create something Germanic without using actual German words.","url":"https://en.wikipedia.org/wiki/Nitzer_Ebb"},"frontlineassembly":{"title":"Front Line Assembly","desc":"Canadian electro-industrial band","text":"Front Line Assembly (FLA) is a Canadian electro-industrial band formed by Bill Leeb in 1986 after leaving Skinny Puppy. FLA has developed its own sound incorporating elements of electronic body music and electro-industrial. The band's membership has rotated through the years, including Michael Balch, Rhys Fulber, and Chris Peterson, all of whom are associated with several other acts.","url":"https://en.wikipedia.org/wiki/Front_Line_Assembly"},"mudvayne":{"title":"Mudvayne","desc":"American metal band","text":"Mudvayne is an American heavy metal band formed in Peoria, Illinois, in 1996. Known for their sonic experimentation, face and body paint, masks and uniforms, the band has sold over five million records worldwide. The group consists of lead guitarist Greg Tribbett, drummer Matthew McDonough, lead vocalist Chad Gray, bassist Ryan Martinie and live rhythm guitarist Marcus Rafferty.","url":"https://en.wikipedia.org/wiki/Mudvayne"},"disturbed":{"title":"Disturbed","desc":"American heavy metal band","text":"Disturbed is an American heavy metal band from Chicago, Illinois and formed in 1994. The band includes guitarist Dan Donegan, drummer Mike Wengren, lead vocalist David Draiman, and bassist John Moyer. Donegan and Wengren have been involved in the band since its inception, with Draiman replacing original lead vocalist Erich Awalt in 1996 and Moyer replacing original bassist Steve \"Fuzz\" Kmak in 2004.","url":"https://en.wikipedia.org/wiki/Disturbed"},"godsmack":{"title":"Godsmack","desc":"American rock band","text":"Godsmack is an American rock band from Lawrence, Massachusetts, formed in 1995. The band is currently composed of lead singer and rhythm guitarist Sully Erna, bassist Robbie Merrill, and lead guitarist Sam Koltun. Since its formation, Godsmack has released nine studio albums, one EP, four DVDs, one compilation album, and two live albums. Their most recent album, Lighting Up the Sky, was released in 2023.","url":"https://en.wikipedia.org/wiki/Godsmack"},"paparoach":{"title":"Papa Roach","desc":"American rock band","text":"Papa Roach is an American rock band from Vacaville, California, formed in 1993. After a few early shifts, the band initially stabilized in 1996 with the lineup of lead vocalist Jacoby Shaddix, drummer Dave Buckner, guitarist Jerry Horton, and bassist Tobin Esperance. This lineup remained consistent for slightly over a decade.","url":"https://en.wikipedia.org/wiki/Papa_Roach"},"limpbizkit":{"title":"Limp Bizkit","desc":"American nu metal band","text":"Limp Bizkit is an American nu metal band from Jacksonville, Florida. Its lineup consists of lead vocalist Fred Durst, drummer John Otto, guitarist Wes Borland, and turntablist DJ Lethal. The band's musical style is marked by Durst's angry vocal delivery and Borland's sonic experimentation. The band is one of the most successful nu metal bands of all time. It has been nominated for three Grammy Awards, sold 40 million records worldwide, and won several other awards.","url":"https://en.wikipedia.org/wiki/Limp_Bizkit"},"coalchamber":{"title":"Coal Chamber","desc":"American nu metal band","text":"Coal Chamber is an American nu metal band formed by Dez Fafara and Meegs Rascón in Los Angeles in 1992, initially under the name She's in Pain. The original lineup also consisted of bassist Rayna Foss and drummer Jon Tor. Mike Cox replaced Tor on drums in 1995, and the Coal Chamber lineup was complete. After signing to Roadrunner Records, they released their debut album, Coal Chamber, in 1997.","url":"https://en.wikipedia.org/wiki/Coal_Chamber"},"sevendust":{"title":"Sevendust","desc":"American rock band","text":"Sevendust is an American rock band from Atlanta, Georgia, formed in 1994 by bassist Vinnie Hornsby, drummer Morgan Rose, and guitarist John Connolly. After their first demo, lead vocalist Lajon Witherspoon and guitarist Clint Lowery joined the group. Following a few name changes, the members settled on Sevendust and released their self-titled debut album in 1997, which sold only 311 copies in its first week but ultimately achieved gold certification.","url":"https://en.wikipedia.org/wiki/Sevendust"},"soulfly":{"title":"Soulfly","desc":"Brazilian-American heavy metal band","text":"Soulfly is a Brazilian-American heavy metal band formed in Phoenix, Arizona in 1997. Soulfly is led by former Sepultura frontman Max Cavalera, who formed the band after he left the Brazilian group in 1996. To date the band has released thirteen studio albums, one tour EP, twenty-three singles, one video album, and twelve music videos. Their debut album, Soulfly, was released on April 21, 1998, while their most recent album, Chama, was released in October 2025.","url":"https://en.wikipedia.org/wiki/Soulfly"},"pod":{"title":"P.O.D.","desc":"American nu metal band","text":"D. is an American Christian nu metal band formed in 1992 and based in San Diego, California. The band's line-up consists of vocalist Paul Joshua \"Sonny\" Sandoval, bassist Mark \"Traa\" Daniels, guitarist Marcos Curiel, and drummer Zachary Christopherr. They have sold over 12 million records worldwide.","url":"https://en.wikipedia.org/wiki/P.O.D."},"baddreligion":{"title":"Bad Religion","desc":"American punk rock band","text":"Bad Religion is an American punk rock band, formed in Los Angeles, California, in 1980. The band's lyrics cover topics related to religion, politics, society, the media and science. Musically, they are noted for their melodic sensibilities and extensive use of three-part vocal harmonies.","url":"https://en.wikipedia.org/wiki/Bad_Religion"},"nofx":{"title":"NOFX","desc":"American punk rock band","text":"NOFX was an American punk rock band, formed in Los Angeles in 1983. Bassist/lead vocalist Fat Mike, rhythm guitarist Eric Melvin and drummer Erik Sandin were original founding and longest-serving members of the band, who have appeared on every release by the band, although Sandin had departed briefly in 1985, only to rejoin the following year. El Hefe joined the band in 1991 to play lead guitar and trumpet, rounding out the best-known iteration of the lineup.","url":"https://en.wikipedia.org/wiki/NOFX"},"rancid":{"title":"Rancid (band)","desc":"American punk rock band","text":"Rancid is an American punk rock band formed in Berkeley, California, in 1991. Founded by Tim Armstrong and Matt Freeman, former members of the band Operation Ivy, Rancid is often credited as being among the wave of bands that revived mainstream interest in punk rock in the United States during the mid-1990s. Over its 35-year career, Rancid has retained much of its original fan base, most of which was connected to its underground musical roots.","url":"https://en.wikipedia.org/wiki/Rancid_(band)"},"socialdistortion":{"title":"Social Distortion","desc":"American punk rock band","text":"Social Distortion is an American punk rock band formed in 1978 in Fullerton, California. It consists of Mike Ness, Jonny Wickersham (guitar), Brent Harding (bass), and David Hidalgo Jr. (drums).","url":"https://en.wikipedia.org/wiki/Social_Distortion"},"thedamned":{"title":"The Damned (band)","desc":"English rock band","text":"The Damned are an English rock band formed in London in 1976 by lead vocalist Dave Vanian, guitarist Brian James, bassist Captain Sensible and drummer Rat Scabies. They were the first punk band from the United Kingdom to release a single, \"New Rose\" (1976), release a studio album, Damned Damned Damned (1977) and tour the United States. The band briefly dissolved after their second album, Music for Pleasure (1977), was critically dismissed.","url":"https://en.wikipedia.org/wiki/The_Damned_(band)"},"buzzcocks":{"title":"Buzzcocks","desc":"British punk rock band","text":"Buzzcocks are an English punk rock band formed by singer-songwriter and guitarist Pete Shelley and singer-songwriter Howard Devoto in Bolton in 1976. They achieved commercial success with singles that fuse pop with rapid-fire punk energy, inspiring the power pop and pop punk movements; these singles were later collected on Singles Going Steady, an acclaimed compilation album music journalist and critic Ned Raggett described as a \"punk masterpiece\".","url":"https://en.wikipedia.org/wiki/Buzzcocks"},"stifflittlefingers":{"title":"Stiff Little Fingers","desc":"Northern Irish punk rock band","text":"Stiff Little Fingers is a Northern Irish punk rock band from Belfast. They formed in 1977 at the height of the Troubles, which informed much of their songwriting. They started out as a schoolboy band called Highway Star, doing rock covers, until they discovered punk. They were the first punk band in Belfast to release a record – the \"Suspect Device\" single came out on their own independent label, Rigid Digits.","url":"https://en.wikipedia.org/wiki/Stiff_Little_Fingers"},"deadboys":{"title":"Dead Boys","desc":"American punk rock band","text":"The Dead Boys were an American punk rock band from Cleveland, Ohio. The band was among the first wave of punk, and regarded by many as one of the rowdiest and most violent groups of the era. They were formed in 1975 by vocalist Stiv Bators, rhythm guitarist Jimmy Zero, bassist Jeff Magnum, lead guitarist Cheetah Chrome, and drummer Johnny Blitz—the latter two having splintered from the band Rocket from the Tombs.","url":"https://en.wikipedia.org/wiki/Dead_Boys"},"germs":{"title":"Germs (band)","desc":"American punk rock band","text":"The Germs were an American punk rock band from Los Angeles, California, originally active from 1976 to 1980. The band's \"classic\" lineup consisted of singer Darby Crash, guitarist Pat Smear, bassist Lorna Doom and drummer Don Bolles. They released only one album, 1979's (GI), produced by Joan Jett, and were featured in Penelope Spheeris's seminal documentary film The Decline of Western Civilization, which chronicled the Los Angeles punk movement.","url":"https://en.wikipedia.org/wiki/Germs_(band)"},"xband":{"title":"X (American band)","desc":"American punk rock band","text":"X is an American punk rock band formed in Los Angeles. The original members were vocalist Exene Cervenka, vocalist-bassist John Doe, guitarist Billy Zoom and drummer D. J. Bonebrake. The band released seven studio albums from 1980 to 1993. After a period of inactivity during the mid-to-late 1990s, X reunited in the early 2000s and continued to tour.","url":"https://en.wikipedia.org/wiki/X_(American_band)"},"circlejerks":{"title":"Circle Jerks","desc":"American punk band","text":"The Circle Jerks are an American hardcore punk band, formed in 1979 in Los Angeles, California. The group was founded by former Black Flag vocalist Keith Morris and Redd Kross guitarist Greg Hetson. To date, the Circle Jerks have released six studio albums, one compilation, a live album and a live DVD. Their debut album, Group Sex (1980), is considered a landmark of the hardcore genre.","url":"https://en.wikipedia.org/wiki/Circle_Jerks"},"descendents":{"title":"Descendents","desc":"American punk rock band","text":"The Descendents are an American punk rock band formed in Manhattan Beach, California, in 1977, by guitarist Frank Navetta, bassist Tony Lombardo and drummer Bill Stevenson as a power pop/surf punk band. In 1979, they enlisted Stevenson's school friend Milo Aukerman as a singer, and reappeared as a melodic hardcore punk band, becoming a major player in the hardcore scene developing in Los Angeles at the time.","url":"https://en.wikipedia.org/wiki/Descendents"},"agnosticfront":{"title":"Agnostic Front","desc":"American hardcore punk band","text":"Agnostic Front is an American hardcore punk band from New York City. Founded in 1980, the band is considered an important influence on the New York hardcore scene, as well as a pioneer of the crossover thrash genre.","url":"https://en.wikipedia.org/wiki/Agnostic_Front"},"sickofitall":{"title":"Sick of It All","desc":"American hardcore punk band","text":"Sick of It All is an American hardcore punk band formed in 1986 in Queens, New York City by brothers Pete and Lou Koller. Their classic lineup, which had lasted for 33 years, included the Koller brothers, drummer Armand Majidi and bassist Craig Setari. As of Lou's death in 2026, Pete remains as the only consistent member of Sick of It All, although Majidi is one of the three members to appear on every studio album.","url":"https://en.wikipedia.org/wiki/Sick_of_It_All"},"youthoftoday":{"title":"Youth of Today","desc":"American hardcore punk band","text":"Youth of Today is an American hardcore punk band, initially active from 1985 to 1990 before reforming in 2010. The band played a major role in establishing the \"Youth Crew\" subculture of hardcore, both espousing and evolving the philosophies of the straight edge and vegetarian lifestyles.","url":"https://en.wikipedia.org/wiki/Youth_of_Today"},"gorillabiscuits":{"title":"Gorilla Biscuits","desc":"American hardcore punk band","text":"Gorilla Biscuits are an American hardcore punk band from New York City, formed in 1986. Signed to Revelation Records since 1988, Gorilla Biscuits are typically seen as one of the most prominent acts of the New York hardcore scene. The band's lineup currently consists of Anthony \"Civ\" Civorelli, Walter Schreifels, Arthur Smilios, and Luke Abbey.","url":"https://en.wikipedia.org/wiki/Gorilla_Biscuits"},"theexploited":{"title":"The Exploited","desc":"Scottish punk rock band","text":"The Exploited are a Scottish punk rock band formed in Edinburgh in 1978 by Stevie Ross and Terry Buchan, with Buchan soon replaced with his brother, Wattie Buchan. They signed to Secret Records in March 1981, and their debut EP, Army Life, and debut album, Punks Not Dead, were released that year. The band maintained a cult following in the 1980s among hardcore working class punks and skinheads.","url":"https://en.wikipedia.org/wiki/The_Exploited"},"jimmyeatworld":{"title":"Jimmy Eat World","desc":"American rock band","text":"Jimmy Eat World is an American rock band formed in Mesa, Arizona, in 1993. The band is composed of vocalist and lead guitarist Jim Adkins, rhythm guitarist and vocalist Tom Linton, bassist Rick Burch, and drummer Zach Lind. They have released ten studio albums, all but the first featuring the current line-up.","url":"https://en.wikipedia.org/wiki/Jimmy_Eat_World"},"hotwatermusic":{"title":"Hot Water Music","desc":"American post-hardcore band","text":"Hot Water Music is an American punk rock band formed in October 1994 and based in Gainesville, Florida. Since their formation, the group has consisted of Chuck Ragan and Chris Wollard on shared lead vocals and guitars, bass guitarist Jason Black, and drummer George Rebelo. Since 2017, the band has also included guitarist-vocalist Chris Cresswell. The band initially broke up in August 1998, but reformed by October 1998.","url":"https://en.wikipedia.org/wiki/Hot_Water_Music"},"thursday":{"title":"Thursday (band)","desc":"American rock band","text":"Thursday is an American rock band formed in New Brunswick, New Jersey, in 1998. The band consists of Geoff Rickly, Tom Keeley, Steve Pedulla, Tim Payne (bass), and Tucker Rule (drums).","url":"https://en.wikipedia.org/wiki/Thursday_(band)"},"takingbacksunday":{"title":"Taking Back Sunday","desc":"American rock band","text":"Taking Back Sunday is an American rock band from Amityville, New York, formed by guitarist Eddie Reyes and bassist Jesse Lacey in late 1999 before rounding out the band with vocalist Antonio Longo, lead guitarist John Nolan, and drummer Steven DeJoseph. The band's current members are Adam Lazzara, John Nolan and Shaun Cooper, accompanied by Nathan Cogan (guitar), Mitchell Register (drums), and former member Fred Mascherino for their live performances.","url":"https://en.wikipedia.org/wiki/Taking_Back_Sunday"},"afi":{"title":"AFI (band)","desc":"American rock band","text":"AFI is an American rock band from Ukiah, California, that was formed in 1991. It has comprised lead vocalist Davey Havok, drummer Adam Carson, bassist-keyboardist Hunter Burgan, and guitarist-keyboardist Jade Puget since 1998. Havok and Carson are the sole remaining original members, with founding guitarist Mark Stopholese having left in 1998. They began as a hardcore punk band in the 1990s but have since explored a myriad of genres.","url":"https://en.wikipedia.org/wiki/AFI_(band)"},"falloutboy":{"title":"Fall Out Boy","desc":"American rock band","text":"Fall Out Boy is an American rock band formed in Wilmette, Illinois, a suburb of Chicago, in 2001. The band consists of lead vocalist and guitarist Patrick Stump, bassist Pete Wentz, guitarist Joe Trohman, and drummer Andy Hurley. The band originated from Chicago's hardcore punk scene and was formed by Wentz and Trohman as a pop-punk side project; Stump joined shortly thereafter.","url":"https://en.wikipedia.org/wiki/Fall_Out_Boy"},"paramore":{"title":"Paramore","desc":"American rock band","text":"Paramore is an American rock band formed in Franklin, Tennessee, in 2004. Since 2017, the band's lineup has included lead vocalist Hayley Williams, guitarist Taylor York, and drummer Zac Farro. Williams and Farro are the founding members of the group, while York, a high school friend of the original lineup, joined in 2007.","url":"https://en.wikipedia.org/wiki/Paramore"},"panic":{"title":"Panic! at the Disco","desc":"American pop rock band","text":"Panic! at the Disco was an American pop rock band formed in Las Vegas, Nevada, in 2004 by high school friends Ryan Ross and Spencer Smith (drums), who recruited classmates Brendon Urie and Brent Wilson (bass). Following several lineup changes, Panic! at the Disco operated as the solo project of frontman Urie from 2015 until its discontinuation in 2023.","url":"https://en.wikipedia.org/wiki/Panic!_at_the_Disco"},"alkalinetrio":{"title":"Alkaline Trio","desc":"American punk rock band","text":"Alkaline Trio is an American punk rock band formed in Chicago, in 1996. The band consists of Matt Skiba, Dan Andriano and Tosh Peterson (drums).","url":"https://en.wikipedia.org/wiki/Alkaline_Trio"},"echobunnymen":{"title":"Echo & the Bunnymen","desc":"English rock band","text":"Echo & the Bunnymen are an English rock band formed in Liverpool in 1978. The original line-up consisted of vocalist Ian McCulloch, guitarist Will Sergeant and bassist Les Pattinson. In 1979, Pete de Freitas joined as the band's drummer.","url":"https://en.wikipedia.org/wiki/Echo_%26_the_Bunnymen"},"killingjoke":{"title":"Killing Joke","desc":"English post-punk band","text":"Killing Joke are an English post-punk band formed in Notting Hill, London, in 1979 by Jaz Coleman, Paul Ferguson (drums), Geordie Walker (guitar) and Youth (bass).","url":"https://en.wikipedia.org/wiki/Killing_Joke"},"thefall":{"title":"The Fall (band)","desc":"English rock band (1976–2018)","text":"The Fall were an English post-punk band, formed in 1976 in Prestwich, Greater Manchester. They had many line-up changes, with vocalist and founder member Mark E. Smith being the only constant member. Their music was generally characterised by Smith's caustic lyrics and sprechgesang vocal delivery, an abrasive, repetitive guitar-driven sound, and tense bass and drum rhythms.","url":"https://en.wikipedia.org/wiki/The_Fall_(band)"},"magazine":{"title":"Magazine (band)","desc":"British post-punk band","text":"Magazine were a British rock band formed in 1977 in Manchester, England by singer Howard Devoto and guitarist John McGeoch. After leaving the punk rock group Buzzcocks in early 1977, Devoto decided to create a more progressive rock band. The original line-up of Magazine was composed of Devoto, McGeoch, Barry Adamson on bass, Bob Dickinson on keyboards and Martin Jackson on drums.","url":"https://en.wikipedia.org/wiki/Magazine_(band)"},"pereubu":{"title":"Pere Ubu","desc":"American rock band","text":"Pere Ubu was an American rock band formed in Cleveland, Ohio, in 1975. The band had a variety of lineup changes, with frontman and leader David Thomas the sole constant member. In December 1975, they released their debut single \"30 Seconds Over Tokyo\"; their debut album The Modern Dance followed in 1978. They disbanded in 1982, but reformed in 1987 and remained active until Thomas' death on April 23, 2025.","url":"https://en.wikipedia.org/wiki/Pere_Ubu"},"slits":{"title":"The Slits","desc":"British punk rock band","text":"The Slits were an early punk and then post-punk band based in London, formed there in 1976 by members of the groups the Flowers of Romance and the Castrators. The group's early line-up consisted of Ari Up and Palmolive, with Viv Albertine and Tessa Pollitt replacing founding members Kate Korus and Suzy Gutsy. Their 1979 debut album, Cut, has been called one of the defining releases of the post-punk era.","url":"https://en.wikipedia.org/wiki/The_Slits"},"suicide":{"title":"Suicide (band)","desc":"American musical duo (1970–2016)","text":"Suicide was an American musical duo composed of vocalist Alan Vega and instrumentalist Martin Rev, intermittently active between 1970 and 2016. The group's pioneering music fused stream-of-conscious, rockabilly-inspired vocals with minimalist electronic instrumentation, including synthesizers and primitive drum machines, and their early performances were confrontational and often ended in violence.","url":"https://en.wikipedia.org/wiki/Suicide_(band)"},"deadcandance":{"title":"Dead Can Dance","desc":"Anglo-Irish - Australian music duo","text":"Dead Can Dance are a British-Australian neoclassical darkwave band founded in Melbourne in 1981 by Brendan Perry and Lisa Gerrard before the pair relocated to London the following year. They signed with independent label 4AD and were initially associated with the United Kingdom's gothic scene before developing a style that incorporated European medieval and Renaissance music traditions alongside ambient pop, darkwave, and world music elements.","url":"https://en.wikipedia.org/wiki/Dead_Can_Dance"},"fieldsnephilim":{"title":"Fields of the Nephilim","desc":"British gothic rock band","text":"Fields of the Nephilim are an English gothic rock band formed in Stevenage, Hertfordshire, in 1984. The band's name refers to a biblical race of angel-human hybrids known as the Nephilim and the magnetic fields around the Earth.","url":"https://en.wikipedia.org/wiki/Fields_of_the_Nephilim"},"themission":{"title":"The Mission (band)","desc":"English gothic rock band","text":"The Mission are an English gothic rock band formed in 1986. Initially known as the Sisterhood, the band was started by frontman Wayne Hussey and bassist Craig Adams, soon adding drummer Mick Brown and guitarist Simon Hinkler. Aside from Hussey, the lineup has changed several times over the years, and the band has been on hiatus twice.","url":"https://en.wikipedia.org/wiki/The_Mission_(band)"},"xtc":{"title":"XTC","desc":"English rock band (1972–2006)","text":"XTC were an English rock band formed in Swindon in 1972. Fronted by songwriters Andy Partridge and Colin Moulding, the band gained popularity during the rise of punk and new wave in the 1970s, later playing in a variety of styles that ranged from angular guitar riffs to elaborately arranged pop. Partly because the group did not fit into contemporary trends, they achieved only sporadic commercial success in the UK and US, but attracted a considerable cult following.","url":"https://en.wikipedia.org/wiki/XTC"},"costello":{"title":"Elvis Costello","desc":"English singer-songwriter (born 1954)","text":"Declan Patrick MacManus, known professionally as Elvis Costello, is an English singer, songwriter, record producer, author, and television host. According to Rolling Stone, Costello \"reinvigorated the literate, lyrical traditions of Bob Dylan and Van Morrison with the raw energy and sass that were principal ethics of punk\", noting the \"construction of his songs, which set densely layered wordplay in an ever-expanding repertoire of styles\".","url":"https://en.wikipedia.org/wiki/Elvis_Costello"},"police":{"title":"The Police","desc":"English rock band","text":"The Police were an English rock band formed in London in 1977. Their core line-up comprised Sting, Andy Summers (guitar) and Stewart Copeland. The Police became globally popular from the late 1970s to the mid-1980s. The band emerged in the British punk scene, but soon expanded into other styles such as new wave, reggae rock, and post-punk.","url":"https://en.wikipedia.org/wiki/The_Police"},"stranglers":{"title":"The Stranglers","desc":"English rock band","text":"The Stranglers are an English rock band formed in Guildford, Surrey in 1974. The group's classic line-up, active from 1975 to 1990, consisted of guitarist and vocalist Hugh Cornwell, bassist and vocalist Jean-Jacques Burnel, keyboardist Dave Greenfield, and drummer Jet Black. Scoring 23 UK top 40 singles and 20 UK top 40 albums to date in a career spanning over five decades, the Stranglers are amongst the longest-surviving bands to have originated in the British punk scene.","url":"https://en.wikipedia.org/wiki/The_Stranglers"},"u2":{"title":"U2","desc":"Irish rock band","text":"U2 are an Irish rock band formed in Dublin in 1976. They comprise Bono, the Edge, Adam Clayton, and Larry Mullen Jr.. Initially rooted in post-punk, U2's musical style has evolved throughout their career, yet has maintained an anthemic quality built on Bono's expressive vocals and the Edge's chiming, effects-based guitar sounds. Bono's lyrics, often embellished with spiritual imagery, focus on personal and sociopolitical themes.","url":"https://en.wikipedia.org/wiki/U2"},"devo":{"title":"Devo","desc":"American new wave band","text":"Devo is an American new wave band from Akron, Ohio, formed in 1973. Their classic line-up consisted of two sets of brothers, the Mothersbaughs and the Casales, along with drummer Alan Myers. While the band is best known for their 1980 single \"Whip It,\" their only top 40 hit on the Billboard Hot 100, they continue to have a loyal following.","url":"https://en.wikipedia.org/wiki/Devo"},"greenriver":{"title":"Green River (band)","desc":"American rock band","text":"Green River was an American rock band formed in Seattle, Washington, in 1984. Considered one of the first grunge bands, Green River is best known for being the precursor to multiple key early 1990s rock bands, most notably Pearl Jam, Mudhoney, Mother Love Bone, Temple of the Dog, and Love Battery. Green River reunited for several live shows in 2008 and 2009.","url":"https://en.wikipedia.org/wiki/Green_River_(band)"},"motherlovebone":{"title":"Mother Love Bone","desc":"American rock band","text":"Mother Love Bone was an American rock band that formed in Seattle, Washington, in 1987. The band was active up until 1990. Frontman Andrew Wood's charisma and songwriting helped to catapult the group to the top of the burgeoning Seattle music scene at the time. Mother Love Bone ultimately became the first of the grunge-adjacent bands to sign with a major label (PolyGram). Their debut EP, Shine, was released in late 1989.","url":"https://en.wikipedia.org/wiki/Mother_Love_Bone"},"templeofthedog":{"title":"Temple of the Dog","desc":"American rock band","text":"Temple of the Dog was an American rock supergroup that formed in Seattle, Washington, in 1990. It was conceived by vocalist Chris Cornell of Soundgarden as a tribute to his friend, the late Andrew Wood, lead singer of the bands Malfunkshun and Mother Love Bone. The lineup included Stone Gossard on rhythm guitar, Jeff Ament on bass guitar, Mike McCready on lead guitar, and Matt Cameron on drums.","url":"https://en.wikipedia.org/wiki/Temple_of_the_Dog"},"screamingtrees":{"title":"Screaming Trees","desc":"American rock band (1984–2000)","text":"Screaming Trees were an American rock band formed in Ellensburg, Washington, in 1984 by vocalist Mark Lanegan, guitarist Gary Lee Conner, bassist Van Conner, and drummer Mark Pickerel. Pickerel was replaced by Barrett Martin in 1991. Screaming Trees became known as one of the pioneers of grunge. Although widely associated with grunge, the band's sound incorporated hard rock and psychedelic elements.","url":"https://en.wikipedia.org/wiki/Screaming_Trees"},"madseason":{"title":"Mad Season (band)","desc":"American rock supergroup","text":"Mad Season was an American rock supergroup formed in 1994 as a side project of members of other bands in the Seattle grunge scene. The band's principal members included guitarist Mike McCready of Pearl Jam, lead singer Layne Staley of Alice in Chains, drummer Barrett Martin of Screaming Trees, and bassist John Baker Saunders. Mad Season released only one album, Above, in March 1995.","url":"https://en.wikipedia.org/wiki/Mad_Season_(band)"},"l7":{"title":"L7 (band)","desc":"American punk rock band","text":"L7 is an American punk rock band founded in Los Angeles, California, first active from 1985 to 2001 and re-formed in 2014. The group currently consists of Suzi Gardner, Donita Sparks, Dee Plakas and Janis Tanaka. L7 has released seven studio albums and has toured widely in the United States, Europe, Japan, Australia, and South America. \"Pretend We're Dead\" was heavily played on United States alternative radio and entered the top 10 on the Billboard Modern Rock chart in 1992.","url":"https://en.wikipedia.org/wiki/L7_(band)"},"stonetemple":{"title":"Stone Temple Pilots","desc":"American rock band","text":"Stone Temple Pilots, commonly abbreviated as STP, are an American rock band formed in San Diego, California, in 1989. Originally consisting of lead vocalist Scott Weiland, drummer Eric Kretz, and brothers Dean (guitar) and Robert DeLeo (bass), the band's lineup remained unchanged from its formation until the firing of Weiland in February 2013. Linkin Park vocalist Chester Bennington joined the band in May 2013 but left amicably in November 2015.","url":"https://en.wikipedia.org/wiki/Stone_Temple_Pilots"},"bush":{"title":"Bush (British band)","desc":"British rock band","text":"Bush are an English rock band formed in London in 1992. As of 2026, their lineup consists of lead vocalist and rhythm guitarist Gavin Rossdale, lead guitarist Chris Traynor, bassist Corey Britz, and drummer Nik Hughes.","url":"https://en.wikipedia.org/wiki/Bush_(British_band)"},"silverchair":{"title":"Silverchair","desc":"Australian rock band","text":"Silverchair were an Australian rock band, which formed in 1992 as Innocent Criminals in Newcastle, New South Wales, with Daniel Johns on vocals and guitars, Ben Gillies on drums, and Chris Joannou on bass guitar. The group got their big break in mid-1994 when they won a national demo competition conducted by SBS TV show Nomad and ABC radio station Triple J. The band was signed by Murmur and were successful in Australia and internationally.","url":"https://en.wikipedia.org/wiki/Silverchair"},"jesuslizard":{"title":"The Jesus Lizard","desc":"American alternative rock band","text":"The Jesus Lizard is an American rock band formed in 1987 in Austin, Texas by vocalist David Yow, guitarist Duane Denison, and bassist David Wm. Sims. They relocated to Chicago in 1989 and began working with producer Steve Albini and Touch and Go Records. \" The albums Goat (1991) and Liar (1992) have since been recognized as two of the most significant noise rock albums of the era.","url":"https://en.wikipedia.org/wiki/The_Jesus_Lizard"},"bigblack":{"title":"Big Black","desc":"American punk rock band","text":"Big Black was an American punk rock band from Evanston, Illinois, active from 1981 to 1987. Founded first as a solo project by singer and guitarist Steve Albini, the band became a trio with an initial lineup that included guitarist Santiago Durango and bassist Jeff Pezzati, both of Naked Raygun. In 1985, Pezzati was replaced by Dave Riley, who played on Big Black's two full-length studio albums, Atomizer (1986) and Songs About Fucking (1987).","url":"https://en.wikipedia.org/wiki/Big_Black"},"butthole":{"title":"Butthole Surfers","desc":"American rock band","text":"Butthole Surfers are an American rock band formed in San Antonio, Texas, by singer Gibby Haynes and guitarist Paul Leary in 1981. The band has had numerous personnel changes, but its core lineup of Haynes, Leary, and drummer King Coffey remained consistent since 1983. Teresa Nervosa served as second drummer, playing alongside Coffey from 1983 to 1985, 1986 to 1989, and 2009. The band had also employed a variety of bass players, most notably Jeff Pinkus.","url":"https://en.wikipedia.org/wiki/Butthole_Surfers"},"helmet":{"title":"Helmet (band)","desc":"American alternative metal band","text":"Helmet is an American alternative metal band from New York City formed in 1989 by vocalist and lead guitarist Page Hamilton. Helmet has had numerous lineup changes with Hamilton as the only constant member. Since 2010, the band has consisted of Hamilton, drummer Kyle Stevenson, guitarist Dan Beeman and bassist Dave Case.","url":"https://en.wikipedia.org/wiki/Helmet_(band)"},"thebreeders":{"title":"The Breeders","desc":"American alternative rock band","text":"The Breeders are an American alternative rock band based in Dayton, Ohio, consisting of members Kim Deal, her twin sister Kelley Deal, Josephine Wiggs, and Jim Macpherson (drums).","url":"https://en.wikipedia.org/wiki/The_Breeders"},"placebo":{"title":"Placebo (band)","desc":"British alternative rock band","text":"Placebo are a British alternative rock band, formed in London in 1994 by vocalist-guitarist Brian Molko and bassist-guitarist Stefan Olsdal, who have remained the two constant members, with three full-time drummers throughout the band's existence.","url":"https://en.wikipedia.org/wiki/Placebo_(band)"},"garbage":{"title":"Garbage (band)","desc":"American rock band","text":"Garbage is an American rock band formed in 1993 in Madison, Wisconsin. The band's line-up, consisting of Scottish musician Shirley Manson (vocals) and American musicians Duke Erikson, Steve Marker, and Butch Vig, has remained unchanged since its inception. All four members are involved in songwriting and production. Garbage has sold over 17 million albums worldwide.","url":"https://en.wikipedia.org/wiki/Garbage_(band)"},"pavement":{"title":"Pavement (band)","desc":"American indie rock band","text":"Pavement is an American indie rock band that formed in Stockton, California in 1989. For most of their career, the group consisted of vocalist and guitarist Stephen Malkmus, guitarist and vocalist Scott Kannberg, bassist Mark Ibold, drummer Steve West and vocalist and multi-instrumentalist Bob Nastanovich. Initially conceived as a recording project, the band at first avoided press or live performances, while attracting considerable underground attention with their early releases.","url":"https://en.wikipedia.org/wiki/Pavement_(band)"},"builttospill":{"title":"Built to Spill","desc":"American indie rock band","text":"Built to Spill is an American indie rock band that was formed in Boise, Idaho, in 1992. Centered on lead vocalist and guitarist Doug Martsch, the only permanent member, Built to Spill has released nine albums since its inception. Martsch originally envisioned the band to feature a changing set of backing musicians for each album, but eventually settled with a stable lineup for over a decade before returning to his original plan in 2012.","url":"https://en.wikipedia.org/wiki/Built_to_Spill"},"weezer":{"title":"Weezer","desc":"American rock band","text":"Weezer is an American rock band formed in Los Angeles, California, in 1992. Since 2001, the band has consisted of Rivers Cuomo, Patrick Wilson (drums), Brian Bell, and Scott Shriner. They have sold 10 million albums in the United States and over 35 million worldwide.","url":"https://en.wikipedia.org/wiki/Weezer"},"thecranberries":{"title":"The Cranberries","desc":"Irish rock band","text":"The Cranberries were an Irish rock band formed in Limerick in 1989. The band was composed of lead vocalist/guitarist Dolores O'Riordan, guitarist Noel Hogan, bassist Mike Hogan and drummer Fergal Lawler; O'Riordan replaced founding member Niall Quinn in 1990. The band classified themselves as an alternative rock group, but their sound blended elements of indie rock, jangle pop, dream pop, folk rock, post-punk, and pop rock.","url":"https://en.wikipedia.org/wiki/The_Cranberries"},"bigstar":{"title":"Big Star","desc":"American rock band","text":"Big Star was an American rock band formed in Memphis, Tennessee in 1971 by Alex Chilton, Chris Bell, Jody Stephens (drums), and Andy Hummel (bass). They have been described as the \"quintessential American power pop band\", and \"one of the most mythic and influential cult acts in all of rock & roll\". In its first era, the band's musical style drew influence from 1960s acts such as the Beatles and the Byrds, pioneering a style that foreshadowed the alternative rock of the 1980s and 1990s.","url":"https://en.wikipedia.org/wiki/Big_Star"},"muse":{"title":"Muse (band)","desc":"English rock band","text":"Muse are an English rock band from Teignmouth, Devon, formed in 1994. The band consists of Matt Bellamy, Chris Wolstenholme, and Dominic Howard.","url":"https://en.wikipedia.org/wiki/Muse_(band)"},"arcticmonkeys":{"title":"Arctic Monkeys","desc":"English rock band","text":"Arctic Monkeys are an English rock band formed in Sheffield in 2002. They comprise lead singer and guitarist Alex Turner, drummer Matt Helders, guitarist Jamie Cook and bassist Nick O'Malley, who replaced co-founder and original bassist Andy Nicholson in 2006. Though initially associated with the short-lived landfill indie movement, Arctic Monkeys were one of the earliest bands to come to public attention via the Internet, during the emerging \"blog rock\" era.","url":"https://en.wikipedia.org/wiki/Arctic_Monkeys"},"strokes":{"title":"The Strokes","desc":"American indie rock band","text":"The Strokes are an American rock band from New York City that formed in 1998. ; bassist Nikolai Fraiture; and drummer Fabrizio Moretti. They were a leading group of the early-2000s garage rock revival and post-punk revival movements.","url":"https://en.wikipedia.org/wiki/The_Strokes"},"whitestripes":{"title":"The White Stripes","desc":"American rock duo (1997–2011)","text":"The White Stripes were an American rock duo formed in Detroit, Michigan, in 1997. The group consisted of Jack White and Meg White. They were a leading group of the 2000s indie and garage rock revivals.","url":"https://en.wikipedia.org/wiki/The_White_Stripes"},"kingsofleon":{"title":"Kings of Leon","desc":"American rock band","text":"Kings of Leon is an American rock band formed in Mount Juliet, Tennessee, in 1999. The band consists of brothers Caleb, Nathan, and Jared Followill; and their cousin Matthew Followill.","url":"https://en.wikipedia.org/wiki/Kings_of_Leon"},"blackkeys":{"title":"The Black Keys","desc":"American rock duo","text":"The Black Keys are an American rock duo formed in Akron, Ohio, in 2001. The group consists of Dan Auerbach and Patrick Carney (drums). The duo began as an independent act, recording music in basements and self-producing their records, before they eventually emerged as one of the most popular garage rock artists during a second wave of the genre's revival in the 2000s. L. Burnside, Howlin' Wolf, and Robert Johnson.","url":"https://en.wikipedia.org/wiki/The_Black_Keys"},"royalblood":{"title":"Royal Blood (band)","desc":"English rock duo","text":"Royal Blood are an English rock duo formed in Worthing in 2011. The lineup consists of Mike Kerr and Ben Thatcher (drums). Their signature sound is built around Kerr's bass playing style, which sees him using various effects pedals and amps to make his bass guitar sound like an electric guitar and bass guitar at the same time. The duo were signed by Warner Chappell Music in 2013 and have since released four studio albums: Royal Blood (2014), How Did We Get So Dark?","url":"https://en.wikipedia.org/wiki/Royal_Blood_(band)"},"gretavanfleet":{"title":"Greta Van Fleet","desc":"American rock band","text":"Greta Van Fleet is an American rock band formed in Frankenmuth, Michigan, in 2012. The band consists of vocalist Josh Kiszka, guitarist Jake Kiszka, bassist/keyboardist Sam Kiszka, and drummer Danny Wagner. The Kiszkas are brothers, and Josh and Jake Kiszka are identical twins. Greta Van Fleet was signed to Lava Records in March 2017, and a month later they released their debut studio EP, Black Smoke Rising.","url":"https://en.wikipedia.org/wiki/Greta_Van_Fleet"},"rosettatharpe":{"title":"Sister Rosetta Tharpe","desc":"American gospel and rock musician (1915–1973)","text":"Sister Rosetta Tharpe was an American singer, songwriter, and guitarist. She gained popularity in the 1930s and 1940s with her gospel recordings, characterized by a unique mixture of spiritual lyrics and electric guitar. She was rooted in a pentecostal church and became the first great recording star of gospel music, and was among the first gospel musicians to appeal to rhythm and blues and rock and roll audiences, later being referred to as \"the original soul sister\" and \"the Godmother of Rock and Roll\".","url":"https://en.wikipedia.org/wiki/Sister_Rosetta_Tharpe"},"charleypatton":{"title":"Charley Patton","desc":"American Delta blues musician (1891–1934)","text":"Charlie Patton, more often spelled Charley Patton, was an American Delta blues musician and songwriter. Considered by many to be the \"Father of the Delta Blues\", he created an enduring body of American music and inspired most Delta blues musicians. The musicologist Robert Palmer considered him one of the most important American musicians of the twentieth century.","url":"https://en.wikipedia.org/wiki/Charley_Patton"},"sonhouse":{"title":"Son House","desc":"American Delta blues singer-guitarist (1902–1988)","text":"Edward James \"Son\" House Jr. was an American Delta blues singer and guitarist, noted for his highly emotional style of singing and slide guitar playing.","url":"https://en.wikipedia.org/wiki/Son_House"},"elmorejames":{"title":"Elmore James","desc":"American blues guitarist, singer, songwriter and bandleader (1918–1963)","text":"Elmore James was an American blues guitarist, singer, songwriter, and bandleader. Noted for his use of loud amplification and his stirring voice, James was inducted into the Rock and Roll Hall of Fame in 1992. His slide guitar technique earned him the nickname \"King of the Slide Guitar\".","url":"https://en.wikipedia.org/wiki/Elmore_James"},"albertking":{"title":"Albert King","desc":"American blues musician (1923–1992)","text":"Albert King was an American guitarist and singer, who is often regarded as one of the greatest and most influential blues guitarists ever. He is perhaps best known for his popular and influential album Born Under a Bad Sign (1967) and its title track. B. B. King, Freddie King, and he, all unrelated, were known as the \"Three Kings of the Blues\". The left-handed Albert King was known for his \"deep, dramatic sound that was widely imitated by both blues and rock guitarists\".","url":"https://en.wikipedia.org/wiki/Albert_King"},"buddyguy":{"title":"Buddy Guy","desc":"American blues guitarist and singer (born 1936)","text":"George \"Buddy\" Guy is an American blues guitarist and singer-songwriter. , and John Mayer. In the 1960s, Guy played with Muddy Waters as a session guitarist at Chess Records and began a musical partnership with blues harp virtuoso Junior Wells.","url":"https://en.wikipedia.org/wiki/Buddy_Guy"},"fatsdomino":{"title":"Fats Domino","desc":"American pianist and singer (1928–2017)","text":"Antoine Caliste \"Fats\" Domino Jr. was an American singer-songwriter and pianist. One of the pioneers of rock and roll music, Domino sold more than 65 million records. Born in New Orleans to a French Creole family, Domino signed to Imperial Records in 1949. His first single \"The Fat Man\" is cited by some historians as the first rock and roll single and the first to sell more than 1 million copies.","url":"https://en.wikipedia.org/wiki/Fats_Domino"},"carlperkins":{"title":"Carl Perkins","desc":"American guitarist (1932–1998)","text":"Carl Lee Perkins was an American country and rockabilly guitarist, singer and songwriter. A rockabilly great and pioneer of rock and roll, he began his recording career at the Sun Studio in Memphis in 1954. Among his best known songs are \"Blue Suede Shoes\", \"Honey Don't\", \"Matchbox\" and \"Everybody's Trying to Be My Baby\".","url":"https://en.wikipedia.org/wiki/Carl_Perkins"},"johnnycash":{"title":"Johnny Cash","desc":"American country singer (1932–2003)","text":"John R. Cash was an American singer-songwriter. Most of his music contains themes of sorrow, moral tribulation, and redemption, especially songs from the later stages of his career. He was known for his deep, calm, bass-baritone voice, the distinctive sound of his backing band, the Tennessee Three, that was characterized by its train-like chugging guitar rhythms, a rebelliousness coupled with an increasingly somber and humble demeanor, and his free prison concerts.","url":"https://en.wikipedia.org/wiki/Johnny_Cash"},"eddiecochran":{"title":"Eddie Cochran","desc":"American rock and roll pioneer (1938–1960)","text":"Edward Ray Cochran was an American rock and roll musician. His songs, such as \"Twenty Flight Rock\", \"Summertime Blues\", \"C'mon Everybody\" and \"Somethin' Else\", captured teenage frustration and desire in the mid-1950s and early 1960s. He experimented with multitrack recording, distortion techniques and overdubbing, even on his earliest singles. Cochran played the guitar, piano, bass, and drums.","url":"https://en.wikipedia.org/wiki/Eddie_Cochran"},"genevincent":{"title":"Gene Vincent","desc":"American rock musician (1935–1971)","text":"Vincent Eugene Craddock, known as Gene Vincent, was an American rock-and-roll musician who pioneered the style of rockabilly. His 1956 top-10 hit with his backing band the Blue Caps, \"Be-Bop-a-Lula\", is considered a significant early example of rockabilly. His chart career was brief, especially in his home country of the US, where he notched three top-40 hits in 1956 and 1957 and never charted in the top 100 again.","url":"https://en.wikipedia.org/wiki/Gene_Vincent"},"royorbison":{"title":"Roy Orbison","desc":"American singer-songwriter (1936–1988)","text":"Roy Kelton Orbison was an American singer, songwriter and guitarist known for his distinctive and powerful voice, complex song structures, and dark, emotional ballads. Orbison's most successful periods were in the early 1960s and the late 1980s. Many of Orbison's songs conveyed vulnerability at a time when most male performers projected strength. He performed with minimal motion and in black clothes, matching his dyed black hair and dark sunglasses.","url":"https://en.wikipedia.org/wiki/Roy_Orbison"},"linkwray":{"title":"Link Wray","desc":"American guitarist (1929–2005)","text":"Fred Lincoln \"Link\" Wray Jr. was an American guitarist, songwriter, and vocalist who became popular in the late 1950s. His 1958 instrumental single \"Rumble\" reached the top 20 in the United States, and was one of the earliest songs in rock music to use distortion and tremolo.","url":"https://en.wikipedia.org/wiki/Link_Wray"},"theventures":{"title":"The Ventures","desc":"American instrumental band","text":"The Ventures are an American instrumental rock band formed in Tacoma, Washington, in 1958, by Don Wilson and Bob Bogle. The band, which was a quartet for most of its existence, helped to popularize the electric guitar across the world during the 1960s. While their popularity in the United States waned in the 1970s, the group remains especially revered in Japan, where they have toured regularly.","url":"https://en.wikipedia.org/wiki/The_Ventures"},"duaneeddy":{"title":"Duane Eddy","desc":"American guitarist (1938–2024)","text":"Duane Eddy was an American guitarist. In the late 1950s and early 1960s, he had a string of hit records produced by Lee Hazlewood which were noted for their characteristically \"twangy\" guitar sound, including \"Rebel-'Rouser\", \"Peter Gunn\", and \"Because They're Young\". He had sold 12 million records by 1963. His guitar style influenced the Ventures, the Shadows, the Beatles, Bruce Springsteen, Steve Earle, and Marty Stuart.","url":"https://en.wikipedia.org/wiki/Duane_Eddy"},"neilyoung":{"title":"Neil Young","desc":"Canadian and American musician (born 1945)","text":"Neil Percival Young is a Canadian and American singer-songwriter and musician. Young's deeply personal lyrics and signature high tenor singing voice define his long career. Young's often distorted electric guitar playing, especially with his backing band Crazy Horse, earned him the nickname \"Godfather of Grunge\" and led to his 1995 album Mirror Ball with Pearl Jam. He also plays piano and harmonica on many albums, which frequently combine folk, rock, country, and other musical genres.","url":"https://en.wikipedia.org/wiki/Neil_Young"},"theband":{"title":"The Band","desc":"Canadian and American rock band","text":"The Band were a Canadian and American rock band formed in Toronto, Ontario. It consisted of Rick Danko, Garth Hudson, Richard Manuel, and Robbie Robertson, all Canadian, and Levon Helm, an American. The Band's music combined elements of Americana, folk, rock, R&B, jazz and country, which influenced artists including George Harrison, Elton John, the Grateful Dead, Eric Clapton and Wilco.","url":"https://en.wikipedia.org/wiki/The_Band"},"fairport":{"title":"Fairport Convention","desc":"English folk rock group","text":"Fairport Convention are an English folk rock band, formed in 1967 by guitarists Richard Thompson and Simon Nicol, bassist Ashley Hutchings and drummer Shaun Frater. They started out influenced by North American folk rock, with a set list dominated by Bob Dylan and Joni Mitchell songs and a sound that earned them the nickname \"the British Jefferson Airplane\". Vocalists Judy Dyble and Iain Matthews joined them before the recording of their self-titled debut in 1968; afterwards, Dyble was replaced by Sandy Denny.","url":"https://en.wikipedia.org/wiki/Fairport_Convention"},"steeleye":{"title":"Steeleye Span","desc":"English folk rock band, formed 1969","text":"Steeleye Span are a British folk rock band formed in 1969 in England by Fairport Convention bass player Ashley Hutchings and established London folk club duo Tim Hart and Maddy Prior. The band were part of the 1970s British folk revival, and were commercially successful in that period, with four Top 40 albums and two hit singles: \"Gaudete\" and \"All Around My Hat\".","url":"https://en.wikipedia.org/wiki/Steeleye_Span"},"faces":{"title":"Faces (band)","desc":"English rock band","text":"Faces are an English rock band formed in London in 1969. They formed after Small Faces lead singer and guitarist Steve Marriott left to form Humble Pie, and the remaining Small Faces—bassist Ronnie Lane, drummer Kenney Jones, and keyboardist Ian McLagan—recruited lead singer Rod Stewart and guitarist Ronnie Wood, both formerly of the Jeff Beck Group, and shortened the band's name to Faces.","url":"https://en.wikipedia.org/wiki/Faces_(band)"},"smallfaces":{"title":"Small Faces","desc":"English rock band","text":"The Small Faces were an English rock and pop band from London, founded in 1965. The group originally consisted of singer/guitarist Steve Marriott, bassist Ronnie Lane, drummer Kenney Jones and keyboardist Jimmy Winston, with Ian McLagan replacing Winston in 1966. The band were initially one of the most acclaimed and influential mod groups of the mid-1960s, with hit singles such as \"Whatcha Gonna Do About It\" (1965), \"Sha-La-La-La-Lee\" and \"All or Nothing\".","url":"https://en.wikipedia.org/wiki/Small_Faces"},"zombies":{"title":"The Zombies","desc":"English rock band","text":"The Zombies were an English rock band formed in St Albans in 1962. Led by keyboardist/vocalist Rod Argent and lead vocalist Colin Blunstone, the group had their first British and American hit in 1964 with \"She's Not There\". In the US, two further singles—\"Tell Her No\" in 1965 and \"Time of the Season\" in 1968—were also successful.","url":"https://en.wikipedia.org/wiki/The_Zombies"},"love":{"title":"Love (band)","desc":"American rock group","text":"Love is an American rock band formed in Los Angeles in 1965. Led by Arthur Lee, the band's primary songwriter, they were one of the first racially diverse American rock bands. Their sound incorporated styles including psychedelic rock, folk rock and garage.","url":"https://en.wikipedia.org/wiki/Love_(band)"},"seeds":{"title":"The Seeds","desc":"American rock band","text":"The Seeds are an American psychedelic garage rock band that formed in Los Angeles, California in 1965, best known for their highest-charting single \"Pushin' Too Hard\". The band's classic lineup featured frontman Sky Saxon in lead vocals and bass guitar, along with guitarist Jan Savage, keyboardist Daryl Hooper and drummer Rick Andridge. In 1968, the band changed their name to Sky Saxon and the Seeds, with Savage and Andridge departing the band.","url":"https://en.wikipedia.org/wiki/The_Seeds"},"herbiehancock":{"title":"Herbie Hancock","desc":"American jazz pianist and composer (born 1940)","text":"Herbert Jeffrey Hancock is an American jazz musician, bandleader, and composer. He started his career with trumpeter Donald Byrd's group. Hancock soon joined the Miles Davis Quintet, where he helped to redefine the role of a jazz rhythm section and was one of the primary architects of the post-bop sound. In the 1970s, he experimented with jazz fusion, funk, and electro styles using a wide array of synthesizers and electronics.","url":"https://en.wikipedia.org/wiki/Herbie_Hancock"},"isleybrothers":{"title":"The Isley Brothers","desc":"American musical group","text":"The Isley Brothers are an American soul group originally from Cincinnati, Ohio, that began in 1954 as four young brothers performing gospel music until the death of one brother that same year. —initially disbanded but then reformed, sparking a decades-long career with various lineups.","url":"https://en.wikipedia.org/wiki/The_Isley_Brothers"},"curtismayfield":{"title":"Curtis Mayfield","desc":"American singer-songwriter (1942–1999)","text":"Curtis Lee Mayfield was an American singer-songwriter, guitarist, and record producer. Dubbed the Gentle Genius, he is considered one of the most influential musicians of soul and socially conscious African-American music. Mayfield first achieved success and recognition with the vocal group the Impressions during the civil rights movement of the late 1950s and the 1960s, and later worked as a solo artist.","url":"https://en.wikipedia.org/wiki/Curtis_Mayfield"},"gnr":{"title":"Guns N' Roses","desc":"American rock band","text":"A. Guns and Hollywood Rose. The classic lineup, Rose (vocals), Slash, Stradlin, Duff McKagan (bass), and Steven Adler (drums), was finalized in June 1985. After signing with Geffen Records in 1986, the band released its debut album Appetite for Destruction (1987). S. It produced three Billboard Hot 100 top-ten singles: \"Welcome to the Jungle\", \"Paradise City\", and the band's only number-one, \"Sweet Child o' Mine\".","url":"https://en.wikipedia.org/wiki/Guns_N'_Roses"},"cromags":{"title":"Cro-Mags","desc":"American hardcore punk band","text":"The Cro-Mags are an American hardcore punk band from New York City. They have released six studio albums. They were among the first bands to fuse hardcore punk with thrash metal. They were also a prototypical band for Krishnacore, a sub-sect of hardcore bands that adopt Krishna consciousness.","url":"https://en.wikipedia.org/wiki/Cro-Mags"},"howlin":{"title":"Howlin' Wolf","desc":"American blues singer, guitarist and harmonica player (1910–1976)","text":"Chester Arthur Burnett, better known by his stage name Howlin' Wolf, was an American blues singer, guitarist and harmonica player. He was at the forefront of transforming acoustic Delta blues into electric Chicago blues, and over a four-decade career, recorded blues, rhythm and blues, rock and roll, and psychedelic rock. He is regarded as one of the most influential blues musicians ever.","url":"https://en.wikipedia.org/wiki/Howlin'_Wolf"},"blink":{"title":"Blink-182","desc":"American rock band","text":"Blink-182 is an American rock band formed in Poway, California, in 1992. Its current and most widely recognized line-up consists of bassist and vocalist Mark Hoppus, guitarist and vocalist Tom DeLonge, and drummer Travis Barker. Though its sound has diversified throughout their career, its musical style, described as pop-punk, blends catchy pop melodies with fast-paced punk rock.","url":"https://en.wikipedia.org/wiki/Blink-182"},"janes":{"title":"Jane's Addiction","desc":"American rock band","text":"Jane's Addiction was an American rock band formed in Los Angeles in 1985. The band's best known line-up consisted of lead vocalist Perry Farrell, bassist Eric Avery, drummer Stephen Perkins and guitarist Dave Navarro. Jane's Addiction was one of the first bands from the early 1990s alternative rock movement to gain commercial success.","url":"https://en.wikipedia.org/wiki/Jane's_Addiction"},"sly":{"title":"Sly and the Family Stone","desc":"American funk and soul band (1966–1983)","text":"Sly and the Family Stone was an American band formed in San Francisco, California, in 1966 and active until 1983. Their work, which blended elements of funk, soul, psychedelic rock, gospel, and R&B, became a pivotal influence on subsequent American popular music. Their core line-up was led by singer-songwriter, producer, and multi-instrumentalist Sly Stone, and included Stone's siblings Freddie Stone and Rose Stone alongside Cynthia Robinson, Greg Errico (drums), Jerry Martini (saxophone), and Larry Graham.","url":"https://en.wikipedia.org/wiki/Sly_and_the_Family_Stone"},"flowertravellin":{"title":"Flower Travellin' Band","desc":"Japanese band","text":"Flower Travellin' Band was a Japanese rock band that was formed in 1967. They were connected to Japan's counterculture movement and noted for their mixture of early heavy metal with psychedelic and progressive rock. They received wide acclaim from critics but failed to achieve commercial success and separated in 1973 to pursue individual careers. The band reunited in late 2007, but permanently disbanded after the 2011 death of vocalist Joe Yamanaka.","url":"https://en.wikipedia.org/wiki/Flower_Travellin'_Band"},"happyend":{"title":"Happy End (band)","desc":"Japanese folk rock band","text":"Happy End was a Japanese folk rock band active from 1969 to 1972. Composed of Haruomi Hosono, Takashi Matsumoto, Eiichi Ohtaki and Shigeru Suzuki, the band's pioneering sound was regarded as avant-garde to most Japanese at the time. They are considered to be among the most influential artists in Japanese music, with Mikiki crediting them with laying the foundation for Japanese rock.","url":"https://en.wikipedia.org/wiki/Happy_End_(band)"},"kino":{"title":"Kino (band)","desc":"Soviet rock band","text":"Kino is a Russian rock band formed in Leningrad in 1981. The band was co-founded and headed by Viktor Tsoi, who wrote the music and lyrics for almost all of the band's songs, until his death in 1990. Over the course of eight years, Kino released over ninety songs spanning over seven studio albums, as well as releasing a few compilations and live albums.","url":"https://en.wikipedia.org/wiki/Kino_(band)"},"aria":{"title":"Aria (band)","desc":"Russian heavy metal band","text":"Aria is a Russian heavy metal band that was formed in 1985 in Moscow. Although it was not the first Soviet band to play hard rock, Aria was the first to break through to mainstream media and commercial success. According to several public polls, Aria ranks among top 10 most popular Russian rock bands. Their sound resembled that of NWOBHM bands, for which they were dubbed the \"Russian Iron Maiden\" in the media.","url":"https://en.wikipedia.org/wiki/Aria_(band)"},"mastershammer":{"title":"Master's Hammer","desc":"Czech black metal band","text":"Master's Hammer is a Czech black metal band formed in Prague in 1983. They were active, with several lineup changes, until 1995, and again from 2009 until 2020. They have released eight studio albums, five demos, one EP, two split albums, two live albums, and several compilations.","url":"https://en.wikipedia.org/wiki/Master's_Hammer"},"vildhjarta":{"title":"Vildhjarta","desc":"Swedish progressive metal band","text":"Vildhjarta is a Swedish progressive metal band from Hudiksvall, formed in 2005. The band plays in a Meshuggah-influenced djent-style employing heavily-down-tuned guitars, as well as harmonic minor chord progressions, jarring staccato riffs, and layers of reverberant guitars and atmospheres. The band currently consists of guitarist Calle Thomér, vocalist Vilhelm Bladin, and drummer Buster Odeholm.","url":"https://en.wikipedia.org/wiki/Vildhjarta"},"riot":{"title":"Riot V","desc":"American heavy metal band","text":"Riot V, formerly known as Riot, is an American heavy metal band formed in New York City in 1975 by guitarist Mark Reale. Achieving peak success and popularity during the early 1980s, the band has continued a long-running successful career. Riot started out as straightforward heavy metal, but since their 1988 release Thundersteel, their style has shifted towards power metal.","url":"https://en.wikipedia.org/wiki/Riot_V"},"spocksbeard":{"title":"Spock's Beard","desc":"American progressive rock band","text":"Spock's Beard is an American progressive rock band from Los Angeles, formed in 1992 by brothers Neal and Alan Morse (guitars), John Ballard (bass), and Nick D'Virgilio (drums). Ballard was replaced by Dave Meros before the release of their debut album, The Light (1995), and Ryo Okumoto (keyboards) joined soon after. Neal Morse left the band following the release of their sixth album, Snow (2002), and D'Virgilio took over as the band's frontman.","url":"https://en.wikipedia.org/wiki/Spock's_Beard"},"staticx":{"title":"Static-X","desc":"American industrial metal band","text":"Static-X is an American industrial metal band from Los Angeles, California, formed in 1994. The line-up has fluctuated over the years, but was long held constant with band founder, frontman, vocalist and rhythm guitarist Wayne Static until his death in 2014.","url":"https://en.wikipedia.org/wiki/Static-X"},"gbh":{"title":"GBH (band)","desc":"British punk band","text":"GBH are an English punk rock band, formed in 1978 by vocalist Colin Abrahall, guitarist Colin \"Jock\" Blyth, bassist Sean McCarthy and drummer Andy \"Wilf\" Williams.","url":"https://en.wikipedia.org/wiki/GBH_(band)"},"b52s":{"title":"The B-52s","desc":"American rock band","text":"The B-52s are an American rock band formed in Athens, Georgia, in 1976. The original lineup consisted of Fred Schneider, Kate Pierson, Cindy Wilson, Ricky Wilson, and Keith Strickland. Ricky Wilson died of AIDS-related illness in 1985, and Strickland permanently switched from drums to lead guitar. The band has also added various auxiliary members for albums and live performances.","url":"https://en.wikipedia.org/wiki/The_B-52s"},"tad":{"title":"Tad (band)","desc":"American grunge band","text":"Tad was an American rock band from Seattle, Washington, formed in 1988 by Tad Doyle. They are often recognized as one of the first grunge bands.","url":"https://en.wikipedia.org/wiki/Tad_(band)"},"tbonewalker":{"title":"T-Bone Walker","desc":"American blues musician and singer-songwriter (1910–1975)","text":"Aaron Thibeaux \"T-Bone\" Walker was an American blues musician, composer, songwriter, and bandleader, who was a pioneer and innovator of the jump blues, West Coast blues, and electric blues sounds. In 2018 Rolling Stone magazine ranked him No. 67 on its list of \"The 100 Greatest Guitarists of All Time\".","url":"https://en.wikipedia.org/wiki/T-Bone_Walker"},"billhaley":{"title":"Bill Haley & His Comets","desc":"American rock and roll band","text":"Bill Haley & His Comets were an American rock and roll band formed in 1947 and continuing until Haley's death in 1981. The band was also known as Bill Haley and the Comets and Bill Haley's Comets. From late 1954 to late 1956, the group recorded nine top-20 singles, one of which was number one and three that were top ten. The single \"Rock Around the Clock\" was the best-selling rock single in the history of the genre and maintained that position for several years.","url":"https://en.wikipedia.org/wiki/Bill_Haley_%26_His_Comets"}};
